const DATA=[
/* ---------- BERLIM · SÓ NESTA DATA ---------- */
{c:"berlin",k:"data",n:"9 de novembro — aniversário da queda do Muro",o:"Mauerfall-Jahrestag",a:"Cidade toda",d:"Dia todo",p:"Grátis",w:"9/11/2026 cai numa segunda e você estará em Berlim. É o dia em que a cidade relembra 1989 — e também 1918, 1923 e 1938, o chamado “dia do destino” alemão. O Memorial da Bernauer Straße e o Gleis 17 costumam ter coroas, flores e programação especial; é uma das experiências mais densas que Berlim oferece, e só acontece nessa data.",t:["história","ao ar livre","grátis","imperdível","solo"]},
{c:"berlin",k:"data",n:"Weihnachtsmarkt Landsberger Allee (aberto desde 31/10)",o:"Weihnachtsmarkt Landsberger Allee",a:"Lichtenberg",d:"2–3h",p:"Grátis (consome quem come)",w:"Funciona de 31/10 a 27/12 — datas de 2026 confirmadas —, ou seja: pega a sua janela inteira, enquanto os mercados clássicos de Berlim só abrem em 23/11; o Winterwelt do Potsdamer Platz pode abrir antes, então vale conferir. Chance de tomar Glühwein, comer Bratwurst, Reibekuchen e Baumstriezel em clima natalino antes de os mercados clássicos abrirem (Gendarmenmarkt, Roter Rathaus e Humboldt Forum abrem depois da sua passagem).",t:["noite","comida","ao ar livre","família","verificar"]},
{c:"berlin",k:"data",n:"Domingo 08/11 — feiras e karaokê no Mauerpark",o:"Flohmarkt Mauerpark + Karaoke",a:"Prenzlauer Berg",d:"3–4h",p:"Grátis (levar troco)",w:"Só existe no domingo e você está na cidade num domingo. O maior mercado de pulgas de Berlim toma o parque, e no anfiteatro ao lado rola karaokê público desde o meio-dia — plateia sentada na grama, gente cantando mal de propósito. É Berlim no estado puro.",t:["ao ar livre","grátis","grupo","compras"]},

/* ---------- BERLIM · ARTE & MUSEUS ---------- */
{c:"berlin",k:"arte",n:"Ilha dos Museus (conjunto)",o:"Museumsinsel",a:"Mitte",d:"Meio dia",p:"€€€",w:"Cinco museus numa ilha UNESCO no meio do Spree, mais a Berliner Dom ao lado. Vale comprar o Museum Pass Berlin ou o Berlin WelcomeCard se você for entrar em dois ou três. ATENÇÃO: o Pergamonmuseum fechou em outubro de 2023 para uma reforma de 14 a 20 anos — a ala norte deve reabrir por volta de 2027. O circuito real hoje é Neues Museum, Alte Nationalgalerie, Bode e Altes.",t:["chuva","grupo","imperdível","verificar"]},
{c:"berlin",k:"arte",n:"Neues Museum — busto de Nefertiti",o:"Neues Museum",a:"Museumsinsel",d:"2–3h",p:"€€€",w:"O substituto natural do Pergamon: é aqui que está o busto de Nefertiti, além do acervo egípcio e do museu da pré-história. O prédio reconstruído por David Chipperfield com as ruínas da guerra preservadas já vale a visita por si só.",t:["chuva","grupo","imperdível"]},
{c:"berlin",k:"arte",n:"Alte Nationalgalerie",o:"Alte Nationalgalerie",a:"Museumsinsel",d:"2h",p:"€€",w:"Pintura e escultura do século XIX, com Caspar David Friedrich, Menzel e a coleção de impressionistas alemães. É o museu mais bonito da ilha por dentro e costuma ser o menos cheio do conjunto.",t:["chuva","arte"]},
{c:"berlin",k:"arte",n:"Bode-Museum",o:"Bode-Museum",a:"Museumsinsel",d:"1h30",p:"€€",w:"Escultura, arte bizantina e uma coleção de moedas enorme, numa ponta de ilha com vista para o Spree. Entrada em cúpula e passagem sobre a água — combina bem com fim de tarde.",t:["chuva","arte","vista"]},
{c:"berlin",k:"arte",n:"Altes Museum",o:"Altes Museum",a:"Museumsinsel",d:"1h",p:"€€",w:"Antiguidades clássicas gregas e romanas no prédio neoclássico de Schinkel, com a rotunda de colunas. Opção curta e boa quando o tempo aperta.",t:["chuva","arte"]},
{c:"berlin",k:"arte",n:"Humboldt Forum",o:"Humboldt Forum",a:"Mitte",d:"2–3h",p:"Grátis (exposições temporárias pagas)",w:"O Berliner Schloss reconstruído, com o Museu Etnológico e o Museu de Arte Asiática por dentro. É polêmico justamente por reunir acervo colonial — as exposições assumem esse debate. Terraço com vista ótima e entrada gratuita na área de exposições permanentes.",t:["chuva","grátis","arte","vista"]},
{c:"berlin",k:"arte",n:"Gemäldegalerie",o:"Gemäldegalerie",a:"Kulturforum, Tiergarten",d:"2–3h",p:"€€",w:"Pintura europeia do século XIII ao XVIII: Rembrandt, Vermeer, Botticelli, Dürer, Cranach. É a coleção de pintura antiga que a cidade tem e costuma ser ignorada pelos turistas, o que é uma vantagem.",t:["chuva","arte"]},
{c:"berlin",k:"arte",n:"Neue Nationalgalerie",o:"Neue Nationalgalerie",a:"Kulturforum, Tiergarten",d:"1h30",p:"€€",w:"O pavilhão de vidro de Mies van der Rohe — arquitetura icônica com o acervo de arte moderna do século XX. Certo dia de arte contemporânea em Berlim começa ou termina aqui.",t:["chuva","arte","arquitetura"]},
{c:"berlin",k:"arte",n:"Kunstgewerbemuseum",o:"Kunstgewerbemuseum",a:"Kulturforum",d:"1h30",p:"€€",w:"Design e artes decorativas, do medieval ao industrial, incluindo o traje de coroação e móveis. Bom se você gosta de objeto e ofício, não só de quadro.",t:["chuva","arte","design"]},
{c:"berlin",k:"arte",n:"Hamburger Bahnhof",o:"Hamburger Bahnhof – Nationalgalerie der Gegenwart",a:"Moabit",d:"2–3h",p:"€€€",w:"Arte contemporânea numa antiga estação de trem: Beuys, Warhol, Kiefer e o Rieckhallen. É o museu de contemporânea mais importante da cidade — o mais próximo do que o Pompidou fazia em Paris.",t:["chuva","arte","imperdível"]},
{c:"berlin",k:"arte",n:"Berlinische Galerie",o:"Berlinische Galerie",a:"Kreuzberg",d:"2h",p:"€€",w:"Arte feita em Berlim, do século XIX à produção atual, com fotografia e arquitetura. O acervo é literalmente sobre a cidade que você está andando — combina muito com o resto do dia em Kreuzberg.",t:["chuva","arte"]},
{c:"berlin",k:"arte",n:"KW Institute for Contemporary Art",o:"KW Institute for Contemporary Art",a:"Mitte (Auguststraße)",d:"1h30",p:"€€",w:"Arte contemporânea num prédio de fábrica em Mitte, referência desde os anos 1990 (foi aqui que nasceu a Bienal de Berlim). Programação ousada e o café no pátio é bom.",t:["chuva","arte","alternativo"]},
{c:"berlin",k:"arte",n:"Gropius Bau",o:"Gropius Bau",a:"Mitte (Niederkirchnerstraße)",d:"2h",p:"€€",w:"Edifício renascentista de 1881 que virou casa de grandes exposições temporárias, do circuito internacional. Fica ao lado da Topografia do Terror — dá para fazer os dois no mesmo bloco.",t:["chuva","arte"]},
{c:"berlin",k:"arte",n:"C/O Berlin",o:"C/O Berlin",a:"Charlottenburg (Amerika Haus)",d:"1h30",p:"€€",w:"Fotografia e imagem em três andares do antigo Amerika Haus, do lado do Zoo. Costuma trazer mostras de nomes grandes — foi por onde passou boa parte da fotografia autoral contemporânea.",t:["chuva","arte","fotografia"]},
{c:"berlin",k:"arte",n:"Fotografiska Berlin",o:"Fotografiska Berlin",a:"Mitte (Tacheles)",d:"1h30",p:"€€",w:"Fotografia num prédio histórico (o antigo centro cultural Tacheles) e aberto até tarde — é uma das poucas opções de museu À NOITE em Berlim. Funciona bem como programa de fim de tarde antes do jantar.",t:["chuva","arte","fotografia","noite"]},
{c:"berlin",k:"arte",n:"Museum für Naturkunde",o:"Museum für Naturkunde",a:"Mitte (Invalidenstraße)",d:"2h",p:"€€",w:"O maior esqueleto de dinossauro montado do mundo (um Brachiosaurus), o fóssil mais famoso da história (o Archaeopteryx) e a maior coleção de meteoritos da Alemanha. Excelente mesmo para quem “não gosta de museu”.",t:["chuva","família","imperdível"]},
{c:"berlin",k:"arte",n:"Deutsches Technikmuseum",o:"Deutsches Technikmuseum",a:"Kreuzberg",d:"3h",p:"€€",w:"Trem de carga saindo do prédio, aviões pendurados, computadores, telefones, moinhos. Interativo e enorme — subestimado pelos turistas e muito bom para entender a Alemanha industrial.",t:["chuva","família","tecnologia"]},
{c:"berlin",k:"arte",n:"DDR Museum",o:"DDR Museum",a:"Mitte",d:"1h30",p:"€€",w:"Como era a vida cotidiana na Alemanha Oriental: carro Trabant, comida, escola, esporte, espionagem. É interativo e abre tudo, bom no mesmo dia do Muro e do Checkpoint Charlie.",t:["chuva","história","interativo"]},
{c:"berlin",k:"arte",n:"Museu Judaico",o:"Jüdisches Museum Berlin",a:"Kreuzberg",d:"2–3h",p:"€€",w:"O prédio de Daniel Libeskind é em si a exposição: corredores tortos, vazios e o “Jardim do Exílio”. A coleção conta 2 mil anos de vida judaica na Alemanha, não só a Shoá.",t:["chuva","arte","história","imperdível"]},
{c:"berlin",k:"arte",n:"Museum Berggruen",o:"Museum Berggruen",a:"Charlottenburg",d:"1h",p:"€€",w:"Coleção de Picasso, Klee, Matisse e Giacometti. ATENÇÃO: está fechado desde setembro de 2022 para uma reforma pesada do Stülerbau, com reabertura prevista só para o fim de 2026 ou 2027 — não conte com ele nesta viagem. O que fica ao lado e abre é o Sammlung Scharf-Gerstenberg.",t:["chuva","arte","fechado"]},
{c:"berlin",k:"arte",n:"Sammlung Scharf-Gerstenberg",o:"Sammlung Scharf-Gerstenberg",a:"Charlottenburg",d:"1h",p:"€€",w:"Surrealismo e arte fantástica do simbolismo ao pós-guerra, em prédio gêmeo ao Berggruen. Se o Berggruen estiver fechado, este é o plano B no mesmo endereço.",t:["chuva","arte"]},
{c:"berlin",k:"arte",n:"Brücke-Museum",o:"Brücke-Museum",a:"Dahlem",d:"1h",p:"€€",w:"Pequeno e dedicado ao expressionismo alemão do grupo Die Brücke, em meio ao bairro verde de Dahlem. Junte com o Alliiertenmuseum e o jardim botânico no mesmo dia.",t:["chuva","arte","longe"]},
{c:"berlin",k:"arte",n:"Schloss Charlottenburg",o:"Schloss Charlottenburg",a:"Charlottenburg",d:"2–3h",p:"€€€",w:"O maior palácio de Berlim: rococó, porcelana, a câmara de ouro e o aposento de Frederico o Grande. O jardim atrás é grátis e ótimo para caminhar, mesmo em novembro.",t:["chuva","arte","história","jardim"]},
{c:"berlin",k:"arte",n:"Zitadelle Spandau",o:"Zitadelle Spandau",a:"Spandau",d:"2h",p:"€€",w:"Fortaleza renascentista entre quatro braços de rio, com quatro museus dentro e a torre de Julius onde se pode subir. Ponto bem fora do circuito turístico — sensação de descobrir algo sozinho.",t:["arte","história","longe","bicicleta"]},
{c:"berlin",k:"arte",n:"Museum für Kommunikation",o:"Museum für Kommunikation",a:"Mitte",d:"1h30",p:"€€",w:"História dos correios, telégrafo, telefone e selos, em prédio bonito na Leipziger Straße. Casa boa de tarde e geralmente vazia.",t:["chuva","tecnologia"]},
{c:"berlin",k:"arte",n:"Julia Stoschek Collection",o:"Julia Stoschek Collection",a:"Mitte (Auguststraße)",d:"1h30",p:"Grátis",w:"Coleção privada de videoarte e instalação, gratuita — uma das melhores paradas de arte contemporânea para quem gosta de imagem em movimento. ATENÇÃO: a sede de Berlim fechou; a coleção continua em Düsseldorf, na Julia Stoschek Foundation. Em Berlim, não conte com ela.",t:["chuva","grátis","arte","fechado"]},
/* ---------- BERLIM · HISTÓRIA & MEMÓRIA ---------- */
{c:"berlin",k:"historia",n:"Portão de Brandemburgo",o:"Brandenburger Tor",a:"Mitte",d:"30min",p:"Grátis",w:"O marco zero simbólico da cidade e o ponto onde Leste e Oeste se encontram. Vá de dia para ver a praça vazia e volte à noite, quando fica iluminado — a diferença é grande. Está a dois passos do Reichstag e do Memorial do Holocausto.",t:["ao ar livre","grátis","noite","imperdível"]},
{c:"berlin",k:"historia",n:"Reichstag — cúpula de vidro",o:"Reichstagskuppel",a:"Mitte",d:"1h30",p:"Grátis (agendar antes)",w:"A cúpula de Norman Foster é gratuita, mas exige agendamento online com antecedência e documento com foto. Do topo você tem uma vista de 360° que explica a geografia da cidade de uma vez. Vale a pena insistir na reserva.",t:["grátis","vista","imperdível","agendar"]},
{c:"berlin",k:"historia",n:"Memorial do Holocausto",o:"Denkmal für die ermordeten Juden Europas",a:"Mitte",d:"1h–1h30",p:"Grátis",w:"As 2.711 lajes de concreto criam um labirinto em que o chão ondula e a cidade some — o arquiteto Peter Eisenman desenhou a experiência física da desorientação. Debaixo, o “Ort der Information” documenta as vítimas com nomes e famílias. Silencioso e forte.",t:["ao ar livre","grátis","solo","imperdível"]},
{c:"berlin",k:"historia",n:"Topografia do Terror",o:"Topographie des Terrors",a:"Mitte (Niederkirchnerstraße)",d:"1h30–2h",p:"Grátis",w:"Exposição ao ar livre e centro de documentação nos terrenos onde ficavam a Gestapo, a SS e o RSHA. É a melhor exposição gratuita da cidade sobre como funcionava o aparato nazista, incluindo o trecho do Muro que passa atrás.",t:["grátis","história","chuva","imperdível"]},
{c:"berlin",k:"historia",n:"Checkpoint Charlie",o:"Checkpoint Charlie",a:"Mitte (Friedrichstraße)",d:"1h",p:"Grátis (museu pago)",w:"O posto de fronteira mais famoso da Guerra Fria, hoje meio turístico demais — mas histórico e gratuito. O Mauermuseum ao lado conta a história das fugas de forma às vezes caótica, porém comovente.",t:["história","grátis"]},
{c:"berlin",k:"historia",n:"Memorial do Muro — Bernauer Straße",o:"Gedenkstätte Berliner Mauer",a:"Wedding/Mitte",d:"2h",p:"Grátis",w:"O lugar onde a história do Muro é melhor contada: trecho preservado com a faixa da morte, torre de observação, a Capela da Reconciliação e o centro de documentação. Aqui a janela de 9 de novembro tem programação especial — priorize este lugar no dia 9.",t:["ao ar livre","grátis","história","imperdível"]},
{c:"berlin",k:"historia",n:"East Side Gallery",o:"East Side Gallery",a:"Friedrichshain",d:"1h–1h30",p:"Grátis",w:"1,3 km de Muro transformados na maior galeria de arte a céu aberto do mundo, com o famoso beijo entre Honecker e Brejnev. Caminhe no sentido Mühlenstraße → Ostbahnhof e saia direto para Friedrichshain.",t:["ao ar livre","grátis","arte","fotografia"]},
{c:"berlin",k:"historia",n:"Berliner Unterwelten — bunkers e túneis",o:"Berliner Unterwelten e.V.",a:"Gesundbrunnen (U-Bahn)",d:"1h30–2h",p:"€€",w:"Passeios guiados por bunkers antiaéreos, túneis de fuga e estações fantasma embaixo da cidade. Há vários roteiros diferentes (“Dark Worlds”, “Fleeing”, “Bunker”) e costumam esgotar — reserve online com antecedência. É um dos programas mais originais de Berlim.",t:["chuva","história","alternativo","agendar"]},
{c:"berlin",k:"historia",n:"Tempelhof — antigo aeroporto",o:"Flughafen Tempelhof",a:"Tempelhof",d:"2–3h",p:"Grátis (tour pago)",w:"O aeroporto construído pelos nazistas e usado no Bloqueio de Berlim virou parque público onde a cidade anda de bicicleta nas pistas. Faça o tour pelos túneis e pelo prédio monumental, um dos maiores do mundo, hoje ocupado por refugiados e ateliês.",t:["ao ar livre","história","bicicleta","grátis"]},
{c:"berlin",k:"historia",n:"Memorial da prisão da Stasi em Hohenschönhausen",o:"Gedenkstätte Berlin-Hohenschönhausen",a:"Lichtenberg",d:"2h",p:"€€ (guia obrigatório)",w:"A prisão onde a Stasi mantinha presos políticos, com celas originais e visitas guiadas feitas muitas vezes por ex-detentos. Deixa uma marca diferente de qualquer museu: não é exposição, é o lugar.",t:["história","solo","forte"]},
{c:"berlin",k:"historia",n:"Tränenpalast — Palácio das Lágrimas",o:"Tränenpalast",a:"Mitte (Friedrichstraße)",d:"1h",p:"Grátis",w:"O pavilhão onde se passava da Berlim Oriental para a Ocidental e onde famílias se despediam — muita gente não voltava. Exposição gratuita, pequena, ao lado da estação Friedrichstraße. Ótimo encaixe depois do Checkpoint Charlie.",t:["grátis","história","chuva"]},
{c:"berlin",k:"historia",n:"Museu Histórico Alemão",o:"Deutsches Historisches Museum",a:"Mitte",d:"2–3h",p:"€€",w:"Do Sacro Império à reunificação, num Zeughaus de 1706 com a extensão de Pei. Se você quer a linha do tempo inteira da Alemanha em um só lugar, é aqui — e ajuda a amarrar tudo o que você viu sobre o nazismo e o Muro.",t:["chuva","história","imperdível"]},
{c:"berlin",k:"historia",n:"Neue Wache",o:"Neue Wache",a:"Unter den Linden",d:"20min",p:"Grátis",w:"O memorial central alemão às vítimas da guerra e da tirania: uma Pietà ampliada de Käthe Kollwitz num prédio de Schinkel, com o céu aberto por cima. Silêncio de verdade, no meio do eixo mais movimentado da cidade.",t:["grátis","ao ar livre","solo"]},
{c:"berlin",k:"historia",n:"Gleis 17 — plataforma da deportação",o:"Gleis 17, Grunewald",a:"Grunewald",d:"1h",p:"Grátis",w:"Na plataforma 17 da estação de Grunewald saíram os trens que levaram judeus de Berlim para os guetos e campos. Cada data gravada no metal indica quantas pessoas partiram naquele dia. É um dos memoriais mais silenciosos e mais bem-feitos da cidade — vale o desvio até o Grunewald.",t:["ao ar livre","grátis","solo","forte"]},
{c:"berlin",k:"historia",n:"Casa da Conferência de Wannsee",o:"Haus der Wannsee-Konferenz",a:"Wannsee",d:"1h30",p:"Grátis",w:"Na villa onde, em janeiro de 1942, se organizou burocraticamente a “Solução Final”. A exposição mostra a banalidade administrativa do genocídio, com os protocolos originais. Entrada gratuita, no meio do bairro mais bonito e arborizado de Berlim.",t:["grátis","história","solo","forte"]},
{c:"berlin",k:"historia",n:"Memorial de Plötzensee",o:"Gedenkstätte Plötzensee",a:"Charlottenburg-Nord",d:"45min",p:"Grátis",w:"O local de execução de quase três mil pessoas resistentes ao nazismo, entre elas membros da Rosa Branca. Uma parede e um gancho de aço dizem tudo sem precisar de exposição. Bem fora do circuito, quase sempre vazio.",t:["grátis","solo","forte","longe"]},
{c:"berlin",k:"historia",n:"Memorial Soviético de Treptower Park",o:"Sowjetisches Ehrenmal Treptow",a:"Treptow",d:"1h",p:"Grátis",w:"Monumento soviético monumental com 5 mil soldados enterrados, estátuas de granito e o soldado que carrega uma criança sobre uma espada quebrada. Escala colossal, dentro de um parque ótimo para caminhar junto ao Spree.",t:["ao ar livre","grátis","história","caminhada"]},
{c:"berlin",k:"historia",n:"Museu Berlin-Karlshorst",o:"Museum Berlin-Karlshorst",a:"Karlshorst",d:"1h30",p:"Grátis",w:"No salão desta casa o comando alemão assinou a capitulação incondicional em 8 de maio de 1945. O museu mantém a sala intacta e conta a guerra pela ótica soviética, com acervo raro. Gratuito e praticamente sem turistas.",t:["grátis","história","longe"]},
{c:"berlin",k:"historia",n:"Museu Aliado (Alliiertenmuseum)",o:"Alliiertenmuseum",a:"Dahlem",d:"1h30",p:"Grátis",w:"A presença americana, britânica e francesa em Berlim, incluindo o interior do avião que serviu no Bloqueio e o posto de escuta que ficava no Teufelsberg. Gratuito, em Dahlem — junte com o jardim botânico e o Brücke-Museum.",t:["grátis","história","longe"]},
{c:"berlin",k:"historia",n:"Memorial da Resistência Alemã",o:"Gedenkstätte Deutscher Widerstand",a:"Mitte (Bendlerblock)",d:"1h",p:"Grátis",w:"No pátio do Bendlerblock, onde o coronel Stauffenberg foi fuzilado depois do atentado de 20 de julho de 1944 contra Hitler. Exposição gratuita sobre toda a resistência alemã, em ordem cronológica e muito bem organizada.",t:["grátis","história","chuva"]},
{c:"berlin",k:"historia",n:"Memoriais do Tiergarten — Sinti, Roma e homossexuais",o:"Denkmal für die verfolgten Homosexuellen / Mahnmal Sinti und Roma",a:"Tiergarten",d:"45min",p:"Grátis",w:"Dois memoriais vizinhos, no parque, às vítimas do nazismo que ficaram fora do discurso oficial por décadas. O cubo de concreto com uma janela onde passa um filme em looping de um beijo entre dois homens é de uma beleza inquietante.",t:["ao ar livre","grátis","solo"]},
{c:"berlin",k:"historia",n:"Berliner Dom",o:"Berliner Dom",a:"Museumsinsel",d:"1h–1h30",p:"€€",w:"A catedral da cidade, com cripta da família Hohenzollern e subida de 270 degraus até a cúpula externa — a melhor vista da Ilha dos Museus e do Spree. Prepare o fôlego e vá com tempo seco.",t:["vista","história","arte"]},

/* ---------- BERLIM · BAIRROS & CAMINHADA ---------- */
{c:"berlin",k:"bairro",n:"Mitte — Auguststraße e Hackesche Höfe",o:"Mitte / Hackesche Höfe",a:"Mitte",d:"2–3h",p:"Grátis",w:"O miolo antigo da cidade: pátios art nouveau conectados cheios de lojinhas e restaurantes, a Auguststraße com galerias e a Hackescher Markt com as estações de S-Bahn mais bonitas de Berlim. Melhor fazer a pé, sem destino.",t:["ao ar livre","caminhada","compras","arquitetura"]},
{c:"berlin",k:"bairro",n:"Kreuzberg — Bergmannstraße e Graefekiez",o:"Kreuzberg",a:"Kreuzberg",d:"3h",p:"Grátis",w:"O bairro mais berlinense de todos: turcos, turistas, artistas, punks e famílias convivendo. Bergmannstraße tem cafés e brechós, Graefekiez tem bar de bairro de verdade, e o Landwehrkanal ao lado é onde a cidade passeia no fim do dia.",t:["ao ar livre","caminhada","comida","alternativo"]},
{c:"berlin",k:"bairro",n:"Neukölln — Weserstraße e Richardplatz",o:"Neukölln",a:"Neukölln",d:"3h",p:"Grátis",w:"O bairro que mudou mais rápido: imigrantes turcos e árabes, artistas, bares queer e o melhor café da cidade. A Richardplatz é uma praça de vilarejo no meio de tudo. À noite vira o epicentro da vida noturna alternativa.",t:["ao ar livre","alternativo","comida","noite"]},
{c:"berlin",k:"bairro",n:"Friedrichshain — Boxhagener Platz e RAW",o:"Friedrichshain",a:"Friedrichshain",d:"2–3h",p:"Grátis",w:"Punk, skatistas, bares e o complexo RAW-Gelände com clubes e casas de show dentro de galpões ferroviários. É o lado jovem do antigo lado oriental, ao lado da East Side Gallery.",t:["ao ar livre","balada","alternativo"]},
{c:"berlin",k:"bairro",n:"Prenzlauer Berg — Kollwitzplatz e Kastanienallee",o:"Prenzlauer Berg",a:"Prenzlauer Berg",d:"2h",p:"Grátis",w:"O bairro mais gentrificado da cidade: ruas arborizadas, prédios restaurados, cafés de brunch e famílias com carrinho. Ótimo para uma manhã lenta de café e caminhada sem pressa.",t:["caminhada","comida","família","ao ar livre"]},
{c:"berlin",k:"bairro",n:"Wedding — Soldiner Kiez",o:"Wedding",a:"Wedding",d:"2h",p:"Grátis",w:"O bairro pobre e vibrante que está virando — turcos, árabes, artistas e aluguéis ainda baixos. Muito pouco turista, comida barata e o Vagabund Brauerei. Se você quer ver o Berlim que não está no cartão-postal, é aqui.",t:["caminhada","alternativo","comida","longe"]},
{c:"berlin",k:"bairro",n:"Schöneberg — Nollendorfplatz e Motzstraße",o:"Schöneberg",a:"Schöneberg",d:"2h",p:"Grátis",w:"Berço do movimento LGBTQIA+ alemão desde os anos 1920, com o arco-íris pintado no Nollendorfplatz e bares históricos na Motzstraße. Cenário do filme “Cabaret”, com a placa de bronze lembrando os livros queimados e o movimento de Magnus Hirschfeld.",t:["caminhada","gay-friendly","noite","história"]},
{c:"berlin",k:"bairro",n:"Tiergarten",o:"Tiergarten",a:"Tiergarten/Mitte",d:"2–3h",p:"Grátis",w:"O parque central de Berlim, maior que o Central Park, cheio de monumentos escondidos, o lago Neuer See com cervejaria à beira d'água e a Siegessäule no meio. Trajeto perfeito entre o Kulturforum e o Portão de Brandemburgo.",t:["ao ar livre","caminhada","grátis","bicicleta"]},
{c:"berlin",k:"bairro",n:"Charlottenburg — Kurfürstendamm e Savignyplatz",o:"Charlottenburg",a:"Charlottenburg",d:"2h",p:"Grátis",w:"O lado chique e antigo do Oeste, com a Ku'damm, a igreja memorial Kaiser-Wilhelm quebrada pela guerra e o Savignyplatz com bistrôs. É o Berlim que ficou rico e conservador — contraste útil com o Leste.",t:["caminhada","compras","comida"]},
{c:"berlin",k:"bairro",n:"Nikolaiviertel",o:"Nikolaiviertel",a:"Mitte",d:"1h",p:"Grátis",w:"O núcleo medieval reconstruído (na época da RDA, com concreto pré-fabricado nos prédios — o que gera uma mistura estranha e interessante). Ruas estreitas, cervejarias, a Nikolaikirche e o bar Zum Nussbaum. Bom para o fim de tarde.",t:["caminhada","história","comida","noite"]},
{c:"berlin",k:"bairro",n:"Hansaviertel",o:"Hansaviertel",a:"Moabit/Tiergarten",d:"1h",p:"Grátis",w:"Bairro inteiro projetado em 1957 por Niemeyer, Gropius, Aalto e outros como resposta modernista à arquitetura de Stalinallee. Uma aula de arquitetura a céu aberto, quase sempre vazia de turista.",t:["arquitetura","caminhada","ao ar livre","grátis"]},
{c:"berlin",k:"bairro",n:"Landwehrkanal — Paul-Lincke-Ufer e Maybachufer",o:"Landwehrkanal",a:"Kreuzberg/Neukölln",d:"1h30",p:"Grátis",w:"A caminhada mais gostosa de Berlim: o canal com árvores, barcos morando na margem e o Türkenmarkt do Maybachufer nas terças e sextas. Vá no fim de tarde, quando o sol baixo bate na água.",t:["ao ar livre","caminhada","grátis","mercado"]},
{c:"berlin",k:"bairro",n:"Haus Schwarzenberg",o:"Haus Schwarzenberg",a:"Mitte (Rosenthaler Str.)",d:"30min",p:"Grátis",w:"Um beco coberto de grafite e arte em plena Mitte, com o Centro Anne Frank, bares escondidos e o café do Dead Chickens. Símbolo da resistência da arte alternativa ao avanço do turismo na região.",t:["ao ar livre","arte","alternativo","grátis"]},
{c:"berlin",k:"bairro",n:"Köpenick — Altstadt e o velho porto",o:"Altstadt Köpenick",a:"Köpenick",d:"2–3h",p:"Grátis",w:"A parte mais “cidade pequena” de Berlim, numa ilha no meio do Dahme: rua principal antiga, castelo barroco e o porto com barcos. Combina com trilha no Müggelsee no mesmo dia.",t:["caminhada","ao ar livre","longe","água"]},
{c:"berlin",k:"bairro",n:"Treptower Park e Insel der Jugend",o:"Treptower Park",a:"Treptow",d:"1h30",p:"Grátis",w:"Parque à beira do Spree com a Ilha da Juventude (casa de shows e cervejaria) e o memorial soviético dentro. Caminhada plana, visões da água e do bairro de Stralau do outro lado.",t:["ao ar livre","caminhada","água","grátis"]},
{c:"berlin",k:"bairro",n:"Bayerisches Viertel e Rathaus Schöneberg",o:"Bayerisches Viertel",a:"Schöneberg",d:"1h",p:"Grátis",w:"Quarteirão elegante do início do século XX com praças desenhadas por Lenné, e a prefeitura de Schöneberg, onde Kennedy fez o discurso do “Ich bin ein Berliner”. Silencioso e bonito, quase sem turista.",t:["caminhada","ao ar livre","grátis"]},
/* ---------- BERLIM · TRILHAS & NATUREZA ---------- */
{c:"berlin",k:"natureza",n:"Grunewald e a torre Grunewaldturm",o:"Grunewald / Grunewaldturm",a:"Grunewald (S-Bahn)",d:"3–4h",p:"Grátis (torre €)",w:"A maior floresta dentro dos limites de Berlim, com trilhas marcadas, lagos escondidos e a torre de tijolo de 1899 no alto (vista do Havel e do Grunewald inteiro). Combina perfeitamente com o Gleis 17 e a Casa de Wannsee no mesmo dia. Novembro = folhas no chão e quase ninguém.",t:["trilha","ao ar livre","grátis","bicicleta","solo"]},
{c:"berlin",k:"natureza",n:"Trilha circular do Schlachtensee e Krumme Lanke",o:"Schlachtensee / Krumme Lanke",a:"Zehlendorf (S-Bahn)",d:"2h",p:"Grátis",w:"O circuito de lago mais gostoso da cidade: cerca de 7 km de trilha plana contornando dois lagos, com paradas para café. Fácil de fazer em meio dia e o acesso é direto da S-Bahn, sem carro. Ideal para uma manhã de descompressão.",t:["trilha","ao ar livre","grátis","fácil","solo"]},
{c:"berlin",k:"natureza",n:"Müggelsee e a torre Müggelturm",o:"Müggelsee / Müggelturm",a:"Köpenick (S-Bahn)",d:"3–4h",p:"Grátis (torre €)",w:"O maior lago de Berlim, com trilha pela floresta de Müggel até a torre de observação e a praia de areia. No mesmo dia você encaixa a Altstadt de Köpenick. Bate um vento frio em novembro — leve casaco de verdade.",t:["trilha","ao ar livre","longe","vista"]},
{c:"berlin",k:"natureza",n:"Wannsee e a Ilha dos Pavões",o:"Wannsee / Pfaueninsel",a:"Wannsee (S-Bahn)",d:"3–4h",p:"€ (balsa para a ilha)",w:"Travessia de balsa para uma ilha só de pavões livres, com um castelo branco de 1794 e jardins. O trajeto de S-Bahn até Wannsee já é bonito, passando por Grunewald e pela beira do lago. Sem banho em novembro, mas a caminhada compensa.",t:["trilha","ao ar livre","vista","água"]},
{c:"berlin",k:"natureza",n:"66-Seen-Wanderweg — trecho de um dia",o:"66-Seen-Wanderweg",a:"Arredores de Berlim",d:"Dia inteiro",p:"Grátis",w:"Trilha de longa distância que dá a volta em Berlim passando por 66 lagos, dividida em etapas de um dia com acesso por trem. Faça uma etapa (por exemplo perto de Wandlitz ou Erkner) e volte de S-Bahn. É trilha de verdade, com sinalização, e sem turista.",t:["trilha","ao ar livre","grátis","dia inteiro","longe"]},
{c:"berlin",k:"natureza",n:"Liepnitzsee — o lago mais bonito perto da cidade",o:"Liepnitzsee",a:"Wandlitz (S-Bahn + ônibus)",d:"Dia inteiro",p:"Grátis",w:"Água esmeralda, floresta fechada e um circuito de trilha de cerca de 9 km com acesso por transporte público. É o tipo de lugar que ninguém espera encontrar a 40 km do centro de Berlim. Vá com sanduíche e água.",t:["trilha","ao ar livre","grátis","longe","solo"]},
{c:"berlin",k:"natureza",n:"Berliner Mauerweg de bicicleta",o:"Berliner Mauerweg",a:"Traçado do Muro",d:"Meio dia",p:"Grátis (aluguel de bike)",w:"Percurso de 160 km no lugar exato por onde passava o Muro, hoje ciclovia contínua. Alugue uma bike e faça um trecho (Bernauer Straße → Mauerpark → centro, ou o trecho sul pelo canal de Teltow). Junta história, exercício e visão da periferia.",t:["bicicleta","trilha","ao ar livre","grátis","história"]},
{c:"berlin",k:"natureza",n:"Jardim Botânico de Berlim",o:"Botanischer Garten Berlin",a:"Dahlem",d:"3h",p:"€€",w:"Um dos maiores e mais importantes jardins botânicos da Europa, com estufas gigantes onde faz calor mesmo em novembro — 20 mil espécies, orquidário e o maior cactário do mundo. Programão de dia frio ou chuvoso.",t:["chuva","jardim","família","longe"]},
{c:"berlin",k:"natureza",n:"Gärten der Welt",o:"Gärten der Welt",a:"Marzahn",d:"3h",p:"€€",w:"Jardins temáticos de várias culturas — japonês, chinês, coreano, oriental, inglês — num parque enorme no Leste. Também tem o teleférico mais antigo da cidade. Passeio calmo, ótimo para caminhar conversando.",t:["jardim","ao ar livre","caminhada","longe","família"]},
{c:"berlin",k:"natureza",n:"Tegeler Fließ e Naturpark Barnim",o:"Tegeler Fließ",a:"Reinickendorf",d:"2–3h",p:"Grátis",w:"Trilha por várzea e riacho a 20 minutos do centro, com passarelas de madeira, bosque de amieiros e castores. Uma das caminhadas mais subestimadas de Berlim e completamente fora do radar turístico.",t:["trilha","ao ar livre","grátis","solo"]},
{c:"berlin",k:"natureza",n:"Volkspark Hasenheide e Tempelhofer Feld",o:"Hasenheide / Tempelhofer Feld",a:"Neukölln",d:"2h",p:"Grátis",w:"Dois parques colados: a Hasenheide (com a colina de escombros de onde se vê o centro) e o Tempelhofer Feld, o antigo campo de aviação com pistas infinitas para caminhar ou pedalar ao pôr do sol. Grátis e sempre vivo.",t:["ao ar livre","grátis","bicicleta","pôr do sol"]},
{c:"berlin",k:"natureza",n:"Britzer Garten",o:"Britzer Garten",a:"Britz",d:"2–3h",p:"€",w:"Parque paisagístico com lagos, jardins de tulipas (na primavera) e trilhas amplas — em novembro é caminhada tranquila e silenciosa. Bom para um dia em que você queira só andar sem multidão.",t:["jardim","ao ar livre","caminhada","longe"]},

/* ---------- BERLIM · NOTURNO & VISTAS ---------- */
{c:"berlin",k:"noturno",n:"Fernsehturm — mirante a 203 m",o:"Berliner Fernsehturm",a:"Alexanderplatz",d:"1h",p:"€€€",w:"A torre de TV da RDA, com mirante panorâmico e bar girando no alto. É turístico e caro, mas a vista sobre a Alexanderplatz, o Spree e o Tiergarten compensa. Compre ingresso com horário marcado e vá antes do pôr do sol (~16h15 em novembro).",t:["vista","noite","turístico","pôr do sol"]},
{c:"berlin",k:"noturno",n:"Siegessäule — subida à coluna da Vitória",o:"Siegessäule",a:"Tiergarten",d:"45min",p:"€",w:"A coluna dourada no meio do Tiergarten, com escada em caracol até o topo e vista de 360° sobre o parque, o Portão de Brandemburgo e a estrela de ruas. Barata, rápida e melhor que muita atração famosa — chegue 30 min antes do pôr do sol.",t:["vista","grátis","pôr do sol","barato"]},
{c:"berlin",k:"noturno",n:"Panoramapunkt Potsdamer Platz",o:"Panoramapunkt",a:"Potsdamer Platz",d:"1h",p:"€€",w:"O mirante do Kollhoff-Tower, a 100 m, com elevador que sobe em 20 segundos e vista direto para o Kulturforum e o Tiergarten. Menos concorrido que o Fernsehturm e no meio da cidade — bom para encaixar entre dois programas.",t:["vista","noite","pôr do sol"]},
{c:"berlin",k:"noturno",n:"Klunkerkranich",o:"Klunkerkranich",a:"Neukölln",d:"2h",p:"€ (consumação)",w:"Terraço no teto de um shopping na Neukölln Arcaden, com vista sobre os telhados, jardim, DJs e o pôr do sol mais fotografado da cidade. Cheio no verão, mais calmo em novembro — e ainda assim com a melhor vibe de bar ao ar livre de Berlim.",t:["noite","bar","vista","pôr do sol","alternativo"]},
{c:"berlin",k:"noturno",n:"Monkey Bar (25hours Hotel)",o:"Monkey Bar",a:"Charlottenburg / Zoo",d:"1h30",p:"€€",w:"Bar no 10º andar do hotel 25hours, com janelas enormes para o Zoo, o Tiergarten e a igreja memorial. Coquetéis bons, ambiente descontraído e vista noturna ótima — o clássico “drink com vista” de Berlim.",t:["bar","vista","noite","coquetel"]},
{c:"berlin",k:"noturno",n:"Caminhada noturna Spree → Oberbaumbrücke",o:"Spree / Oberbaumbrücke",a:"Friedrichshain/Kreuzberg",d:"1h30",p:"Grátis",w:"A ponte de tijolos dupla entre Kreuzberg e Friedrichshain é uma das imagens mais bonitas da cidade à noite, refletida na água. Caminhe da East Side Gallery até ela e siga para os bares de Friedrichshain. Grátis e sem multidões em novembro.",t:["noite","ao ar livre","grátis","fotografia"]},
{c:"berlin",k:"noturno",n:"Ônibus 100 e 200 — city tour barato",o:"Bus 100 / Bus 200",a:"Mitte → Zoo",d:"1h30",p:"Bilhete normal",w:"Os ônibus de linha 100 e 200 fazem um circuito turístico de graça (para quem já tem bilhete): Portão de Brandemburgo, Unter den Linden, Alexanderplatz, Ilha dos Museus, Potsdamer Platz, Kulturforum, Zoo. Faça o trajeto inteiro no fim da tarde vendo a cidade acender.",t:["barato","vista","noite","sem caminhar"]},
{c:"berlin",k:"noturno",n:"Passeio de barco pelo Spree",o:"Spreefahrt",a:"Mitte / Nikolaiviertel",d:"1h–2h",p:"€€",w:"Os barcos saem perto da Nikolaiviertel e passam pela Ilha dos Museus, pela Berliner Dom e pelo bairro governamental, com o Muro e a arquitetura moderna na mesma vista. Existem versões diurnas e noturnas, e o barco é fechado — funciona mesmo com frio.",t:["água","vista","noite","chuva"]},
{c:"berlin",k:"noturno",n:"Alexanderplatz e o relógio mundial",o:"Alexanderplatz / Weltzeituhr",a:"Mitte",d:"1h",p:"Grátis",w:"A praça mais berlinense e mais feia-bonita da cidade, com o relógio mundial onde as pessoas combinam encontros, a fonte e o Fernsehturm iluminado em cima. Passe por ali à noite para ver a mistura de turista, morador e vida real.",t:["noite","ao ar livre","grátis"]},
{c:"berlin",k:"noturno",n:"Rooftop Deck 5 / Bikini Berlin",o:"Deck 5 / Bikini Berlin",a:"Zoo",d:"1h",p:"€ (consumação)",w:"Terraço da Bikini Berlin com vista para o recinto dos macacos do Zoo, o Tiergarten e a igreja memorial quebrada — contraste de cidade, natureza e ruína no mesmo quadro. Vai bem antes de um jantar em Charlottenburg.",t:["bar","vista","noite"]},
{c:"berlin",k:"noturno",n:"Estação fantasma e túneis do metrô (rota noturna)",o:"Geisterbahnhöfe",a:"Mitte",d:"2h",p:"€€",w:"Alguns roteiros guiados entram em estações fechadas na época da divisão e em túneis de fuga que passavam por baixo do Muro. Se você curte engenharia e história urbana, é dos programas mais diferentes que Berlim tem — reserve com antecedência.",t:["noite","história","alternativo","agendar"]},
{c:"berlin",k:"noturno",n:"Berlin à noite de bicicleta",o:"Nachtradtour",a:"Cidade toda",d:"2–3h",p:"€ (aluguel)",w:"Berlim é plana, tem ciclovia em todo lado e quase nenhum trânsito à noite. Pedalar de Mitte até Kreuzberg, Friedrichshain e voltar pelo Landwehrkanal com os monumentos iluminados é uma das melhores maneiras de ver a cidade — e há tours guiados noturnos em inglês.",t:["bicicleta","noite","ao ar livre","grupo"]},

/* ---------- BERLIM · EXPERIÊNCIA ÚNICA ---------- */
{c:"berlin",k:"unica",n:"Sammlung Boros",o:"Sammlung Boros",a:"Mitte (Reinhardtstraße)",d:"1h30",p:"€€€ (só com agendamento)",w:"Coleção privada de arte contemporânea dentro de um bunker antiaéreo da Segunda Guerra, com os andares reformados e o antigo grafite preservado nas paredes. Visita só com horário marcado e guia, com vagas limitadas — se te interessar, reserve antes de viajar.",t:["arte","alternativo","agendar","chuva"]},
{c:"berlin",k:"unica",n:"Teufelsberg — a colina de entulho com estação espiã",o:"Teufelsberg",a:"Grunewald",d:"2–3h",p:"€€",w:"Uma colina artificial feita com os escombros da Berlim destruída na guerra, com as cúpulas de radar da estação de escuta americana abandonadas no topo e grafite em tudo. Vista enorme da cidade, história da Guerra Fria e um lugar que não existe em nenhum outro lugar do mundo.",t:["alternativo","vista","arte","trilha","imperdível"]},
{c:"berlin",k:"unica",n:"Spreepark — o parque de diversões abandonado",o:"Spreepark",a:"Treptow (Plänterwald)",d:"1h30",p:"€€ (tour)",w:"Parque de diversões da RDA fechado em 2001 e tomado pelo mato, com a roda-gigante enferrujada e os brinquedos parados. Está em obra para reabrir aos poucos: o miolo fica pronto no fim de 2026 e as visitas guiadas acontecem em datas marcadas — para novembro, confirme as datas no site antes de contar com ele.",t:["alternativo","abandonado","verificar","longe"]},
{c:"berlin",k:"unica",n:"Dirigir um Trabant: Trabi Safari",o:"Trabi Safari",a:"Mitte",d:"2h",p:"€€€",w:"Você dirige um Trabant de verdade (o carro da Alemanha Oriental, de plástico e fumaça) em comboio pela cidade, com rádio e guia. É turístico, sim — e é divertido, especialmente se você gosta de carro e de história social.",t:["alternativo","turístico","grupo","carro"]},
{c:"berlin",k:"unica",n:"Alternative Berlin Tours — street art e subsolo",o:"Alternative Berlin Tours",a:"Mitte/Kreuzberg",d:"3h",p:"Grátis (gorjeta)",w:"Tours a pé em inglês focados em street art, squats, cultura de clube e história alternativa, conduzidos por gente que vive a cena. Excelente no primeiro dia em Berlim para entender a cidade por baixo do cartão-postal.",t:["grupo","alternativo","caminhada","grátis","primeiro dia"]},
{c:"berlin",k:"unica",n:"Stand-up comedy em inglês",o:"Cosmic Comedy / Comedy Café Berlin",a:"Neukölln / Mitte",d:"2h",p:"€",w:"Berlim tem uma cena de comédia em inglês muito boa, com noites quase todos os dias em Neukölln e Mitte. Barato, social e uma forma de conhecer gente da cidade em vez de turista. Ótimo para uma noite em que você não quer clube.",t:["noite","barato","grupo","inglês"]},
{c:"berlin",k:"unica",n:"Vabali Spa — sauna nórdica",o:"Vabali Spa Berlin",a:"Moabit (perto da Hbf)",d:"4h",p:"€€€",w:"Complexo de saunas finlandesas, banhos quentes e frios, piscinas e áreas de descanso, com piscina externa. É a experiência alemã de sauna de verdade: roupa de banho não se usa nas áreas de sauna. Perfeito para uma tarde fria ou para curar uma noite de clube.",t:["spa","chuva","relaxar","imperdível"]},
{c:"berlin",k:"unica",n:"Liquidrom",o:"Liquidrom",a:"Kreuzberg",d:"2–3h",p:"€€€",w:"Cúpula com piscina de água salgada, som subaquático e DJ ao vivo, mais saunas e banhos de vapor. É banho termal com música eletrônica — bem Berlim, e funciona tanto de dia quanto à noite.",t:["spa","noite","relaxar","alternativo"]},
{c:"berlin",k:"unica",n:"Stadtbad Neukölln",o:"Stadtbad Neukölln",a:"Neukölln",d:"1h30",p:"€",w:"Piscina coberta de 1914 com azulejos, arcos e vitrais — parece um templo. Barata, linda e frequentada por moradores, não por turistas. Se você gosta de piscina histórica, essa é mais bonita que qualquer museu de bairro.",t:["barato","chuva","arquitetura","relaxar"]},
{c:"berlin",k:"unica",n:"Sala de boulder em Kreuzberg ou Lichtenberg",o:"Der Kegel / Bouldergarten / Ostbloc",a:"Kreuzberg / Lichtenberg",d:"2h",p:"€€",w:"Berlim tem dezenas de academias de escalada, algumas em estruturas industriais impressionantes (a Der Kegel é numa torre de gás). Aluguel de sapatilha incluso. Boa forma de fazer exercício e ver gente local num dia chuvoso.",t:["chuva","esporte","grupo","barato"]},
{c:"berlin",k:"unica",n:"Karaokê em bar queer ou no Mauerpark",o:"Karaoke (Mon Cheri / Mauerpark)",a:"Mitte / Prenzlauer Berg",d:"2h",p:"€",w:"Berlim leva karaokê a sério. No domingo, o anfiteatro do Mauerpark vira palco público com plateia; durante a semana, bares de Mitte e Schöneberg fazem noites de karaokê com gente que canta bem de verdade — e gente que canta mal de propósito.",t:["noite","barato","grupo","música"]},
{c:"berlin",k:"unica",n:"Free walking tour — o primeiro dia em Berlim",o:"Free Walking Tour",a:"Mitte (Portão de Brandemburgo)",d:"2h30",p:"Grátis (gorjeta)",w:"Tour de introdução que sai do Portão de Brandemburgo e cobre os 800 anos de história em um trajeto, em inglês e com guia que se paga por gorjeta. Serve para você se localizar de verdade no primeiro dia, o que economiza tempo depois.",t:["primeiro dia","grátis","grupo","caminhada"]},
{c:"berlin",k:"unica",n:"Anti-Kriegs-Museum (Museu Antiguerra)",o:"Anti-Kriegs-Museum",a:"Wedding",d:"1h",p:"€ (doação)",w:"Museu pequeno, independente e completamente analógico, no prédio onde Ernst Friedrich manteve os arquivos antiguerra nos anos 1920 antes de os nazistas destruírem tudo. Guardado por voluntários, sem vitrine de luxo — o oposto do museu institucional.",t:["alternativo","história","barato","solo"]},
{c:"berlin",k:"unica",n:"Christmas market de fim de noite com Glühwein",o:"Glühwein & Lichter",a:"Lichtenberg / Potsdamer Platz",d:"2h",p:"€ (consumação)",w:"Mesmo que só um mercado esteja aberto, a experiência de Glühwein com rum, Bratwurst, Reibekuchen com maçã e luzes quentes num frio de 4°C é um dos melhores programas noturnos de novembro na Alemanha. Vá com fome e sem carro.",t:["noite","comida","ao ar livre","frio"]},
/* ---------- BERLIM · BALADA, DJs & MÚSICA AO VIVO ---------- */
{c:"berlin",k:"balada",n:"Berghain / Panorama Bar",o:"Berghain",a:"Friedrichshain",d:"Noite toda",p:"€€",w:"O clube mais famoso do mundo e o teste definitivo da cultura de clube berlinense: som monumental, sem telefone na pista, sem foto, entrada decidida na porta pelo segurança (não há regra objetiva). Sábado à noite é a Klubnacht, a maratona que começa sábado e termina segunda. Vá sem grupo grande, sem falar alto na fila e com paciência para 1h–2h de espera.",t:["techno","noite","madrugada","imperdível","regras"]},
{c:"berlin",k:"balada",n:"Watergate",o:"Watergate",a:"Kreuzberg (Spree)",d:"Noite toda",p:"€€",w:"Casa de techno e house à beira do Spree, com LED no teto e vista para a água pelas janelas panorâmicas. Menos intimidante que o Berghain, com line-up consistente e festas que atravessam a manhã. Bom “primeiro clube” de Berlim.",t:["techno","noite","madrugada","rio"]},
{c:"berlin",k:"balada",n:"Kater Blau",o:"Kater Blau",a:"Mitte (Holzmarkt)",d:"Noite toda",p:"€€",w:"Clube em palafitas no complexo Holzmarkt, à beira do Spree, com decoração de madeira, dois andares e som de techno melódico e house. Ambiente mais acolhedor e colorido que os clubes de concreto — e a área externa com fogueira é ótima no frio.",t:["techno","noite","madrugada","rio","alternativo"]},
{c:"berlin",k:"balada",n:"Sisyphos",o:"Sisyphos",a:"Lichtenberg",d:"Domingo/manhã",p:"€€",w:"Mais do que um clube, é um festival permanente: pátio com esculturas, barracas de comida, dois palcos e pista. A magia é ir no domingo à tarde e sair na segunda de manhã — a energia de domingo em Berlim não existe em outro lugar.",t:["techno","domingo","ao ar livre","alternativo","imperdível"]},
{c:"berlin",k:"balada",n:"Renate",o:"Renate",a:"Lichtenberg",d:"Noite toda",p:"€€",w:"Clube-labirinto numa casa antiga, com cada sala decorada de forma diferente (tem até banheira e quarto), público queer-friendly e som que vai do house ao electro. Uma das experiências mais divertidas e menos solenes da noite berlinense.",t:["techno","noite","queer","alternativo"]},
{c:"berlin",k:"balada",n:"://about blank",o:"about blank",a:"Friedrichshain (Ostkreuz)",d:"Noite toda",p:"€€",w:"Clube gerido coletivamente, com postura política explícita (antifascista, contra discriminação na pista) e jardim externo no verão. Techno e house de qualidade e público bem diverso — o oposto do clubismo de turista.",t:["techno","noite","queer","alternativo","político"]},
{c:"berlin",k:"balada",n:"Tresor (Kraftwerk Berlin)",o:"Tresor",a:"Mitte (Köpenick)",d:"Noite toda",p:"€€",w:"Lendário e histórico: funcionou no cofre de um banco nos anos 1990 e hoje ocupa a usina Kraftwerk. Techno duro, acústica brutal e o “Globus” no andar de baixo. Se você quer entender de onde vem a cultura techno de Berlim, é aqui.",t:["techno","noite","história","madrugada"]},
{c:"berlin",k:"balada",n:"KitKatClub",o:"KitKatClub",a:"Mitte (Heinrich-Heine-Str.)",d:"Noite toda",p:"€€€",w:"Clube fetichista e liberal com dress code obrigatório (látex, couro, fetish, body painting) e piscina no meio da pista. Não é para todo mundo, mas é uma instituição berlinense — se você for, vá com fantasia de verdade, senão a porta não deixa entrar.",t:["fetish","noite","liberal","dresscode"]},
{c:"berlin",k:"balada",n:"Ritter Butzke",o:"Ritter Butzke",a:"Kreuzberg",d:"Noite toda",p:"€€",w:"Clube em três andares de um antigo edifício industrial, com som de techno e house e um jardim interno. Costuma ser mais acessível na porta que os clubes grandes e tem programação quase toda noite.",t:["techno","noite","fácil de entrar"]},
{c:"berlin",k:"balada",n:"SO36",o:"SO36",a:"Kreuzberg",d:"Noite",p:"€€",w:"Casa de punk e cultura alternativa na Oranienstraße desde 1978, quando Berlim Ocidental ainda era outra cidade. Hoje alterna shows de punk, festas gays, reggae e noites de rock — a memória viva do Kreuzberg autêntico.",t:["punk","noite","história","rock","gay-friendly"]},
{c:"berlin",k:"balada",n:"Astra Kulturhaus",o:"Astra Kulturhaus",a:"Friedrichshain",d:"Noite",p:"€€",w:"Casa de shows dentro do RAW-Gelände, com programação de indie, eletrônica e bandas internacionais. Espaço grande, ingressos razoáveis e o melhor lugar da cidade para ver show de banda em turnê.",t:["shows","noite","rock","indie"]},
{c:"berlin",k:"balada",n:"Lido",o:"Lido",a:"Kreuzberg",d:"Noite",p:"€€",w:"Casa de shows na Schlesische Straße com programação indie, pop e hip-hop, além de festas. Palco pequeno e som bom, com público que realmente vai pela música.",t:["shows","noite","indie"]},
{c:"berlin",k:"balada",n:"Cassiopeia",o:"Cassiopeia",a:"Friedrichshain (RAW)",d:"Noite",p:"€",w:"Complexo com casa de shows, clube e pista de skate coberta dentro do RAW-Gelände. Alternativo, barato e cheio de gente nova. Bom para uma noite que começa com banda e termina dançando.",t:["shows","skate","alternativo","barato"]},
{c:"berlin",k:"balada",n:"Badehaus Szimpla",o:"Badehaus Szimpla Music Hall",a:"Friedrichshain (RAW)",d:"Noite",p:"€€",w:"Casa de show dentro de um antigo banho público, com acústica boa e programação de jazz, folk, world e eletrônica ao vivo. Um dos espaços mais bonitos para música em Berlim.",t:["shows","jazz","noite","arquitetura"]},
{c:"berlin",k:"balada",n:"A-Trane",o:"A-Trane",a:"Charlottenburg",d:"Noite",p:"€€",w:"O clube de jazz mais estabelecido da cidade, na Pestalozzistraße, com concertos quase todas as noites e nomes internacionais passando por lá. Sente cedo para pegar lugar perto do palco — a sala não é grande.",t:["jazz","noite","música ao vivo","imperdível"]},
{c:"berlin",k:"balada",n:"Quasimodo",o:"Quasimodo",a:"Charlottenburg",d:"Noite",p:"€€",w:"Jazz, funk, soul e grooves no subsolo de um prédio na Kantstraße, funcionando desde os anos 1970. Fim de noite rola DJ set e a pista enche. Um dos melhores lugares para jazz que não é caro nem chique.",t:["jazz","funk","noite","barato"]},
{c:"berlin",k:"balada",n:"Zig Zag Jazz Club",o:"Zig Zag Jazz Club",a:"Schöneberg",d:"Noite",p:"€€",w:"Clube de jazz pequeno e acolhedor na Hauptstraße, com programação forte de jazz contemporâneo e jovens músicos da cena berlinense. Ambiente de sala de estar — você fica a dois metros do contrabaixo.",t:["jazz","noite","intimista"]},
{c:"berlin",k:"balada",n:"Donau115",o:"Donau115",a:"Neukölln",d:"Noite",p:"€ (gorjeta no chapéu)",w:"Bar minúsculo em Neukölln onde o jazz experimental acontece literalmente no chão, entre as mesas, com preço de consumação e chapéu passando. É a cena de jazz jovem de Berlim no seu estado mais cru — chegue cedo, cabe pouca gente.",t:["jazz","noite","alternativo","barato","experimental"]},
{c:"berlin",k:"balada",n:"Kantine am Berghain",o:"Kantine am Berghain",a:"Friedrichshain",d:"Noite",p:"€€",w:"A cantina ao lado do Berghain tem programação própria de shows — indie, experimental, eletrônica ao vivo, hip-hop — com entrada separada e sem a fila do clube. Muita gente boa passa por aqui antes de virar nome grande.",t:["shows","indie","noite","experimental"]},
{c:"berlin",k:"balada",n:"Monarch",o:"Monarch",a:"Kreuzberg (Kottbusser Tor)",d:"Noite",p:"€",w:"Bar e clube no primeiro andar em cima do Kottbusser Tor, com janelas dando para a praça e vista da vida da rua. Programação de DJs variada e entrada barata — o ponto de encontro clássico antes de decidir para onde ir depois.",t:["bar","noite","vista","barato","alternativo"]},
{c:"berlin",k:"balada",n:"SchwuZ",o:"SchwuZ",a:"Neukölln",d:"Noite toda",p:"€€",w:"O maior clube LGBTQIA+ de Berlim, com dois andares, festas temáticas (pop, electro, darkroom) e público enorme e diverso. Historicamente importante para a comunidade desde os anos 1970, hoje é festa grande e alegre.",t:["queer","noite","festa","madrugada","gay-friendly"]},
{c:"berlin",k:"balada",n:"Chantal's House of Shame",o:"Chantal's House of Shame",a:"Neukölln",d:"Noite toda",p:"€€",w:"Clube e espaço queer alternativo em Neukölln, com performances, drag, festas temáticas e um público muito misto em idade e estilo. É onde a cena queer jovem de Berlim se encontra — bem diferente do circuito gay tradicional.",t:["queer","noite","drag","alternativo","festa"]},
{c:"berlin",k:"balada",n:"Clärchens Ballhaus",o:"Clärchens Ballhaus",a:"Mitte (Auguststraße)",d:"Noite",p:"€€",w:"Salão de dança de 1913 que continua funcionando: dança de salão, tango, swing, salsa e festas de época, em um salão espelhado que está literalmente descascando. Experiência única e muito mais divertida do que parece — não precisa saber dançar.",t:["dança","noite","história","único","grupo"]},
{c:"berlin",k:"balada",n:"Buck & Breck",o:"Buck & Breck",a:"Mitte",d:"2h",p:"€€€",w:"Bar de coquetelaria premiada, sem telefone, sem música alta, sem menu — você diz o que gosta e o bartender decide. Fica atrás de uma porta discreta. Se você gosta de coquetel a sério, é a melhor da cidade.",t:["coquetel","noite","sofisticado","escondido"]},
{c:"berlin",k:"balada",n:"Armadilhas da noite: o que evitar",o:"Touristenfallen",a:"Warschauer Straße / Mitte",d:"—",p:"—",w:"Regra prática: desconfie de clubes com promoter na porta chamando gente na rua, de “open bar” e de lugares na Warschauer Straße anunciados como “the real Berlin techno experience”. O melhor filtro é olhar o line-up em ra.co alguns dias antes; se não houver DJ identificado, provavelmente é armadilha de turista.",t:["armadilha","noite","evitar"]},

/* ---------- BERLIM · PALCO, ÓPERA & CONCERTOS ---------- */
{c:"berlin",k:"palco",n:"Berliner Philharmonie",o:"Berliner Philharmoniker",a:"Kulturforum",d:"2h",p:"€€–€€€€",w:"Uma das melhores orquestras do mundo na sala desenhada por Hans Scharoun, com palcos em vinha no meio da plateia. Há ingressos baratos de última hora e ensaios abertos — vale checar a programação para a sua data antes de viajar.",t:["concerto","erudito","arquitetura","imperdível"]},
{c:"berlin",k:"palco",n:"Staatsoper Unter den Linden",o:"Staatsoper Unter den Linden",a:"Mitte",d:"3h",p:"€€–€€€€",w:"A ópera histórica de Berlim, no eixo principal, com acústica excelente depois da reforma. Ingressos de pé ou de última hora custam pouco. Se você nunca foi a uma ópera, comece por aqui — os alemães não se vestem de gala.",t:["ópera","erudito","noite"]},
{c:"berlin",k:"palco",n:"Deutsche Oper Berlin",o:"Deutsche Oper Berlin",a:"Charlottenburg",d:"3h",p:"€€–€€€",w:"A outra grande casa de ópera, em Charlottenburg, com repertório mais tradicional e ingressos geralmente mais fáceis de conseguir. Edifício moderno e programação variada.",t:["ópera","erudito","noite"]},
{c:"berlin",k:"palco",n:"Komische Oper Berlin",o:"Komische Oper Berlin",a:"Mitte (Behrenstraße)",d:"2h30",p:"€€",w:"Ópera com legendas em inglês e alemão projetadas, foco em repertório acessível e encenações modernas. A melhor porta de entrada para quem não conhece ópera e não quer se sentir perdido.",t:["ópera","erudito","acessível","legendas"]},
{c:"berlin",k:"palco",n:"Konzerthaus Berlin",o:"Konzerthaus am Gendarmenmarkt",a:"Mitte (Gendarmenmarkt)",d:"2h",p:"€€–€€€",w:"Sala neoclássica na praça mais bonita de Berlim, com concertos sinfônicos e de câmara quase diários. Fica do lado do mercado de Natal da Gendarmenmarkt (que abre depois da sua passagem) — mas a praça iluminada já vale a ida.",t:["concerto","erudito","noite","arquitetura"]},
{c:"berlin",k:"palco",n:"Berliner Ensemble",o:"Berliner Ensemble",a:"Mitte",d:"2h30",p:"€€",w:"O teatro fundado por Brecht e Helene Weigel, ainda no prédio do Theater am Schiffbauerdamm, com encenações em alemão (algumas com legendas em inglês). Peça histórica da dramaturgia mundial e programa em cartaz variado.",t:["teatro","erudito","noite"]},
{c:"berlin",k:"palco",n:"Schaubühne am Lehniner Platz",o:"Schaubühne",a:"Charlottenburg",d:"2h30",p:"€€",w:"O teatro contemporâneo mais respeitado da cidade, com direção de ponta e textos de Ibsen a Sarah Kane. Muitas produções têm legendas em inglês — vale conferir a marcação no site. Se você gosta de teatro de verdade, é aqui.",t:["teatro","contemporâneo","noite"]},
{c:"berlin",k:"palco",n:"Volksbühne",o:"Volksbühne",a:"Mitte (Rosa-Luxemburg-Platz)",d:"2h30",p:"€€",w:"Teatro histórico do lado oriental, com histórico de provocação e experimentação. O prédio de 1914 na Rosa-Luxemburg-Platz já vale a ida, e a programação segue politicamente engajada.",t:["teatro","alternativo","história","noite"]},
{c:"berlin",k:"palco",n:"Maxim Gorki Theater",o:"Maxim Gorki Theater",a:"Mitte",d:"2h30",p:"€€",w:"O menor teatro da cidade e o mais diverso: elenco pós-migratório, muitos textos sobre identidade, e legendas em inglês em várias produções. Excelente para entender o debate atual da Alemanha.",t:["teatro","diversidade","noite","legendas"]},
{c:"berlin",k:"palco",n:"Kino Babylon",o:"Kino Babylon",a:"Mitte (Rosa-Luxemburg-Platz)",d:"2h",p:"€€",w:"Cinema de 1929 em estilo Bauhaus e cinemas mudos acompanhados por orquestra ao vivo — uma experiência rara e barata. A sala grande é patrimônio arquitetônico. Programa mensal no site, reserve antes.",t:["cinema","erudito","noite","único"]},
{c:"berlin",k:"palco",n:"Kino International",o:"Kino International",a:"Mitte (Karl-Marx-Allee)",d:"2h",p:"€€",w:"Cinema de estreia da RDA, com mármore, lustre e escadaria larga — um monumento ao luxo socialista de 1963. Ver um filme aqui é metade cinema, metade viagem no tempo. Fica na Karl-Marx-Allee, que merece a caminhada.",t:["cinema","história","noite","arquitetura"]},
/* ---------- BERLIM · COMIDA & BEBIDA ---------- */
{c:"berlin",k:"comida",n:"Currywurst: Curry 36 e Konnopke's",o:"Curry 36 / Konnopke's Imbiß",a:"Kreuzberg / Prenzlauer Berg",d:"30min",p:"€",w:"A currywurst é o prato-símbolo de Berlim e estes dois são os clássicos: Curry 36 (na Mehringdamm, de pé, de madrugada) e Konnopke's, funcionando sob o viaduto do metrô de Prenzlauer Berg desde 1930. Peça com “mit Darm” (com tripa) e Pommes com maionese.",t:["comida","barato","rápido","ícone"]},
{c:"berlin",k:"comida",n:"Döner kebab — os dois endereços da discussão",o:"Mustafa's Gemüse Kebap / Hasir",a:"Kreuzberg / Wedding",d:"30–60min",p:"€",w:"O döner foi inventado em Berlim (e é berlinense, não turco), e a briga sobre quem faz o melhor é local. Mustafa's Gemüse Kebab na Mehringdamm tem a fila mais famosa da cidade; Hasir, em Kreuzberg, serve na mesa desde 1970. Vá de estômago vazio.",t:["comida","barato","ícone","fila"]},
{c:"berlin",k:"comida",n:"Markthalle Neun e o Street Food Thursday",o:"Markthalle Neun",a:"Kreuzberg",d:"2h",p:"€–€€",w:"Mercado histórico de 1891 salvo por moradores, com produtores, banca de queijos, padaria, açougue e a cervejaria Heidenpeters dentro. Às quintas-feiras acontece o Street Food Thursday, com cozinhas do mundo inteiro — chegue a partir das 18h.",t:["comida","mercado","noite","imperdível"]},
{c:"berlin",k:"comida",n:"Arminiushalle",o:"Arminiushalle",a:"Moabit",d:"1h",p:"€",w:"Mercado de bairro em Moabit com açougue, peixaria, queijos, especiarias e barracas de comida turca e italiana — dos lugares onde os moradores realmente compram. Muito barato e praticamente sem turista.",t:["comida","mercado","barato","local"]},
{c:"berlin",k:"comida",n:"Türkenmarkt do Maybachufer",o:"Türkenmarkt am Maybachufer",a:"Neukölln",d:"1h",p:"€",w:"Feira turca às terças e sextas na beira do canal: frutas, azeitonas, queijos brancos, pão, especiarias, tabuleiro de barracas. É feira de morador, com preço de morador. Combine com a caminhada no Landwehrkanal. (Você está na cidade na sexta 06/11 — aproveite.)",t:["comida","mercado","barato","local","sexta"]},
{c:"berlin",k:"comida",n:"Winterfeldtmarkt",o:"Winterfeldtmarkt",a:"Schöneberg",d:"1h30",p:"€",w:"Praça de mercado em Schöneberg às quartas e sábados, com produtores, queijos, flores e barracas de comida quente. Aos sábados o entorno vira um brunch gigante ao ar livre. Bom para a manhã de sábado antes de ir para Kreuzberg.",t:["comida","mercado","manhã","sábado"]},
{c:"berlin",k:"comida",n:"KaDeWe — andar gourmet",o:"Kaufhaus des Westens (Feinkostabteilung)",a:"Charlottenburg",d:"1h",p:"€€–€€€€",w:"O segundo maior departamento da Europa, com o andar de comida mais famoso da Alemanha: peixaria, charcutaria, mais de mil queijos, ostras e uma ilha de sobremesas. Mesmo que você não compre nada, vá ver — e coma algo no balcão.",t:["comida","compras","luxo","ícone"]},
{c:"berlin",k:"comida",n:"Cerveja ao ar livre: Prater e Café am Neuen See",o:"Prater / Café am Neuen See",a:"Prenzlauer Berg / Tiergarten",d:"2h",p:"€€",w:"A Prater é a cervejaria mais antiga de Berlim (1837), com jardim de castanheiras e mesas compridas; o Café am Neuen See fica dentro do Tiergarten, à beira do lago, com barcos e cisnes. Em novembro ambos ficam mais tranquilos — leve casaco e tome cerveja escura de inverno.",t:["bar","ao ar livre","cerveja","tradição"]},
{c:"berlin",k:"comida",n:"Cerveja artesanal de Berlim",o:"BRLO / Vagabund / Heidenpeters",a:"Kreuzberg / Wedding",d:"2h",p:"€€",w:"A cena de craft beer berlinense cresceu muito: a BRLO fica dentro de um complexo de contêineres no Gleisdreieck, a Heidenpeters dentro da Markthalle Neun, e a Vagabund tem o jardim mais gostoso de Wedding. Bom para descobrir cerveja alemã que não é só pilsen.",t:["cerveja","bar","noite","alternativo"]},
{c:"berlin",k:"comida",n:"Cafés de especialidade",o:"Bonanza / The Barn / Five Elephant",a:"Kreuzberg / Mitte / Prenzlauer Berg",d:"1h",p:"€€",w:"Berlim é uma cidade de café sério. Bonanza e The Barn torram na cidade, a Five Elephant faz cheesecake lendário em Kreuzberg, e a Father Carpenter, num pátio em Mitte, é a melhor opção para sentar. Para trabalhar de manhã, qualquer uma serve.",t:["café","manhã","chuva","trabalhar"]},
{c:"berlin",k:"comida",n:"Alta gastronomia berlinense",o:"Nobelhart & Schmutzig / Rutz / Tim Raue",a:"Mitte / Charlottenburg",d:"3h",p:"€€€€",w:"Berlim virou destino gastronômico: a Nobelhart & Schmutzig trabalha só com produtores da região de Berlim e é uma experiência-manifesto; a Rutz tem três estrelas; a Tim Raue faz cozinha asiática alemã premiada. Reserve com semanas de antecedência.",t:["comida","luxo","reservar","noite"]},
{c:"berlin",k:"comida",n:"Cozinha alemã clássica",o:"Zur letzten Instanz / Schwarzwaldstuben / Katz Orange",a:"Mitte / Kreuzberg",d:"2h",p:"€€",w:"A Zur letzten Instanz é a taverna mais antiga de Berlim (1621), com paredes de azulejo e Eisbein; a Schwarzwaldstuben faz cozinha do sul da Alemanha com Maultaschen; a Katz Orange é o clássico contemporâneo para carne e vinho. Para provar comida alemã que não é caricatura.",t:["comida","tradição","noite"]},
{c:"berlin",k:"comida",n:"Vegetariano e vegano",o:"Lucky Leek / FREA / 1990 Vegan Living",a:"Charlottenburg / Mitte / Friedrichshain",d:"1h30",p:"€€",w:"Berlim é provavelmente a melhor cidade da Europa para comer vegetariano: a Lucky Leek é a única com estrela Michelin, a FREA é sem desperdício e a 1990 é vegan vietnamita. Mesmo quem come carne sai satisfeito.",t:["comida","vegetariano","vegano","noite"]},
{c:"berlin",k:"comida",n:"Vietnamita e asiático",o:"Monsieur Vuong / District Mot / Umami",a:"Mitte / Kreuzberg",d:"1h30",p:"€€",w:"A comunidade vietnamita em Berlim é enorme e a comida é excelente: a Monsieur Vuong, em Mitte, é instituição; a District Mot, em Mitte, faz o pho mais aclamado. Depois do currywurst, é o melhor custo-benefício da cidade.",t:["comida","asiático","barato"]},
{c:"berlin",k:"comida",n:"Turco de verdade, além do kebab",o:"Hasir / Adana Grillhaus / Bursa",a:"Kreuzberg / Wedding",d:"2h",p:"€€",w:"Kreuzberg tem a maior comunidade turca fora da Turquia: a Hasir é a casa-mãe desde 1970, a Adana Grillhaus faz grelhados no carvão e a Bursa é onde a comunidade almoça. Peça mezes, pide e chá — é uma cozinha muito mais ampla que o döner.",t:["comida","local","noite"]},
{c:"berlin",k:"comida",n:"Doce: Fassbender & Rausch",o:"Fassbender & Rausch",a:"Mitte (Gendarmenmarkt)",d:"45min",p:"€€",w:"Chocolateria na Gendarmenmarkt desde 1863, com esculturas gigantes de chocolate (do Brandemburgo a um vulcão de chocolate fluindo) e cafés no primeiro andar. Bom souvenir comestível e boa parada em dia frio.",t:["comida","doce","chuva","souvenir"]},
{c:"berlin",k:"comida",n:"Kneipe — o bar de esquina alemão",o:"Kneipe",a:"Kreuzberg / Neukölln / Prenzlauer Berg",d:"2h",p:"€",w:"A instituição social berlinense: bar pequeno, cerveja na garrafa, mesa de madeira, fumaça e conversa. Entre num qualquer no Graefekiez ou na Weserstraße sem pesquisar — a graça é escolher pela fachada. Barato e onde se conhece gente local.",t:["bar","noite","barato","local","autêntico"]},
{c:"berlin",k:"comida",n:"Wine bars e vinho alemão",o:"Cordo / Vin Aqua Vin / Weinbar Rutz",a:"Mitte / Kreuzberg",d:"2h",p:"€€–€€€",w:"A Alemanha faz bons vinhos (Riesling de Mosel e Rheingau, Spätburgunder) que quase nunca se bebe no Brasil. Numa wine bar de Berlim você prova por taça e entende o país por dentro. Boa opção de noite calma e sofisticada.",t:["vinho","noite","sofisticado"]},

/* ---------- BERLIM · COMPRAS & MERCADOS ---------- */
{c:"berlin",k:"compras",n:"Flohmarkt do Mauerpark",o:"Flohmarkt im Mauerpark",a:"Prenzlauer Berg",d:"3h",p:"Grátis",w:"O maior e mais famoso mercado de pulgas de Berlim, só aos domingos: móveis, roupas vintage, vinis, bicicletas antigas, louça da RDA e comida de rua. Ao lado, o karaokê público no anfiteatro. Vá cedo (9h–10h) para achar as coisas boas.",t:["compras","mercado","domingo","ao ar livre","imperdível"]},
{c:"berlin",k:"compras",n:"Flohmarkt do Arkonaplatz",o:"Flohmarkt Arkonaplatz",a:"Prenzlauer Berg",d:"1h30",p:"Grátis",w:"Ao lado do Mauerpark, bem menor e mais curado: vintage de qualidade, antiguidades, objetos de design da RDA. Os preços são maiores e as peças melhores — é o mercado para procurar uma coisa específica, não para garimpar.",t:["compras","mercado","domingo","vintage"]},
{c:"berlin",k:"compras",n:"Flohmarkt de Boxhagener Platz",o:"Flohmarkt Boxhagener Platz",a:"Friedrichshain",d:"1h30",p:"Grátis",w:"Mercado de pulgas de bairro em Friedrichshain, aos domingos, com clima mais local e alternativo que o Mauerpark. Roupas, discos, livros e bugigangas. Bom se você já está na região das baladas e quer começar o dia ali.",t:["compras","mercado","domingo","alternativo"]},
{c:"berlin",k:"compras",n:"Fehrbelliner Platz — antiguidades",o:"Antik- und Flohmarkt Fehrbelliner Platz",a:"Wilmersdorf",d:"2h",p:"Grátis",w:"O mercado de antiguidades de Berlim: prata, porcelana, relógios, moedas, livros antigos, mobiliário. Domingos. Público de colecionador, muito diferente do mercado de roupas vintage — bom se você gosta de objeto com história.",t:["compras","antiguidades","domingo"]},
{c:"berlin",k:"compras",n:"Feira de antiguidades da Straße des 17. Juni",o:"Kunst- und Trödelmarkt",a:"Tiergarten",d:"2h",p:"Grátis",w:"Sábados e domingos, entre o Portão de Brandemburgo e a Siegessäule, com artesanato, antiguidades e arte. Muito turística, mas a localização é imbatível — encaixa perfeitamente num sábado de caminhada pelo Tiergarten.",t:["compras","antiguidades","sábado","domingo","turístico"]},
{c:"berlin",k:"compras",n:"KaDeWe",o:"KaDeWe",a:"Charlottenburg",d:"2h",p:"€€€€",w:"O departamento mais famoso da Alemanha, com sete andares de moda, beleza, casa e o andar gourmet no topo. Luxo de verdade e um bom termômetro do consumo alemão. A vista pela escada na área gourmet vale mesmo sem comprar.",t:["compras","luxo","ícone"]},
{c:"berlin",k:"compras",n:"Bikini Berlin",o:"Bikini Berlin",a:"Zoo",d:"1h30",p:"€€",w:"Shopping conceito dos anos 1950 reformado, com lojas de marcas jovens, jardim vertical interno e a vista para o recinto dos macacos do Zoo pela janela. Menos óbvio e mais interessante que os shoppings grandes.",t:["compras","design","chuva"]},
{c:"berlin",k:"compras",n:"Hackescher Markt e Hackesche Höfe",o:"Hackescher Markt",a:"Mitte",d:"2h",p:"€€",w:"Oito pátios conectados em estilo Art Nouveau com lojas de design, joalherias, ateliês e restaurantes, no coração de Mitte. É a melhor concentração de compras “de designer independente” da cidade — cuidado com o preço.",t:["compras","design","arquitetura","caminhada"]},
{c:"berlin",k:"compras",n:"Kurfürstendamm e Tauentzienstraße",o:"Kurfürstendamm",a:"Charlottenburg",d:"2h",p:"€€",w:"O eixo comercial clássico do lado ocidental, com lojas de departamento, grifes e o KaDeWe na ponta. Se você não gosta de shopping, a razão real de ir é caminhar e ver a igreja memorial do Kaiser Wilhelm quebrada pela guerra.",t:["compras","caminhada","ícone"]},
{c:"berlin",k:"compras",n:"Moda conceito e multimarcas",o:"Voo Store / Andreas Murkudis / Darklands",a:"Kreuzberg / Mitte / Schöneberg",d:"2h",p:"€€€",w:"A Voo Store, escondida num pátio em Kreuzberg, e a Andreas Murkudis, em Mitte, são as multimarcas que definem o estilo da cidade. A Darklands é referência mundial em estética dark/monocromática. Moda alemã e escandinava de verdade.",t:["compras","moda","design"]},
{c:"berlin",k:"compras",n:"Lojas de vinil",o:"Hard Wax / OYE Records / Rotation",a:"Kreuzberg / Neukölln",d:"2h",p:"€€",w:"A Hard Wax, em Kreuzberg, é uma das lojas de vinil de techno mais importantes do mundo — vende para DJs do planeta inteiro. A OYE Records e a Rotation completam o circuito. Mesmo sem comprar, é colinha com a cultura musical da cidade.",t:["compras","vinil","música","ícone"]},
{c:"berlin",k:"compras",n:"Dussmann das KulturKaufhaus",o:"Dussmann",a:"Mitte (Friedrichstraße)",d:"1h",p:"€€",w:"Livraria enorme em cinco andares com seção grande em inglês, CDs, DVDs e papelaria, aberta até tarde inclusive domingo. Ótima parada de dia frio ou quando você quer comprar um livro alemão para levar.",t:["compras","livros","chuva","domingo"]},
/* ---------- BERLIM · BATE-VOLTA ---------- */
{c:"berlin",k:"batevolta",n:"Potsdam — Sanssouci e o bairro holandês",o:"Potsdam / Schloss Sanssouci",a:"Potsdam",d:"Dia inteiro",p:"€€",w:"O palácio rococó de Frederico o Grande com o terraço de vinhedos, mais os jardins, o Neues Palais e o Moisés de Voltaire. A cidade ao lado tem o Holländisches Viertel (bairro holandês de tijolos vermelhos) e o Quartier Barberini. ~30 min de S-Bahn/trem do centro de Berlim.",t:["batevolta","arte","história","jardim","imperdível"]},
{c:"berlin",k:"batevolta",n:"Museum Barberini (Potsdam)",o:"Museum Barberini",a:"Potsdam",d:"2h",p:"€€",w:"O museu de arte do colecionador Hasso Plattner, com a coleção de impressionistas e pós-impressionistas mais importante da Alemanha fora de Berlim (Monet, Renoir, Signac). Fica no palácio reconstruído na praça central de Potsdam — encaixa perfeitamente no dia de Sanssouci.",t:["batevolta","arte","impressionismo"]},
{c:"berlin",k:"batevolta",n:"Memorial de Sachsenhausen",o:"Gedenkstätte Sachsenhausen",a:"Oranienburg",d:"Meio dia",p:"Grátis",w:"Campo de concentração a 40 minutos de Berlim, preservado e com exposição muito bem feita. Entrada gratuita, visita sóbria e cansativa — não encaixe nada pesado depois. Vá de trem até Oranienburg e de lá a pé ou de ônibus.",t:["batevolta","história","grátis","forte","solo"]},
{c:"berlin",k:"batevolta",n:"Dresden",o:"Dresden",a:"Saxônia (2h de trem)",d:"Dia inteiro",p:"€€",w:"A “Florença do Elba”: Frauenkirche, Zwinger, Residenzschloss, o terraço Brühl e o rio. Cidade destruída em 1945 e reconstruída peça por peça. É um dia longo (2h de trem cada trecho), mas um dos bate-voltas mais bonitos possíveis a partir de Berlim.",t:["batevolta","história","arte","arquitetura","dia inteiro"]},
{c:"berlin",k:"batevolta",n:"Leipzig",o:"Leipzig",a:"Saxônia (1h15 de ICE)",d:"Dia inteiro",p:"€€",w:"A cidade de Bach, da Nikolaikirche (onde começaram as manifestações pacíficas de 1989) e da Baumwollspinnerei, uma antiga fábrica de algodão ocupada por galerias de arte contemporânea. Menos turística que Dresden, mais viva, e mais perto.",t:["batevolta","arte","história","música"]},
{c:"berlin",k:"batevolta",n:"Hamburgo",o:"Hamburg",a:"Hamburgo (2h de ICE)",d:"Dia longo",p:"€€",w:"O porto, a Speicherstadt de tijolos sobre canais (Patrimônio Mundial), a Miniatur Wunderland e a Elbphilharmonie com vista da praça pública. 2h de trem — dá para fazer em um dia puxado ou dormir uma noite.",t:["batevolta","porto","arquitetura","dia inteiro"]},
{c:"berlin",k:"batevolta",n:"Spreewald — canais de Lübbenau",o:"Spreewald",a:"Lübbenau (1h20 de trem)",d:"Dia inteiro",p:"€€",w:"Rede de canais no meio da floresta, percorrida de barco a remo por um barqueiro que vai contando histórias. A região é a terra dos sórbios, povo eslavo com língua própria, e das conservas de pepino (Spreewälder Gurken). Em novembro os barcos ainda operam com agasalho.",t:["batevolta","natureza","água","cultura","longe"]},
{c:"berlin",k:"batevolta",n:"Sächsische Schweiz — montanhas de arenito",o:"Sächsische Schweiz / Elbsandsteingebirge",a:"Bad Schandau (2h15 de trem)",d:"Dia inteiro",p:"€€",w:"Trilhas entre torres de arenito, pontes de pedra sobre abismos e o desfiladeiro do Elba — é o parque nacional de escalada mais importante da Alemanha, com centenas de formações. Trilha de dia inteiro e bem séria; vá com bota e previsão boa. Vale pegar o trem das 6h.",t:["batevolta","trilha","natureza","dia inteiro","adrenalina"]},
{c:"berlin",k:"batevolta",n:"Wittenberg — cidade de Lutero",o:"Lutherstadt Wittenberg",a:"Saxônia-Anhalt (40min de ICE)",d:"Meio dia",p:"€€",w:"Onde Martinho Lutero afixou as 95 teses em 1517 e onde a Reforma começou: castelo, igreja de Todos os Santos, a casa de Lutero e de Melanchthon, tudo Patrimônio Mundial. Pertinho e quase vazio de turista — bom para meio dia.",t:["batevolta","história","grátis"]},
{c:"berlin",k:"batevolta",n:"Quedlinburg — cidade medieval",o:"Quedlinburg",a:"Saxônia-Anhalt (2h30)",d:"Dia inteiro",p:"€€",w:"Mais de 1.300 casas enxaimel preservadas, castelo no morro, igreja colegiada e ruas de paralelepípedo sem um carro sequer. Patrimônio Mundial e a cidade medieval mais bonita da Alemanha — em novembro com neblina fica ainda melhor.",t:["batevolta","história","arquitetura","dia inteiro"]},
{c:"berlin",k:"batevolta",n:"Harz — Brocken e Wernigerode",o:"Wernigerode / Brocken",a:"Harz (2h40 de trem)",d:"Dia inteiro",p:"€€",w:"Cidade enxaimel de Wernigerode aos pés do maciço do Harz, com trem a vapor histórica que sobe até o Brocken (1.141 m), o ponto mais alto do norte da Alemanha. Em novembro faz frio e vento de verdade — cachorro, neve e neblina são possíveis. Dia longo.",t:["batevolta","trilha","trem a vapor","natureza","dia inteiro"]},
{c:"berlin",k:"batevolta",n:"Frankfurt an der Oder — a fronteira polonesa",o:"Frankfurt (Oder) / Słubice",a:"Brandenburgo (1h de trem)",d:"Meio dia",p:"€",w:"Cidade dividida entre Alemanha e Polônia: atravesse a ponte a pé e você está em Słubice, comprando a preço polonês. Cidade pequena, reconstruída, sem turista nenhum. Bom se você quer a experiência de cruzar fronteira sem pegar avião.",t:["batevolta","fronteira","caminhada","longe"]},
{c:"berlin",k:"batevolta",n:"Rostock e Warnemünde — Mar Báltico",o:"Rostock / Warnemünde",a:"Mecklemburgo (2h30 de ICE)",d:"Dia longo",p:"€€",w:"Cidade hanseática de tijolos vermelhos mais o balneário de Warnemünde, com praia de areia larga, molhes e um farol. Em novembro o Báltico é cinza, ventoso e bonito de um jeito melancólico — leve roupa de frio grossa.",t:["batevolta","praia","arquitetura","dia inteiro","mar"]},
/* ---------- PARIS · SÓ NESTA DATA ---------- */
{c:"paris",k:"data",n:"PARIS PHOTO — 12 a 15/11 no Grand Palais",o:"Paris Photo 2026",a:"Grand Palais (8e)",d:"3–4h",p:"€€€",w:"A maior feira de fotografia do mundo cai INTEIRA na sua janela em Paris. 2026: dias 12 a 15 de novembro, das 13h às 20h (domingo até 19h), no Grand Palais. Você chega dia 13 de manhã, então dá para ir dia 13, 14 e/ou 15. Vale checar se há dia de abertura restrito a profissionais e comprar ingresso com data marcada. Se fotografia te interessa, é o evento-âncora da viagem.",t:["arte","fotografia","evento","imperdível"]},
{c:"paris",k:"data",n:"Made in France Expo — 12 a 15/11",o:"Made in France Expo",a:"Paris",d:"2–3h",p:"€–€€",w:"Feira de produtos fabricados na França, acontecendo nas mesmas datas do Paris Photo (12–15/11). Se você se interessa por produto, manufatura e marca — o que conecta com o seu trabalho —, é um passeio de negócio disfarçado de turismo: a 14ª edição é de 12 a 15 de novembro de 2026, na Porte de Versailles (Hall 7).",t:["evento","negócios","design"]},
{c:"paris",k:"data",n:"Iluminações de Natal das ruas",o:"Illuminations de Noël",a:"Champs-Élysées e centro",d:"1h30",p:"Grátis",w:"Paris acende as luzes de Natal em meados de novembro — a avenida Champs-Élysées, a rue Saint-Honoré, o Faubourg Saint-Honoré e o bairro do Marais costumam ser os primeiros. As datas variam a cada ano; pergunte na recepção do hotel ou confira o Sortir à Paris na semana. Se pegar, é um passeio noturno gratuito de primeira.",t:["noite","grátis","ao ar livre","verificar"]},
{c:"paris",k:"data",n:"Mercados de Natal (podem estar abrindo)",o:"Marchés de Noël de Paris",a:"Tuileries / Champs-Élysées / Jardin des Plantes",d:"2h",p:"Grátis",w:"Os grandes mercados de Natal de Paris costumam abrir em meados a fim de novembro, então suas datas (13–16/11) podem pegar a abertura. Os clássicos são o das Tuileries, o dos Champs-Élysées, o do Jardin des Plantes e o de Saint-Germain-des-Prés. Vale confirmar quais já abriram — se um estiver aberto, é vin chaud garantido.",t:["noite","comida","ao ar livre","verificar","família"]},
{c:"paris",k:"data",n:"13/11 — aniversário dos atentados de 2015",o:"Commémorations du 13 novembre",a:"11e / Saint-Denis",d:"—",p:"—",w:"13 de novembro é o aniversário dos ataques de 2015. Costuma haver cerimônias e reforço de segurança em pontos específicos (arredores do Bataclan, Le Carrefour Voltaire, Stade de France). Não muda o roteiro normal, mas evite contar com acesso desimpedido nessas áreas no fim da tarde e não estranhe revista reforçada. Trate com a discrição que o assunto pede.",t:["aviso","segurança","evento"]},
{c:"paris",k:"data",n:"Ciclo Wagner na Ópera — 06 a 22/11",o:"Der Ring des Nibelungen",a:"Ópera de Paris",d:"Noite",p:"€€€–€€€€",w:"Havia um ciclo de “O Anel do Nibelungo”, de Wagner, programado entre 6 e 22 de novembro — ou seja, durante a sua estada. É ópera em alemão, longa (4 a 5 horas por noite) e exige preparação, mas para quem gosta de música é uma experiência rara. Confirme casa (Bastille ou Garnier), datas exatas e disponibilidade no site da Ópera.",t:["ópera","erudito","noite","evento","verificar"]},
{c:"paris",k:"data",n:"O que você pega e o que você perde em novembro",o:"Calendário de novembro",a:"Paris",d:"—",p:"—",w:"PEGA: Paris Photo (12–15), iluminações de Natal começando e possível abertura de mercados. PERDE: Beaujolais Nouveau (terceira quinta, 19/11 — você já terá voltado para Colônia), Nuit Blanche (junho), Journées du Patrimoine (setembro) e a Feira do Chocolat, cujas datas variam (histórico de fim de outubro/início de novembro — confirme). Sabendo isso, você não perde tempo procurando o que não existe.",t:["aviso","planejamento","calendário"]},

/* ---------- PARIS · ARTE & MUSEUS ---------- */
{c:"paris",k:"arte",n:"Louvre",o:"Musée du Louvre",a:"1er",d:"Meio dia",p:"€€€",w:"O maior museu do mundo e o mais visitado: Mona Lisa, Vitória de Samotrácia, Vênus de Milo, as salas egípcias e as pinturas francesas. Reserve ingresso com hora marcada e entre pelo Porte des Lions ou pelo Carrousel do Louvre para não encarar a fila da pirâmide. Vá abrindo o museu, às 9h, e escolha dois ou três setores — tentar ver tudo é a receita para não ver nada.",t:["arte","chuva","imperdível","reservar"]},
{c:"paris",k:"arte",n:"Musée d'Orsay",o:"Musée d'Orsay",a:"7e",d:"3h",p:"€€€",w:"A antiga estação de trem convertida em museu do impressionismo: Monet, Renoir, Degas, Van Gogh, Toulouse-Lautrec. IMPORTANTE: o museu está em obra de renovação até o verão de 2028, mas segue aberto — algumas salas circulam. Confirme no site o que está exposto e reserve com horário. A quinta-feira costuma ter horário estendido à noite.",t:["arte","chuva","imperdível","obras","reservar"]},
{c:"paris",k:"arte",n:"Musée de l'Orangerie",o:"Musée de l'Orangerie",a:"1er (Tuileries)",d:"1h–1h30",p:"€€",w:"Duas salas ovais desenhadas para receber as Ninféias de Monet — a luz entra de cima e as telas dão a volta no ambiente. É um dos espaços mais bonitos e calmos de Paris, e o ingresso é combinado com o d'Orsay. Vá no fim do dia, quando a luz baixa entra nas salas.",t:["arte","chuva","imperdível","calmo"]},
{c:"paris",k:"arte",n:"Musée Rodin",o:"Musée Rodin",a:"7e (Invalides)",d:"2h",p:"€€",w:"Casa-ateliê de Rodin com esculturas espalhadas por um jardim maravilhoso — O Pensador e Os Portões do Inferno ao ar livre, com a cúpula dos Invalides em fundo. Um dos melhores programas para um dia de sol fraco de novembro: cruze o jardim e depois entre no museu.",t:["arte","jardim","ao ar livre"]},
{c:"paris",k:"arte",n:"Musée de Cluny — mundo medieval",o:"Musée de Cluny",a:"5e (Quartier Latin)",d:"1h30",p:"€€",w:"Termas romanas de 2.000 anos com um museu medieval construído em cima, incluindo a famosa tapeçaria da Dama do Unicórnio. É o museu mais antigo de Paris na sua forma mais inesperada: você desce e está literalmente dentro de uma casa de banho romana.",t:["arte","história","chuva","imperdível"]},
{c:"paris",k:"arte",n:"Musée du Quai Branly – Jacques Chirac",o:"Musée du Quai Branly",a:"7e",d:"2h",p:"€€",w:"Artes e civilizações da África, Ásia, Oceania e Américas, num prédio de Jean Nouvel com fachada viva e jardim vertical. Fica perto da Torre Eiffel, então encaixa perfeitamente num dia de Trocadéro. Há um debate importante sobre proveniência das peças — as exposições encaram isso.",t:["arte","chuva","jardim"]},
{c:"paris",k:"arte",n:"Musée de l'Armée e os Invalides",o:"Musée de l'Armée / Invalides",a:"7e",d:"2h",p:"€€",w:"O túmulo de Napoleão sob a cúpula dourada, mais o museu militar com armaduras, espadas e a história das duas guerras mundiais. Combina com o Museu Rodin ao lado e com a caminhada pela esplanada dos Invalides até o Sena.",t:["arte","história","chuva"]},
{c:"paris",k:"arte",n:"Musée Marmottan Monet",o:"Musée Marmottan Monet",a:"16e",d:"1h30",p:"€€",w:"O maior acervo de Monet do mundo, incluindo “Impressão, Sol Nascente” — o quadro que deu nome ao impressionismo. Fica numa mansão fora do circuito, com pouca fila e público mais local. Ótimo se você gosta de impressionismo e quer fugir do tumulto do Orsay.",t:["arte","menos turístico"]},
{c:"paris",k:"arte",n:"Musée Carnavalet — história de Paris",o:"Musée Carnavalet",a:"3e (Marais)",d:"2h",p:"Grátis",w:"A história de Paris da pré-história à Segunda Guerra, com cartazes, quadros, objetos, maquetes e a reconstituição do quarto de Proust. Acervo permanente GRATUITO, dentro de duas mansões no Marais — a melhor parada de graça da cidade.",t:["arte","história","grátis","chuva","imperdível"]},
{c:"paris",k:"arte",n:"Musée d'Art Moderne de Paris",o:"Musée d'Art Moderne de Paris",a:"16e (Trocadéro)",d:"2h",p:"Grátis (temporárias pagas)",w:"Fauvismo, cubismo, arte abstrata e contemporânea, incluindo o monumental “La Danse” de Matisse e a sala Raoul Dufy com o afresco da Fée Électricité. Coleção permanente gratuita num prédio art déco com vista para o Sena e a Torre.",t:["arte","grátis","chuva","vista"]},
{c:"paris",k:"arte",n:"Palais de Tokyo",o:"Palais de Tokyo",a:"16e",d:"2h",p:"€€",w:"O maior centro de arte contemporânea da Europa e o mais vivo: exposições enormes sem coleção permanente, curadorias ousadas, livraria excelente e bar. Aberto até meia-noite — é o único grande espaço de arte de Paris que funciona à noite, e o substituto natural do que você perdeu com o Pompidou fechado.",t:["arte","contemporânea","noite","alternativo","imperdível"]},
{c:"paris",k:"arte",n:"Bourse de Commerce — Coleção Pinault",o:"Bourse de Commerce",a:"1er (Les Halles)",d:"2h",p:"€€€",w:"A antiga bolsa de grãos transformada por Tadao Ando num cilindro de concreto dentro da rotunda de vidro, abrigando a coleção de arte contemporânea de François Pinault. Arquitetura e acervo no mesmo nível — um dos espaços de arte mais impressionantes de Paris hoje.",t:["arte","contemporânea","arquitetura","chuva","imperdível"]},
{c:"paris",k:"arte",n:"Fondation Louis Vuitton",o:"Fondation Louis Vuitton",a:"16e (Bois de Boulogne)",d:"3h",p:"€€€",w:"O edifício de Frank Gehry com as velas de vidro, no meio do Bois de Boulogne, com exposições temporárias de ponta e terraços que dão para os dois lados do parque. Vale pelo prédio tanto quanto pela mostra — reserve com hora marcada porque enche.",t:["arte","arquitetura","reservar","longe","imperdível"]},
{c:"paris",k:"arte",n:"Petit Palais",o:"Petit Palais",a:"8e",d:"1h30",p:"Grátis (temporárias pagas)",w:"Museu de Belas Artes da cidade de Paris em prédio de 1900 com cúpula, mosaicos e jardim interno — a coleção permanente é GRATUITA e quase vazia de gente. Fica em frente ao Grand Palais, então encaixa no mesmo dia do Paris Photo.",t:["arte","grátis","chuva","arquitetura","imperdível"]},
{c:"paris",k:"arte",n:"Musée des Arts Décoratifs",o:"Musée des Arts Décoratifs",a:"1er (Rivoli)",d:"2h",p:"€€",w:"Design de interiores, móveis, porcelana, vidro, brinquedos e moda, dentro de um pavilhão do Louvre. Boa mostra de design de produto — relevante se você se interessa por objeto e manufatura, não só por pintura.",t:["arte","design","chuva"]},
{c:"paris",k:"arte",n:"Palais Galliera — museu da moda",o:"Palais Galliera",a:"16e",d:"1h30",p:"€€",w:"O museu de moda da cidade de Paris, com exposições temporárias sobre costureiros, peças históricas e figurinos. Renova as mostras com frequência — vale checar o que está em cartaz na sua data. Fica perto do Palais de Tokyo e do Trocadéro.",t:["arte","moda","chuva"]},
{c:"paris",k:"arte",n:"Atelier des Lumières",o:"Atelier des Lumières",a:"11e",d:"1h30",p:"€€€",w:"Exposição imersiva de projeções gigantes sobre pintura, música e história, numa antiga fundição em Belleville. Funciona muito bem à noite e em dia de chuva. É espetáculo, não museu — escolha pela mostra em cartaz.",t:["arte","imersivo","chuva","noite"]},
{c:"paris",k:"arte",n:"Musée Gustave Moreau",o:"Musée Gustave Moreau",a:"9e",d:"1h",p:"€€",w:"O ateliê e a casa do pintor símbolo do simbolismo, preservados como ele deixou: três andares de quadros empilhados, escadas em caracol e uma luz dourada. Um dos museus mais atmosféricos e menos visitados de Paris.",t:["arte","escondido","chuva","imperdível"]},
{c:"paris",k:"arte",n:"Musée de la Chasse et de la Nature",o:"Musée de la Chasse et de la Nature",a:"3e (Marais)",d:"1h30",p:"€€",w:"Um museu peculiar dentro de um hôtel particulier no Marais: cabeças de animais montadas em salas de época, arte contemporânea no meio da coleção, sala do urso e sala da coruja. Temático, exótico e completamente diferente de qualquer outro museu da cidade.",t:["arte","exótico","chuva","escondido"]},
{c:"paris",k:"arte",n:"Musée Nissim de Camondo",o:"Musée Nissim de Camondo",a:"8e (Parc Monceau)",d:"1h30",p:"€€",w:"Mansão dos anos 1910 preservada intacta, com mobiliário francês do século XVIII, porcelana de Sèvres e uma história familiar trágica (o filho morreu na Primeira Guerra e a família foi deportada em 1943). Casa-museu que é também um memorial silencioso. Ao lado do Parc Monceau.",t:["arte","história","chuva","memória"]},
{c:"paris",k:"arte",n:"Institut du Monde Arabe",o:"Institut du Monde Arabe",a:"5e",d:"2h",p:"€€ (terraço grátis)",w:"Cultura e arte do mundo árabe num prédio de Jean Nouvel com os famosos mouch-arabes (diafragmas mecânicos na fachada que se abrem conforme a luz). A coleção é boa e o terraço no alto tem uma das melhores vistas de Notre-Dame e do Sena — de graça ou com consumação.",t:["arte","vista","chuva","cultura"]},
{c:"paris",k:"arte",n:"Musée de Montmartre",o:"Musée de Montmartre",a:"18e",d:"1h",p:"€€",w:"No prédio mais antigo de Montmartre, onde viveram Renoir, Suzanne Valadon e Utrillo, com vista para o vinhedo do Clos Montmartre e para os telhados. Pequeno, cheio de quadros e documentos, e no meio do bairro que você vai visitar de qualquer forma.",t:["arte","bairro","chuva","história"]},
{c:"paris",k:"arte",n:"Centre Pompidou — fechado até 2030: o que fazer no lugar",o:"Centre Pompidou (fermé)",a:"4e (Beaubourg)",d:"—",p:"—",w:"O Beaubourg está FECHADO para a grande renovação de 2025 a 2030 — não conte com ele. Substitutos diretos para arte moderna e contemporânea: Palais de Tokyo (aberto até meia-noite), Bourse de Commerce (Pinault), Musée d'Art Moderne de Paris (grátis), Fondation Louis Vuitton e o Musée Picasso no Marais. O prédio em si, com os tubos coloridos, continua visível por fora.",t:["fechado","arte","aviso"]},
/* ---------- PARIS · HISTÓRIA & MONUMENTOS ---------- */
{c:"paris",k:"historia",n:"Torre Eiffel",o:"Tour Eiffel",a:"7e (Champ de Mars)",d:"2–3h",p:"€€€ (subir)",w:"Ver de baixo é grátis e ver de cima é outra coisa. Reserve ingresso com horário no site oficial (ou suba pela escada até o 2º andar — mais barato e sem fila). À noite, do anoitecer até 1h da manhã, ela pisca por 5 minutos a cada hora cheia: planeje estar no Trocadéro ou no Champ de Mars nesse momento.",t:["história","vista","noite","reservar","imperdível"]},
{c:"paris",k:"historia",n:"Notre-Dame de Paris",o:"Cathédrale Notre-Dame",a:"4e (Île de la Cité)",d:"1h30",p:"Grátis (torres pagas)",w:"Reaberta em dezembro de 2024 depois do incêndio, com a pedra e os vitrais limpos e um novo percurso de visita. A entrada na catedral é gratuita (fila), mas as torres exigem ingresso com horário marcado e reserva — o acesso é limitado. A cripta arqueológica embaixo do parvis mostra a Paris romana.",t:["história","grátis","reservar","imperdível"]},
{c:"paris",k:"historia",n:"Sainte-Chapelle",o:"Sainte-Chapelle",a:"4e (Île de la Cité)",d:"1h",p:"€€",w:"A capela de Luís IX com 1.113 vitrais que contam a história bíblica do chão ao teto, sustentados por colunas finíssimas. Em dia de sol claro é deslumbrante; em dia nublado, mais escura. Há concertos clássicos à noite dentro da capela — a melhor forma de visitá-la é com música.",t:["história","arte","vitral","concerto","imperdível"]},
{c:"paris",k:"historia",n:"Conciergerie",o:"Conciergerie",a:"4e (Île de la Cité)",d:"1h",p:"€€",w:"O palácio medieval que virou prisão durante a Revolução, onde Maria Antonieta ficou presa antes da guilhotina. As salas góticas com as colunas gigantes e a cela reconstituída dão o tom. Fica no mesmo complexo da Sainte-Chapelle — compre o ingresso combinado.",t:["história","chuva"]},
{c:"paris",k:"historia",n:"Panthéon",o:"Panthéon",a:"5e (Quartier Latin)",d:"1h30",p:"€€",w:"A cripta onde estão Voltaire, Rousseau, Victor Hugo, Zola, Marie Curie e Simone Veil, mais o pêndulo de Foucault pendurado sob a cúpula. Recentemente abriu a subida à cúpula, com uma das melhores vistas do Quartier Latin — vale checar disponibilidade de horário.",t:["história","arte","vista"]},
{c:"paris",k:"historia",n:"Arco do Triunfo",o:"Arc de Triomphe",a:"8e (Étoile)",d:"1h",p:"€€",w:"O mirante no topo é o melhor lugar para ver a estrela de doze avenidas que Haussmann desenhou, com a Torre Eiffel de um lado e a La Défense do outro. Vá no fim da tarde para ver a cidade acender; a subida é por escada em caracol, sem elevador.",t:["história","vista","pôr do sol","imperdível"]},
{c:"paris",k:"historia",n:"Sacré-Cœur e a Basílica",o:"Basilique du Sacré-Cœur",a:"18e (Montmartre)",d:"1h30",p:"Grátis (cúpula €)",w:"A basílica branca no ponto mais alto da cidade, com a cripta e a subida à cúpula para a vista mais ampla de Paris. Ao lado, a Place du Tertre com pintores, o que sobrou da boemia de Montmartre. Vá no fim do dia e desça pela rue Lepic.",t:["história","vista","grátis","pôr do sol"]},
{c:"paris",k:"historia",n:"Opéra Garnier",o:"Palais Garnier",a:"9e",d:"1h30",p:"€€",w:"A ópera de 1875 que inspirou “O Fantasma da Ópera”: escadaria de mármore, grande foyer com espelhos dourados, teto pintado por Chagall (1964) e o lago subterrâneo que existe de verdade. Existe visita guiada com acesso aos bastidores, que vale muito mais do que a visita livre.",t:["história","arte","arquitetura","imperdível","reservar"]},
{c:"paris",k:"historia",n:"Palais Royal e as Colunas de Buren",o:"Palais Royal",a:"1er",d:"45min",p:"Grátis",w:"O jardim fechado do Palais Royal com as 260 colunas de mármore listrado de Daniel Buren no pátio de honra (inauguradas em 1986, na época muito polêmicas) e os arcos onde ficam as galerias e o Ministério da Cultura. Escondido, bonito e quase sem turista. Ao lado do Louvre e do Passagem Vivienne.",t:["ao ar livre","grátis","arte","jardim","escondido"]},
{c:"paris",k:"historia",n:"Place des Vosges e o Marais histórico",o:"Place des Vosges",a:"4e (Marais)",d:"45min",p:"Grátis",w:"A praça mais antiga de Paris (1612), simétrica e de tijolos vermelhos, antiga praça real e depois centro da aristocracia. A casa de Victor Hugo fica num canto (entrada gratuita). Praça perfeita para sentar, piquenique ou apenas descansar no meio da caminhada pelo Marais.",t:["ao ar livre","grátis","história","arquitetura"]},
{c:"paris",k:"historia",n:"Cemitério do Père-Lachaise",o:"Cimetière du Père-Lachaise",a:"20e",d:"2h",p:"Grátis",w:"Mais museu ao ar livre do que cemitério: Oscar Wilde (com o túmulo beijado), Jim Morrison, Chopin, Edith Piaf, Proust, Molière. As lápides e mausoléus cobrem morros inteiros e há um mapa na entrada. Um dos passeios mais bonitos e gratuitos de Paris, especialmente com as árvores de novembro.",t:["ao ar livre","grátis","história","caminhada","solo"]},
{c:"paris",k:"historia",n:"Catacumbas de Paris",o:"Catacombes de Paris",a:"14e (Denfert-Rochereau)",d:"1h30",p:"€€€",w:"Quilômetros de galerias subterrâneas forradas com os ossos de cerca de 6 milhões de parisienses, transferidos dos cemitérios no século XVIII. Tem que reservar com horário e descer 130 degraus — faz frio e a saída é em outra rua. Fecha às 20h30, última entrada mais cedo.",t:["história","chuva","reservar","inusitado","imperdível"]},
{c:"paris",k:"historia",n:"Basílica de Saint-Denis",o:"Basilique de Saint-Denis",a:"Saint-Denis (30min)",d:"1h30",p:"€€",w:"A primeira catedral gótica do mundo (século XII) e a necrópole dos reis da França, com 43 reis e 32 rainhas enterrados em monumentos esculpidos. Fica fora do centro, na região da estação, quase sem turista. Junte com uma caminhada pela cidade e pelo mercado.",t:["história","arte","longe","menos turístico"]},
{c:"paris",k:"historia",n:"Château de Vincennes",o:"Château de Vincennes",a:"Vincennes (linha 1)",d:"1h30",p:"€€",w:"Muito mais impressionante do que a fama sugere: um castelo medieval de verdade, cercado por fosso profundo, com a torre do homenagem mais alta fortaleza da Europa, capela e celas. Fim de linha do metrô 1, ao lado do Bois de Vincennes — encaixa com parque no mesmo dia.",t:["história","chuva","longe","imperdível"]},
{c:"paris",k:"historia",n:"Mémorial de la Shoah",o:"Mémorial de la Shoah",a:"3e (Marais)",d:"2h",p:"Grátis",w:"O memorial do Holocausto na França, com o Muro dos Nomes (76 mil judeus deportados da França) e uma exposição histórica muito bem documentada. Entrada gratuita, no Marais. Forte e necessário — não encaixe nada leve em seguida.",t:["história","grátis","memória","forte","solo"]},
{c:"paris",k:"historia",n:"Memorial dos Mártires da Deportação",o:"Mémorial des Martyrs de la Déportation",a:"4e (ponta da Île de la Cité)",d:"30min",p:"Grátis",w:"Escondido atrás de Notre-Dame, num desnível na ponta da Île de la Cité: uma sala estreita de concreto com 200 mil pontos de luz cravados nas paredes, representando os deportados franceses. Gratuito, silencioso e de um design devastador.",t:["história","grátis","solo","escondido"]},
{c:"paris",k:"historia",n:"Cripta arqueológica do parvis de Notre-Dame",o:"Crypte archéologique",a:"4e",d:"1h",p:"€€",w:"Escavações que mostram 2.000 anos de ocupação do local: casas galo-romanas, o porto antigo, a muralha de Luís o Gordo e as fundações de construções anteriores. Boa parada de chuva no mesmo dia de Notre-Dame e Sainte-Chapelle.",t:["história","chuva","arte"]},
{c:"paris",k:"historia",n:"Cemitério de Montparnasse",o:"Cimetière du Montparnasse",a:"14e",d:"1h30",p:"Grátis",w:"O outro grande cemitério de Paris, com Sartre e Simone de Beauvoir, Baudelaire, Serge Gainsbourg, Cortázar, Man Ray e Susan Sontag. Mais tranquilo e mais literário que o Père-Lachaise, ao lado dos cafés de Montparnasse que estão no item de bairro.",t:["ao ar livre","grátis","história","caminhada"]},
{c:"paris",k:"historia",n:"Visitas guiadas a instituições: Hôtel de Ville, Sénat, Assemblée",o:"Visites de l'Hôtel de Ville / Sénat / Assemblée nationale",a:"Marais / 6e / 7e",d:"1h30",p:"Grátis (reserva obrigatória)",w:"Câmara municipal, Senado (no Palais du Luxembourg) e Assembleia Nacional oferecem visitas guiadas gratuitas que precisam ser reservadas bem antes, com documento. É uma forma de entrar em prédios normalmente fechados e ver o ritual republicano francês de dentro. Vale agendar antes de viajar.",t:["história","grátis","reservar","político"]},
{c:"paris",k:"historia",n:"La Défense e a Grande Arche",o:"La Défense",a:"Puteaux (RER A / linha 1)",d:"2h",p:"Grátis (mirante €)",w:"O bairro de negócios no fim do eixo histórico, com a Grande Arche (um cubo vazado do qual se vê a Avenue Charles de Gaulle alinhada com o Arco do Triunfo), esculturas ao ar livre e arquitetura de César Pelli, Jean Nouvel e outros. Contraste absoluto com a Paris histórica — 15 minutos de metrô.",t:["arquitetura","ao ar livre","arte","vista"]},
{c:"paris",k:"historia",n:"Le Train Bleu — a brasserie da Gare de Lyon",o:"Le Train Bleu",a:"12e (Gare de Lyon)",d:"1h30",p:"€€–€€€",w:"A brasserie de 1901 dentro da Gare de Lyon, com salões pintados, teto dourado e lustres — um monumento Belle Époque que virou restaurante. Mesmo que o preço não convença, vale entrar para tomar um café ou um drink e ver o salão. Fica no caminho se você pegar trem em Gare de Lyon.",t:["comida","história","arquitetura","escondido"]},
{c:"paris",k:"historia",n:"As pontes do Sena",o:"Pont Neuf / Pont Alexandre III / Pont de Bir-Hakeim",a:"Sena",d:"1h30",p:"Grátis",w:"Caminhada por três pontes com personalidades muito diferentes: a Pont Neuf (a mais antiga de Paris, 1607), a Pont Alexandre III (a mais ornamentada, com o Grand Palais e os Invalides nas pontas) e a Pont de Bir-Hakeim (a de dois andares sobre o metrô, cenário de filmes). De graça e é literalmente o melhor de Paris.",t:["ao ar livre","grátis","caminhada","fotografia"]},
{c:"paris",k:"historia",n:"Tour Saint-Jacques",o:"Tour Saint-Jacques",a:"4e",d:"1h",p:"€€€",w:"A torre gótica que sobra de uma igreja demolida na Revolução, com vista de 360° a 54 m e visita guiada a pé (54 degraus + 300 degraus, em grupo pequeno com guia obrigatório). ATENÇÃO: está fechada para obras, e a temporada normal vai de meados de maio a meados de novembro, só de quarta a domingo — em novembro de 2026, confirme antes de contar com ela. Uma das vistas menos vistas de Paris.",t:["história","vista","reservar","fechado"]},

/* ---------- PARIS · BAIRROS & CAMINHADA ---------- */
{c:"paris",k:"bairro",n:"Le Marais",o:"Le Marais",a:"3e / 4e",d:"Meio dia",p:"Grátis",w:"O bairro mais completo para caminhar em Paris: mansões históricas (hôtels particuliers), a Place des Vosges, a rue des Rosiers com falafel e a comunidade judaica, brechós vintage, galerias de arte contemporânea, o Museu Picasso, o Carnavalet e a vida LGBTQIA+ concentrada. Vá num sábado se puder — mas em novembro qualquer dia funciona.",t:["caminhada","ao ar livre","compras","comida","gay-friendly","imperdível"]},
{c:"paris",k:"bairro",n:"Montmartre",o:"Montmartre",a:"18e",d:"3h",p:"Grátis",w:"Suba pela rue Lepic (evitando o funicular e a escadaria lotada), passe pelo Moulin de la Galette, o muro do “Je t'aime” e a Place du Tertre, e desça pelo lado leste até o mercado Saint-Pierre. Quanto mais você sobe, mais o bairro vira vilarejo. Melhor no fim de tarde, com a cidade acendendo embaixo.",t:["caminhada","ao ar livre","vista","história","imperdível"]},
{c:"paris",k:"bairro",n:"Canal Saint-Martin e Belleville",o:"Canal Saint-Martin / Belleville",a:"10e / 11e / 19e-20e",d:"3h",p:"Grátis",w:"A Paris mais jovem e mais viva: a água do canal com as comportas e passarelas de ferro, cafés e bares em barcaças, depois subida até Belleville com o parque no alto (vista aberta sobre a cidade), street art pela rue Denoyez e os ateliês de artistas chineses. Onde os parisienses realmente moram.",t:["caminhada","ao ar livre","arte","alternativo","vista"]},
{c:"paris",k:"bairro",n:"Butte-aux-Cailles",o:"Butte-aux-Cailles",a:"13e",d:"1h30",p:"Grátis",w:"Vila boêmia em ruas de paralelepípedo com casas baixas e jardins, bares de esquina e street art. Foi um bairro operário e virou refúgio de estudantes e artistas que saíram do Marais quando os aluguéis subiram. Quase nenhum turista e uma das piscinas art déco mais bonitas da cidade fica ali.",t:["caminhada","ao ar livre","alternativo","escondido"]},
{c:"paris",k:"bairro",n:"Pigalle, South Pigalle e Nouvelle Athènes",o:"Pigalle / SoPi",a:"9e / 18e",d:"2h30",p:"Grátis",w:"Pigalle clássico dos cabarés, a rue des Martyrs cheia de padarias e lojas de comida, e a Nouvelle Athènes com casas de artistas do século XIX (George Sand, Chopin, Toulouse-Lautrec). South Pigalle virou área de bares e restaurantes descolados. Caminhada noturna muito boa — é aqui que está a vida noturna adulta de Paris.",t:["caminhada","noite","bar","história","comida"]},
{c:"paris",k:"bairro",n:"Saint-Germain-des-Prés",o:"Saint-Germain-des-Prés",a:"6e",d:"2h",p:"Grátis",w:"O bairro dos cafés literários — Les Deux Magots, Café de Flore, Brasserie Lipp — onde Sartre, Beauvoir e Hemingway circulavam. Hoje é caro e cheio, mas ainda vale caminhar pelas ruas de galerias de arte (rue de Seine, rue Jacob) e entrar na livraria La Hune. Vá de manhã, antes do movimento.",t:["caminhada","café","história","compras"]},
{c:"paris",k:"bairro",n:"Quartier Latin e rue Mouffetard",o:"Quartier Latin",a:"5e",d:"2h30",p:"Grátis",w:"A Sorbonne, o Panthéon, o Jardim de Luxembourg e a rue Mouffetard, uma das ruas de mercado mais antigas de Paris, cheia de barracas, queijos, padarias e bistrôs baratos. Fim de tarde na Mouffetard é barulhento, vivo e bom. Termine no Luxemburgo ou no Arènes de Lutèce (anfiteatro romano).",t:["caminhada","comida","mercado","barato"]},
{c:"paris",k:"bairro",n:"Île de la Cité e Île Saint-Louis",o:"Île de la Cité / Île Saint-Louis",a:"4e",d:"2h",p:"Grátis",w:"O berço de Paris: Notre-Dame, Sainte-Chapelle, a Conciergerie e, do outro lado da ponte, a Île Saint-Louis com a sorveteria Berthillon, ruas estreitas, antiquários e casas de 1640. A caminhada pela ponta ocidental da ilha, no Quai d'Orléans, é um dos lugares mais bonitos e tranquilos da cidade.",t:["caminhada","ao ar livre","grátis","história"]},
{c:"paris",k:"bairro",n:"Champs-Élysées e Avenue Montaigne",o:"Champs-Élysées",a:"8e",d:"2h",p:"Grátis",w:"A avenida mais famosa do mundo: do Arco do Triunfo até a Place de la Concorde, passando por cinema, carros, lojas e o Grand Palais. Já foi mais charmosa; hoje é comercial e cheia. O motivo real de passar por ali é o eixo histórico — e ver o cotidiano parisiense do luxo na Avenue Montaigne e na rue du Faubourg Saint-Honoré.",t:["caminhada","compras","luxo","ícone"]},
{c:"paris",k:"bairro",n:"Trocadéro e Passy",o:"Trocadéro / Passy",a:"16e",d:"1h30",p:"Grátis",w:"A esplanada do Trocadéro é o melhor ponto para ver a Torre Eiffel de frente, e dali você desce pelos jardins até o Sena e atravessa para a Torre. Do lado de Passy há a rue de Passy com comércio local e os jardins do Trocadéro. Vá no fim do dia e fique para a torre acender.",t:["caminhada","ao ar livre","vista","grátis","pôr do sol"]},
{c:"paris",k:"bairro",n:"Sentier, rue Montorgueil e as passagens cobertas",o:"Passages couverts",a:"2e / 9e",d:"2h30",p:"Grátis",w:"O circuito das passagens cobertas do século XIX — Passage des Panoramas, Jouffroy, Verdeau, Vivienne, Brady, Choiseul — com piso de mosaico, livrarias antigas, selarias, lojas de filatelia e bistrôs escondidos. Ligado pela rue Montorgueil (rua de mercado com ostras, queijos e cafés). O MELHOR programa de dia de chuva em Paris.",t:["caminhada","chuva","compras","comida","imperdível"]},
{c:"paris",k:"bairro",n:"Place Vendôme e Faubourg Saint-Honoré",o:"Place Vendôme",a:"1er / 8e",d:"1h",p:"Grátis",w:"A praça da coluna de Napoleão com as joalherias mais caras do mundo ao redor, mais a rue Saint-Honoré e a Faubourg Saint-Honoré com as grifes de luxo e as vitrines de Natal. Se você trabalha com comércio, é uma aula de varejo de luxo. E o Hôtel Ritz e o Ministério da Justiça estão ali.",t:["compras","luxo","caminhada","arquitetura"]},
{c:"paris",k:"bairro",n:"Bastille, Viaduc des Arts e a Coulée Verte",o:"Coulée verte René-Dumont",a:"11e / 12e",d:"2h",p:"Grátis",w:"A Bastille com a Ópera moderna e a coluna de Julho, depois o Viaduc des Arts (arcos do viaduto ocupados por ateliês de artesãos) e, em cima dele, a Coulée Verte René-Dumont — o antigo elevado ferroviário transformado em jardim suspenso, o precursor da High Line de Nova York. Andar por ali é um dos segredos mais gostosos de Paris.",t:["caminhada","jardim","ao ar livre","grátis","arte","imperdível"]},
{c:"paris",k:"bairro",n:"La Villette",o:"Parc de la Villette",a:"19e",d:"3h",p:"Grátis (museus pagos)",w:"O maior parque cultural de Paris: Cité des Sciences, Cité de la Musique, a sala do trampolim (foie du parc), os jardins temáticos projetados por Tschumi e a Philharmonie de Paris ao lado. Bairro jovem, diversos, com canais. Tem programa cultural quase todos os dias — confira a agenda.",t:["ao ar livre","arte","música","família","jardim"]},
{c:"paris",k:"bairro",n:"Bercy, Parque de Bercy e a BnF",o:"Bercy Village",a:"12e",d:"2h",p:"Grátis",w:"Bercy Village ocupa antigos armazéns de vinho com lojas e restaurantes dentro dos barris de pedra; ao lado, o Parc de Bercy com jardins, lagos e a passarela Simone-de-Beauvoir que atravessa o Sena. Do outro lado fica a Biblioteca Nacional François-Mitterrand, com as quatro torres em forma de livro aberto.",t:["caminhada","ao ar livre","arquitetura","jardim"]},
{c:"paris",k:"bairro",n:"Buttes-Chaumont e o Parc",o:"Parc des Buttes-Chaumont",a:"19e",d:"1h30",p:"Grátis",w:"Parque desenhado por Haussmann em cima de pedreiras e terreno ingreme: falésias, ponte suspensa, templo no alto de uma rocha no meio do lago e canais. É o parque mais dramático de Paris e o menos turístico entre os grandes. Vá ao fim da tarde para ver a cidade por cima dos telhados.",t:["jardim","ao ar livre","caminhada","vista","grátis"]},
{c:"paris",k:"bairro",n:"Boulogne-Billancourt e o Jardim Albert Kahn",o:"Musée Albert Kahn",a:"Boulogne (linha 10)",d:"2h",p:"€",w:"O jardim mais bonito e inesperado perto de Paris: o banqueiro Albert Kahn criou um “jardim do mundo” com paisagens japonesa, inglesa, francesa e floresta vosgienne, mais uma aldeia japonesa com casas tradicionais. No outono as cores ficam impressionantes. Perto do fim da linha 10, muito pouco turista.",t:["jardim","ao ar livre","escondido","fotografia","imperdível"]},
/* ---------- PARIS · TRILHAS & NATUREZA ---------- */
{c:"paris",k:"natureza",n:"Bois de Boulogne",o:"Bois de Boulogne",a:"16e",d:"3h",p:"Grátis",w:"846 hectares de floresta no limite oeste da cidade, com lagos, cascatas, o Jardin des Serres d'Auteuil (estufas históricas), o Parc de Bagatelle com seu roseiral e a Fondation Louis Vuitton dentro. Dá para fazer trilha sem sair de Paris — e em novembro as cores das folhas estão no ponto.",t:["trilha","ao ar livre","grátis","bicicleta","jardim"]},
{c:"paris",k:"natureza",n:"Bois de Vincennes",o:"Bois de Vincennes",a:"12e",d:"3h",p:"Grátis",w:"O outro pulmão de Paris, no lado leste: lago de Daumesnil com os dois templos, o Parc Floral, o zoológico e o Château de Vincennes na ponta. Menos frequentado que o Boulogne e com mais gente local fazendo corrida e caminhada. Bom para um domingo de manhã.",t:["trilha","ao ar livre","grátis","jardim","domingo"]},
{c:"paris",k:"natureza",n:"Floresta de Fontainebleau — a trilha dos 25 Bosses",o:"Forêt de Fontainebleau / Trois Pignons",a:"Fontainebleau (45min de trem)",d:"Dia inteiro",p:"€€ (trem)",w:"A melhor trilha de verdade perto de Paris: cerca de 14 km subindo e descendo 25 colinas de arenito, com areia, raízes e vistas. É também a meca europeia do boulder — se você escala, Trois Pignons é parada obrigatória. A 45 minutos de trem da Gare de Lyon, com trilha sinalizada.",t:["trilha","natureza","dia inteiro","escalada","batevolta","imperdível"]},
{c:"paris",k:"natureza",n:"Vallée de Chevreuse",o:"Parc naturel régional de la Vallée de Chevreuse",a:"Yvelines (RER B)",d:"Dia inteiro",p:"€ (RER)",w:"Parque natural a uma hora de RER B do centro, com trilhas entre campos, bosques, aldeias de pedra e o château de Dampierre e de Breteuil. É o campo de verdade mais acessível a partir de Paris, com circuitos de 8 a 20 km marcados. Vá de manhã cedo e leve comida.",t:["trilha","natureza","dia inteiro","batevolta","campo"]},
{c:"paris",k:"natureza",n:"Floresta de Saint-Germain-en-Laye",o:"Forêt de Saint-Germain-en-Laye",a:"Yvelines (RER A)",d:"3h",p:"€ (RER)",w:"Trilha em floresta a 30 minutos de RER A, com o terraço do castelo no fim dando vista do vale do Sena até La Défense. Dá para combinar com a cidade real de Saint-Germain, o museu das Antiguidades Nacionais e o mercado. Bate-volta de meio dia, sem carro.",t:["trilha","natureza","batevolta","fácil"]},
{c:"paris",k:"natureza",n:"Floresta de Rambouillet",o:"Forêt de Rambouillet",a:"Yvelines (1h de trem)",d:"Dia inteiro",p:"€€ (trem)",w:"Grande maciço florestal com trilhas sinalizadas, lagoas, cervos e o Château de Rambouillet com a Chaumière aux Coquillages (gruta revestida de conchas). Menos movimentada que Fontainebleau, com quilômetros de trilha para fazer sozinho.",t:["trilha","natureza","dia inteiro","batevolta","solo"]},
{c:"paris",k:"natureza",n:"Parc de Sceaux",o:"Parc de Sceaux",a:"Hauts-de-Seine (RER B)",d:"2h",p:"Grátis",w:"Jardim desenhado por André Le Nôtre (o mesmo de Versailles) com o canal central, o Grande Cascade e o Château de Sceaux com museu. 30 minutos de RER B e a entrada é gratuita — um dos melhores custo-benefício de Paris num dia de sol.",t:["jardim","ao ar livre","grátis","batevolta","fotografia"]},
{c:"paris",k:"natureza",n:"Petite Ceinture — trilha urbana no antigo anel ferroviário",o:"Petite Ceinture",a:"12e / 15e / 16e",d:"2h",p:"Grátis",w:"Trechos da antiga linha ferroviária que cercava Paris, abandonada e hoje transformada em corredor verde, com trilhos, túneis, paredões grafitados e vegetação tomando conta. Vários acessos são abertos ao público por temporada — confirme quais trechos estão abertos na sua data.",t:["trilha","urbano","ao ar livre","grátis","alternativo","verificar"]},
{c:"paris",k:"natureza",n:"Escalada e boulder indoor",o:"Arkose / Climbing District / Vertical'Art",a:"Várias unidades",d:"2h",p:"€€",w:"Paris tem uma das melhores redes de academia de escalada da Europa, com muros altos e boulders em antigas fábricas — a Climbing District da Villette e as Arkose são as mais impressionantes. Aluguel de material no local. Bom programa de chuva e para um dia sem andar pela cidade.",t:["chuva","esporte","grupo"]},
{c:"paris",k:"natureza",n:"Parc de Saint-Cloud e a floresta de Meudon",o:"Parc de Saint-Cloud",a:"Hauts-de-Seine (linha 10 / tram)",d:"2–3h",p:"Grátis",w:"O grande parque de Le Nôtre no morro acima do Sena, com cascatas, jardins históricos e uma das vistas mais amplas de Paris a partir da Grande Perspective. Ao lado, a floresta de Meudon e o observatório. Fim de tarde aqui, com a cidade acesa ao longe, é difícil de superar.",t:["jardim","ao ar livre","grátis","vista","batevolta"]},

/* ---------- PARIS · NOTURNO & VISTAS ---------- */
{c:"paris",k:"noturno",n:"Torre Eiffel à noite e a hora piscante",o:"Tour Eiffel illuminée",a:"7e / Trocadéro",d:"1h30",p:"Grátis",w:"A cada hora cheia, do anoitecer até 1h da manhã, a Torre pisca por cinco minutos — e é melhor assistir do Trocadéro, do Champ de Mars ou de um barco no Sena. Programe o jantar para terminar ao lado dela às 20h ou 21h. É gratuito e é provavelmente a melhor lembrança da viagem.",t:["noite","grátis","vista","imperdível"]},
{c:"paris",k:"noturno",n:"Tour Montparnasse — o melhor mirante de Paris",o:"Tour Montparnasse",a:"15e (Montparnasse)",d:"1h30",p:"€€€",w:"O mirante mais alto do centro de Paris, e o truque é óbvio: é o único lugar de onde você vê a Torre Eiffel, porque de todos os outros mirantes ela é que está na foto. Terraço a céu aberto, aberto até tarde e com bar no alto. Suba 30 minutos antes do pôr do sol (em novembro, ~17h10) e fique pelos dois lados.",t:["noite","vista","pôr do sol","imperdível"]},
{c:"paris",k:"noturno",n:"Rooftop das Galeries Lafayette (grátis)",o:"Galeries Lafayette Haussmann",a:"9e (Boulevard Haussmann)",d:"45min",p:"Grátis",w:"O terraço no alto das Galeries Lafayette é de graça, tem vista direta para a Ópera Garnier, a Tour Eiffel e os telhados de Haussmann. Vá no fim da tarde. A cúpula de vitral da loja por dentro já vale a entrada, e a partir de meados de novembro há as vitrines e as luzes de Natal.",t:["noite","vista","grátis","pôr do sol","compras"]},
{c:"paris",k:"noturno",n:"Cruzeiro no Sena",o:"Croisière sur la Seine",a:"Port d'Alma / Pont Neuf / Torre Eiffel",d:"1h–2h",p:"€€",w:"O passeio de barco iluminado com a Torre, o Louvre, Notre-Dame e as pontes passando por cima é turístico, sim — e continua sendo uma das melhores formas de ver Paris à noite. Vá no último horário, quando a cidade já está toda acesa. Existe versão simples (barco) e versão com jantar.",t:["noite","vista","água","turístico","imperdível"]},
{c:"paris",k:"noturno",n:"Rooftop bars e hotéis com vista",o:"Le Perchoir / Mama Shelter / Terrass\" / Le Déli-Cieux",a:"Ménilmontant / 11e / 18e",d:"2h",p:"€€–€€€",w:"O circuito de terraços de Paris: Le Perchoir (Ménilmontant, o original, e as unidades do Marais e da Tour Eiffel), Mama Shelter com vista da cidade, o Terrass\" em Montmartre mirando a Torre e o Le Déli-Cieux no Printemps. Reserve quando possível — em novembro muitos fecham as áreas externas, mas os fechados com vista seguem funcionando.",t:["bar","noite","vista","coquetel"]},
{c:"paris",k:"noturno",n:"Jazz no Caveau de la Huchette",o:"Caveau de la Huchette",a:"5e (Quartier Latin)",d:"3h",p:"€€",w:"Cave abobadada do século XVI onde se toca jazz ao vivo desde 1946, com pista de dança, jazz tradicional e swing. Público misto de turista, morador e gente dançando bem de verdade. Sente cedo, porque a sala é pequena e enche — e é provavelmente o melhor lugar de jazz de Paris para não especialista.",t:["jazz","noite","dança","histórico","imperdível"]},
{c:"paris",k:"noturno",n:"Jazz em Châtelet — Duc des Lombards e Le Sunside",o:"Le Duc des Lombards / Sunset-Sunside",a:"1er / Châtelet",d:"2h",p:"€€",w:"A rue des Lombards concentra três clubes de jazz colados, com programação quase toda noite — o Duc des Lombards é o mais sério, o Sunside aposta em jovens e o Sunset em fusão. Dá para comprar ingresso barato na hora em muitos casos. Melhor que qualquer “show de cabaré”.",t:["jazz","noite","música ao vivo"]},
{c:"paris",k:"noturno",n:"Cabarés: Moulin Rouge, Crazy Horse, Paradis Latin, Madame Arthur",o:"Cabarets parisiens",a:"18e / 8e / 5e",d:"2h30",p:"€€€–€€€€",w:"O Moulin Rouge é o clássico e o mais caro; o Crazy Horse aposta na dança contemporânea e na Coreografia; o Paradis Latin é o show mais teatral e divertido; e o MADAME ARTHUR, em Pigalle, é um cabaré drag com plateia jovem e lotada — de longe o mais divertido e o mais barato do grupo. Reserve com antecedência.",t:["noite","show","drag","turístico","reservar"]},
{c:"paris",k:"noturno",n:"Concerto à luz de velas",o:"Concerts aux chandelles",a:"Sainte-Chapelle / Saint-Sulpice / Saint-Éphrem",d:"1h30",p:"€€–€€€",w:"Concertos clássicos de uma hora em igrejas iluminadas por centenas de velas, com Vivaldi, Bach, Schubert ou trilhas de cinema. É curto, bonito, acessível e num espaço que você já quer ver de qualquer forma. Na Sainte-Chapelle, com os vitrais iluminados, é provavelmente a melhor porta de entrada noturna em Paris.",t:["concerto","noite","erudito","romântico","imperdível"]},
{c:"paris",k:"noturno",n:"Cinémathèque française e cinemas de arte",o:"Cinémathèque française / Le Champo / Studio 28",a:"12e / 5e / 18e",d:"2h",p:"€€",w:"A Cinémathèque (no prédio de Frank Gehry em Bercy) tem sessões, retrospectivas e exposições sobre cinema — e o museu Méliès com objetos originais. O Le Champo, no Quartier Latin, e o Studio 28, em Montmartre, são cinemas históricos que exibem clássicos em versão original. Custa pouco e é outra Paris.",t:["cinema","noite","erudito","barato"]},
{c:"paris",k:"noturno",n:"Paris iluminada a pé: Sena, Île Saint-Louis e Louvre",a:"Caminhada noturna",a:"1er / 4e / 5e",d:"2h",p:"Grátis",w:"O melhor passeio noturno gratuito de Paris: comece no Hôtel de Ville iluminado, atravesse para a Île Saint-Louis, caminhe pelo Quai d'Orléans, siga pelo Sena até o Louvre com a pirâmide acesa e termine na Pont des Arts. Tudo de graça, com pouca gente em novembro, e a cidade inteira funcionando ao redor.",t:["noite","grátis","caminhada","ao ar livre","imperdível"]},
{c:"paris",k:"noturno",n:"Tour noturno de bicicleta ou tuk-tuk elétrico",o:"Vélo nocturne / Tuk-tuk",a:"Centro",d:"2–3h",p:"€€",w:"Há tours guiados de bike à noite, passando por pontos iluminados, e também os tuk-tuks elétricos que atendem turista com roteiro personalizável. O tour de bicicleta é mais interessante e cobre mais distância. Confirme disponibilidade fora da alta temporada.",t:["bicicleta","noite","grupo","verificar"]},

/* ---------- PARIS · PALCO, ÓPERA & CONCERTOS ---------- */
{c:"paris",k:"palco",n:"Opéra Bastille",o:"Opéra Bastille",a:"11e/12e (Bastille)",d:"3h",p:"€€–€€€€",w:"A casa principal da Ópera Nacional de Paris, com a maior sala da França (2.700 lugares) e encenações modernas. O repertório na sua janela incluía Wagner — confirme no site. Há ingressos de última hora baratos e lugares com visão parcial muito em conta.",t:["ópera","erudito","noite","imperdível"]},
{c:"paris",k:"palco",n:"Palais Garnier — espetáculo",o:"Palais Garnier",a:"9e",d:"3h",p:"€€€–€€€€",w:"Além da visita diurna, o Garnier tem óperas, balés e concertos à noite, dentro do salão de 1875 com o teto de Chagall. Assistir a qualquer coisa ali vale mais pelo lugar do que pelo programa. Se o balé estiver em cartaz, é a melhor pedida — a companhia de dança da ópera é de alto nível.",t:["ópera","balé","erudito","noite","arquitetura"]},
{c:"paris",k:"palco",n:"Philharmonie de Paris",o:"Philharmonie de Paris",a:"19e (La Villette)",d:"2h",p:"€€–€€€",w:"Sala nova de Jean Nouvel, em La Villette, com acústica famosa e preços surpreendentemente acessíveis (há ingressos jovens e de última hora). Orquestras e solistas internacionais. Ao lado, a Cité de la Musique com o museu de instrumentos. Uma das melhores noites de música erudita possíveis em Paris por custo baixo.",t:["concerto","erudito","noite","barato"]},
{c:"paris",k:"palco",n:"Théâtre des Champs-Élysées",o:"Théâtre des Champs-Élysées",a:"8e",d:"2h30",p:"€€€",w:"A casa onde a Sagração da Primavera de Stravinsky causou o motim de 1913. Sala art déco, programação de concertos, ópera e dança de altíssimo nível, com acústica excelente e público exigente. Menos turístico que a Garnier e com programação mais interessante.",t:["concerto","erudito","noite","história"]},
{c:"paris",k:"palco",n:"Comédie-Française",o:"Comédie-Française",a:"1er (Palais Royal)",d:"2h30",p:"€€",w:"A companhia teatral mais antiga do mundo (1680), com Molière no repertório e a sala Richelieu em estilo dourado no meio do Palais Royal. Encenações em francês — se o idioma for barreira, escolha peças cujo texto você conheça. É o teatro francês na sua forma canônica.",t:["teatro","erudito","noite","história"]},
{c:"paris",k:"palco",n:"Odéon-Théâtre de l'Europe",o:"Odéon",a:"6e",d:"2h30",p:"€€",w:"Teatro nacional ao lado do Jardim de Luxembourg, com encenações europeias, muitas com legendas em inglês. Sala histórica de 1782 reformada, e público mais jovem que o da Comédie-Française.",t:["teatro","erudito","noite","legendas"]},
{c:"paris",k:"palco",n:"Théâtre du Châtelet",o:"Théâtre du Châtelet",a:"1er (Châtelet)",d:"2h30",p:"€€–€€€",w:"Casa de espetáculos de 1862 na Place du Châtelet com programação ampla: ópera, dança, jazz, musicais e concertos sinfônicos. Arquitetura interior espetacular e localização central — fácil de encaixar numa noite de caminhada pelo Sena.",t:["concerto","erudito","noite","central"]},
{c:"paris",k:"palco",n:"Salle Gaveau",o:"Salle Gaveau",a:"8e",d:"2h",p:"€€–€€€",w:"Sala de concerto art déco de 1907, com programação de piano, música de câmara e recitais de altíssimo nível em ambiente intimista (cerca de mil lugares, formato de casa de concerto europeia clássica). Se você gosta de piano, vale olhar a agenda.",t:["concerto","erudito","noite","intimista"]},
/* ---------- PARIS · BALADA, DJs & MÚSICA AO VIVO ---------- */
{c:"paris",k:"balada",n:"Rex Club",o:"Rex Club",a:"2e (Grands Boulevards)",d:"Noite toda",p:"€€",w:"O clube de techno e house mais respeitado de Paris, com o sound system que é referência na Europa desde os anos 1980. Pista no subsolo, público que vai pela música e line-ups de nomes sérios. Se você só for a um clube em Paris, é esse.",t:["techno","house","noite","madrugada","imperdível"]},
{c:"paris",k:"balada",n:"La Machine du Moulin Rouge",o:"La Machine du Moulin Rouge",a:"18e (Pigalle)",d:"Noite toda",p:"€€",w:"Clube dentro do complexo do Moulin Rouge, com três andares, programação de techno, house e festas temáticas. Fica a poucos passos de Pigalle, então dá para começar nos bares de SoPi e terminar aqui. Entrada relativamente fácil.",t:["techno","noite","madrugada","fácil de entrar"]},
{c:"paris",k:"balada",n:"Djoon",o:"Djoon",a:"13e",d:"Noite toda",p:"€€",w:"Clube de house, soul, garage e sons negros com uma pista séria e público caloroso — é onde a cena de dança de Paris acontece de verdade. Bem menos turista que os clubes centrais, com ambiente de comunidade.",t:["house","soul","noite","dança","local"]},
{c:"paris",k:"balada",n:"Glazart",o:"Glazart",a:"19e (Porte de la Villette)",d:"Noite toda",p:"€€",w:"Clube em um antigo depósito de sal, com techno e eletrônica pesada, som enorme e festas que vão até tarde. No verão tem praia artificial com shows ao ar livre. Fim de linha do metrô 7 — é longe, mas o público é dos melhores.",t:["techno","noite","madrugada","alternativo"]},
{c:"paris",k:"balada",n:"La Bellevilloise",o:"La Bellevilloise",a:"20e (Ménilmontant)",d:"Noite",p:"€€",w:"Centro cultural e de festas num antigo prédio cooperativo operário: concertos, DJs, exposições e brunch no domingo com vista dos telhados de Paris e da Torre ao longe. Programação variada, ambiente descontraído e não é só balada — vale ver a agenda.",t:["shows","noite","brunch","alternativo","vista"]},
{c:"paris",k:"balada",n:"Le Trabendo",o:"Le Trabendo",a:"19e (La Villette)",d:"Noite",p:"€€",w:"Casa de shows em La Villette com programação forte de indie, rock, eletrônica e hip-hop internacional, dentro do complexo do Parc de la Villette. Capacidade média e boa acústica.",t:["shows","rock","indie","noite"]},
{c:"paris",k:"balada",n:"Cabaret Sauvage",o:"Cabaret Sauvage",a:"19e (La Villette)",d:"Noite",p:"€€",w:"Espaço em forma de carrossel vermelho no Parc de la Villette, dedicado a música do mundo, afrobeat, latinidades e festas comunitárias. Uma das noites mais quentes e menos europeias de Paris — vá sem preconceito de gênero musical.",t:["world","noite","dança","festa"]},
{c:"paris",k:"balada",n:"La Cigale",o:"La Cigale",a:"18e (Pigalle)",d:"Noite",p:"€€",w:"Casa de shows histórica de 1885 na Place Pigalle, com painéis de cerâmica na fachada, programação de rock, chanson, pop e eletrônica. Boa vista de todos os pontos e localização no meio da vida noturna.",t:["shows","noite","história"]},
{c:"paris",k:"balada",n:"Le Trianon",o:"Le Trianon",a:"18e",d:"Noite",p:"€€",w:"Sala de 1894 aberta por Bourdelle, recentemente restaurada, com teto pintado e palco de teatro. Excelente para ver shows de médio porte — som e visão muito superiores aos clubes.",t:["shows","noite","arquitetura","imperdível"]},
{c:"paris",k:"balada",n:"Bataclan",o:"Bataclan",a:"11e",d:"Noite",p:"€€",w:"A lendária casa de shows de 1864, hoje reaberta e ativa com programação de rock, pop e eletrônica. Palco que recebeu de Bowie a Prince. Estado de espírito um pouco diferente dos outros lugares, pelo que aconteceu em 2015, mas é parte da vida cultural de Paris.",t:["shows","noite","história"]},
{c:"paris",k:"balada",n:"L'Olympia",o:"L'Olympia",a:"9e",d:"Noite",p:"€€€",w:"O templo da música ao vivo em Paris desde 1893 — Piaf, Beatles, Brel, Rolling Stones. Hoje recebe nomes grandes e projetos especiais. Se algo que você gosta estiver em cartaz, não pense duas vezes.",t:["shows","noite","história","ícone"]},
{c:"paris",k:"balada",n:"Élysée Montmartre",o:"Élysée Montmartre",a:"18e",d:"Noite",p:"€€",w:"Casa de espetáculos de 1807 com balé, festas e shows, que virou clube nos fins de semana. Interior dourado e antigo, com público grande e variado. Fica ao pé de Montmartre.",t:["shows","noite","história"]},
{c:"paris",k:"balada",n:"Showcase (sob o Pont Alexandre III)",o:"Showcase",a:"8e (Pont Alexandre III)",d:"Noite toda",p:"€€€",w:"Clube literalmente embaixo dos arcos da Pont Alexandre III, à beira do Sena, com teto abobadado de pedra e vista para os barcos passando. Já foi referência absoluta da noite parisiense; hoje é mais turístico e caro, mas o espaço físico é impressionante.",t:["techno","noite","arquitetura","turístico"]},
{c:"paris",k:"balada",n:"Le Faust",o:"Le Faust",a:"7e (Pont d'Alma)",d:"Noite toda",p:"€€",w:"Clube underground dentro de um túnel na margem do Sena, embaixo da Pont d'Alma, com atmosfera industrial e som alternativo. Entrada discreta, público que sabe onde está e uma das experiências mais “underground” de Paris.",t:["techno","noite","alternativo","escondido"]},
{c:"paris",k:"balada",n:"Le Badaboum",o:"Le Badaboum",a:"11e (Bastille)",d:"Noite",p:"€€",w:"Clube e sala de shows perto da Bastille, com programação de indie, eletrônica e hip-hop e festas de selos e coletivos. Tamanho bom: nem intimista demais nem arena.",t:["shows","noite","indie"]},
{c:"paris",k:"balada",n:"Petit Bain",o:"Petit Bain",a:"13e (Bibliothèque)",d:"Noite",p:"€€",w:"Barco-casa de shows ancorado no Sena, com terraço, concertos e festas eletrônicas — um dos espaços mais charmosos da noite parisiense, com vista para a água. Programação eclética, do rock ao eletrônico.",t:["shows","noite","rio","alternativo"]},
{c:"paris",k:"balada",n:"La Station – Gare des Mines",o:"La Station – Gare des Mines",a:"18e (Porte d'Aubervilliers)",d:"Noite toda",p:"€€",w:"Antiga estação ferroviária transformada em espaço cultural e clube, com techno, festas independentes e programação comunitária em um galpão industrial. Uma das melhores noites alternativas de Paris hoje, e bem longe do circuito turístico.",t:["techno","noite","alternativo","underground"]},
{c:"paris",k:"balada",n:"Supersonic",o:"Supersonic",a:"11e (Bastille)",d:"Noite",p:"Grátis/€",w:"Clube e casa de shows com entrada gratuita em muitas noites, com bandas novas, DJs e público jovem. Se você quer uma noite com música ao vivo sem gastar muito, é a melhor aposta de Paris — confira a programação do dia.",t:["shows","noite","barato","grátis","alternativo"]},
{c:"paris",k:"balada",n:"Le Comptoir Général",o:"Le Comptoir Général",a:"10e (Canal Saint-Martin)",d:"Noite",p:"€ (consumação)",w:"Bar e espaço cultural às margens do Canal Saint-Martin, decorado como um gabinete de curiosidades africano, com plantas, objetos, DJs e ambiente único. Vai bem como primeira parada da noite — abre cedo e é mais bar de conversa que pista.",t:["bar","noite","alternativo","decoração"]},
{c:"paris",k:"balada",n:"Rosa Bonheur sur Seine e Wanderlust",o:"Rosa Bonheur / Wanderlust",a:"7e / 13e (Sena)",d:"Noite",p:"€ (consumação)",w:"Bares à beira do Sena: o Rosa Bonheur é um espaço descontraído embaixo do pont des Invalides com mesas ao ar livre e público jovem; o Wanderlust tem pista, DJs e um deck enorme sobre a água. Em novembro os espaços externos sofrem com o frio, mas seguem abertos com cobertura — confirme o funcionamento.",t:["bar","noite","rio","ao ar livre","verificar"]},
{c:"paris",k:"balada",n:"Le Marais gay e a noite LGBTQIA+",o:"Le Marais / Chez Moune",a:"3e / 4e / 9e",d:"Noite toda",p:"€–€€",w:"Paris concentra a noite LGBTQIA+ principalmente no Marais (rues des Archives e Sainte-Croix-de-la-Bretonnerie), com bares para todos os gostos, e em clubes maiores como o Chez Moune (clube lésbico histórico em Pigalle, desde 1936) e as festas coletivas do 11e. A cena é mais discreta que em Berlim, mas existe e tem história.",t:["queer","noite","bar","gay-friendly"]},
{c:"paris",k:"balada",n:"Le Balajo e as soirées de dança",o:"Le Balajo / La Java",a:"11e / 10e",d:"Noite",p:"€€",w:"Dois salões históricos onde Paris ainda dança a dois: o Balajo, desde 1936 na rue de Lappe, com musette, salsa e milongas; e o La Java, onde Django Reinhardt tocou, hoje com noites de swing, electro e afro. Vá sem saber dançar — o público ensina.",t:["dança","noite","história","tango","imperdível"]},
{c:"paris",k:"balada",n:"New Morning",o:"New Morning",a:"10e (Château-Landon)",d:"Noite",p:"€€",w:"Casa de shows histórica dedicada a jazz, soul, funk, afrobeat e world music, com artistas que às vezes só tocam aqui na França. Barraquinha, sem frescura, e um dos melhores públicos de Paris. Confira a agenda — quase sempre vale.",t:["shows","jazz","world","noite","história"]},

/* ---------- PARIS · EXPERIÊNCIA ÚNICA ---------- */
{c:"paris",k:"unica",n:"Leilão ao vivo no Hôtel Drouot",o:"Hôtel Drouot",a:"9e",d:"2h",p:"Grátis",w:"Drouot é a casa de leilões de Paris, funcionando desde 1852, com dezenas de pregões por dia, gratuitos e abertos ao público. Você entra sem aviso, senta, vê objetos do século XVIII ao design moderno sendo arrematados e sai quando quiser. É grátis, é espetáculo e é onde se vê o sistema de arte parisiense funcionando de verdade.",t:["arte","grátis","escondido","único","imperdível"]},
{c:"paris",k:"unica",n:"Curso de croissant e pâtisserie",o:"Atelier de pâtisserie",a:"Marais / Montmartre / Bastille",d:"3h",p:"€€€",w:"Aulas de manhã onde você faz croissant, brioche, éclair ou macaron com um chef, em cozinha profissional, e leva o que produziu. A La Cuisine Paris e a Cook'n With Class têm aulas em inglês; há opções em francês mais baratas. Vale reservar antes de viajar.",t:["comida","aula","chuva","reservar","grupo"]},
{c:"paris",k:"unica",n:"Degustação e curso de vinho",o:"Dégustation de vins",a:"Marais / 8e / 5e",d:"2h",p:"€€€",w:"Sessões guiadas de degustação com sommelier para entender Borgonha, Bordeaux, Rhône e Champanhe — muitas em inglês e com foco em viticultura. Há também o Le Grand Tasting e os salões de vignerons independentes (verifique datas). Melhor souvenir intelectual que você pode levar.",t:["vinho","aula","chuva","reservar"]},
{c:"paris",k:"unica",n:"Atelier de perfume",o:"Atelier de parfum",a:"Palais Royal / Montmartre",d:"2h",p:"€€–€€€",w:"Oficinas onde você cria e leva o seu próprio perfume, conhecendo as matérias-primas, dentro de uma cidade que é literalmente o centro mundial da perfumaria. Boa para fazer algo com as mãos num dia frio. Reserve antes.",t:["aula","chuva","reservar","único","souvenir"]},
{c:"paris",k:"unica",n:"Hammam da Grande Mosquée de Paris",o:"Hammam de la Grande Mosquée",a:"5e",d:"2h30",p:"€€",w:"Banho turco com vapor, massagem com sabão preto, esfoliação e té de menta no pátio da mesquita em seguida. É um banho histórico no estilo árabe-andaluz, dentro do Instituto Muçulmano construído em 1926, e um dos programas mais relaxantes e mais baratos de Paris. Vá de manhã.",t:["spa","relaxar","cultura","barato","imperdível"]},
{c:"paris",k:"unica",n:"Piscine Molitor",o:"Piscine Molitor",a:"16e",d:"3h",p:"€€€",w:"A piscina art déco de 1929, tombada como patrimônio, onde foram lançados os primeiros biquínis em 1946 — hoje reformada como hotel e clube com day pass pago. Piscina exterior aquecida no inverno, com a neblina saindo da água e o prédio laranja ao redor: visual absurdo.",t:["spa","relaxar","arquitetura","luxo","frio"]},
{c:"paris",k:"unica",n:"Piscinas art déco de Pontoise e Butte-aux-Cailles",o:"Piscine Pontoise / Piscine de la Butte-aux-Cailles",a:"5e / 13e",d:"1h30",p:"€",w:"As piscinas municipais históricas de Paris são joias escondidas: a Piscine Pontoise é de 1934, com estrutura de aço e vitral, e a de la Butte-aux-Cailles está num bairro de vila boêmia. Entrada de alguns euros, nada de turista, e um programa que faz parte da vida da cidade.",t:["barato","chuva","arquitetura","relaxar","local"]},
{c:"paris",k:"unica",n:"Marché du livre ancien no Parc Georges-Brassens",o:"Marché du livre ancien",a:"15e",d:"1h30",p:"Grátis",w:"Feira de livros antigos e de colecionador, aos sábados e domingos, embaixo de uma estrutura coberta dentro do Parc Georges-Brassens (onde existia o antigo matadouro e que hoje tem até vinhedo e mercado de pulgas). Muito pouca gente, livros raros, cartazes e gravuras.",t:["compras","livros","grátis","sábado","domingo","escondido"]},
{c:"paris",k:"unica",n:"Bastidores da Ópera Garnier e da Comédie-Française",o:"Visites des coulisses",a:"9e / 1er",d:"1h30",p:"€€€",w:"Visitas guiadas que entram nos bastidores do Palais Garnier (bem além da visita comum, incluindo o lago e as salas de ensaio) e nos subsolos e reservas da Comédie-Française. Grupos pequenos e horários limitados — precisa reservar antes. É a melhor forma de entender como a alta cultura francesa é montada.",t:["arte","erudito","reservar","bastidores","imperdível"]},
{c:"paris",k:"unica",n:"Pedalar o Sena com o Vélib'",o:"Vélib' Métropole",a:"Cidade toda",d:"3h",p:"€",w:"Paris é plana e tem ciclovia em quase todo o Sena, com faixas exclusivas em várias margens. Alugue uma Vélib' (barata, com estação em toda esquina) e faça o eixo: Bastille → Île Saint-Louis → Louvre → Orsay → Torre Eiffel → Trocadéro. Frio em novembro, mas é o melhor jeito de cobrir muito terreno.",t:["bicicleta","ao ar livre","barato","rio"]},
{c:"paris",k:"unica",n:"Balão cativo do Parc André Citroën",o:"Ballon de Paris Generali",a:"15e",d:"45min",p:"€€",w:"Um balão preso por cabo que sobe 150 m sobre o Parc André Citroën e fica parado no ar o tempo que você quiser, com vista de 360° sobre o Sena, a Torre e o sudoeste de Paris. Muito melhor que os mirantes fechados em termos de sensação. Funciona conforme o vento — confirme no dia.",t:["vista","único","família"]},
{c:"paris",k:"unica",n:"Les Égouts de Paris — o museu do esgoto",o:"Musée des Égouts de Paris",a:"7e (Pont de l'Alma)",d:"1h",p:"€€",w:"Você desce para dentro da rede de esgoto de Paris e caminha por galerias reais, com a água passando ao lado, em uma exposição sobre a história do saneamento da cidade. Fecha no inverno em caso de cheia — confirme. É inusitado, educativo e cheira menos do que parece.",t:["chuva","inusitado","escondido"]},
{c:"paris",k:"unica",n:"Guinguette e dîner dansant",o:"Guinguettes",a:"Sena / Bois de Vincennes",d:"Noite",p:"€€",w:"A tradição parisiense dos bares à beira do rio onde se come, bebe e dança — versão de inverno em espaços fechados com pista, como o Chalet des Îles no Bois de Boulogne. Existe também o “dîner dansant” clássico com orquestra. Confirme a programação, porque varia muito com a estação.",t:["dança","noite","comida","tradição","verificar"]},
/* ---------- PARIS · COMIDA & BEBIDA ---------- */
{c:"paris",k:"comida",n:"Boulangeries e pâtisseries para não errar",o:"Du Pain et des Idées / Poilâne / Stohrer / Cédric Grolet",a:"Marais / 6e / 2e",d:"1h",p:"€",w:"A Du Pain et des Idées, no Canal, faz o melhor pão e a pain au chocolat-pistache mais comentada da cidade; a Poilâne é a padaria de sourdough mais famosa do mundo; a Stohrer é a mais antiga de Paris (1730) e a Cédric Grolet faz a pastelaria-espetáculo. Entrar numa boulangerie de bairro qualquer também funciona — o padrão é alto.",t:["comida","barato","manhã","ícone","imperdível"]},
{c:"paris",k:"comida",n:"Chocolaterias e confeitarias",o:"Patrick Roger / Jacques Genin / À la Mère de Famille",a:"6e / 3e / 9e",d:"45min",p:"€€€",w:"Patrick Roger é considerado um dos melhores chocolatiers do mundo e faz esculturas de chocolate de escala pública; Jacques Genin faz caramelo e pâte de fruit de outro nível; e a À la Mère de Famille, de 1761, é a mais antiga loja de guloseimas de Paris. Sobremesa e souvenir no mesmo lugar.",t:["comida","doce","souvenir","luxo"]},
{c:"paris",k:"comida",n:"Os mercados de bairro",o:"Marché d'Aligre / Bastille / Enfants Rouges / Saxe-Breteuil",a:"12e / 11e / 3e / 7e",d:"1h30",p:"€",w:"O de Aligre é o mais popular e barulhento; o des Enfants Rouges (1615) é o mais antigo de Paris, com barracas de comida e bancos para comer ali; o de Saxe-Breteuil tem a melhor vista de fundo (a Torre Eiffel); e o da Bastille é enorme e cobre dois quarteirões. Cada um tem dia próprio — confira antes.",t:["comida","mercado","barato","manhã","local"]},
{c:"paris",k:"comida",n:"Bistrôs clássicos parisienses",o:"Le Comptoir du Relais / Bistrot Paul Bert / Chez l'Ami Jean",a:"6e / 11e / 7e",d:"2h",p:"€€€",w:"O bistrô é a instituição gastronômica mais parisiense que existe: menu curto, prato do dia escrito na lousa, carne, molho, batata e uma taça de vinho. O Bistrot Paul Bert, no 11e, é o templo contemporâneo; o Chez l'Ami Jean faz cozinha basca generosa. Reserve — e vá almoçar, que é mais barato que jantar.",t:["comida","tradição","reservar","imperdível"]},
{c:"paris",k:"comida",n:"Bouillons — comer bem por pouco",o:"Bouillon Chartier / Bouillon Pigalle",a:"9e / 18e",d:"1h30",p:"€",w:"Os bouillons são refeitórios históricos que servem cozinha francesa clássica a preço popular, em salões de 1900 com espelhos, madeira e muito burburinho. O Bouillon Chartier funciona desde 1896 e o de Pigalle é a versão nova e igualmente boa. Se seu objetivo é comer francês sem gastar muito, é aqui.",t:["comida","barato","história","fila","imperdível"]},
{c:"paris",k:"comida",n:"Brasseries históricas de Montparnasse",o:"La Coupole / Le Dôme / La Rotonde",a:"14e (Montparnasse)",d:"2h",p:"€€€",w:"As grandes brasseries onde Hemingway, Picasso e Modigliani comiam: La Coupole (1927), com salão art déco enorme e banquetas alinhadas; Le Dôme, especializado em peixe; e La Rotonde, que ainda tem a decoração original. Frutos do mar, choucroute e cena social. Caro, mas é uma experiência de época.",t:["comida","história","tradição","turístico"]},
{c:"paris",k:"comida",n:"Cafés literários de Saint-Germain",o:"Les Deux Magots / Café de Flore / Brasserie Lipp",a:"6e",d:"1h",p:"€€€",w:"Os três cafés do bulevar Saint-Germain onde Sartre, Beauvoir, Camus e Hemingway se sentavam. Hoje o café custa caro e o serviço é para turista, mas tomar um chocolate quente no Flore e olhar o bairro continua valendo. Vá de manhã, fora do horário de almoço.",t:["café","história","turístico","manhã"]},
{c:"paris",k:"comida",n:"Falafel e shawarma do Marais",o:"L'As du Fallafel / Miznon",a:"4e (rue des Rosiers)",d:"45min",p:"€",w:"O falafel mais famoso de Paris (L'As du Fallafel, na rue des Rosiers, com fila na rua) e a Miznon, que faz pita de sabich e carne num estilo israelense moderno. Barato, rápido, gostoso e no meio da caminhada pelo Marais. Peça para viagem e coma numa praça.",t:["comida","barato","rápido","ícone"]},
{c:"paris",k:"comida",n:"Bistronomia moderna e cozinha de autor",o:"Septime / Le Châteaubriand / Frenchie / Le Verre Volé",a:"11e / 10e",d:"2h30",p:"€€€€",w:"A “bistronomia” nasceu em Paris: cozinha de alto nível em salas pequenas e informais, com menu degustação a preços menores que os restaurantes estrelados. A Septime e o Châteaubriand são referências mundiais e reservam com semanas de antecedência — o Le Verre Volé, que é loja de vinho e restaurante, é mais fácil e igualmente bom.",t:["comida","moderno","reservar","noite","imperdível"]},
{c:"paris",k:"comida",n:"Alta gastronomia",o:"Guy Savoy / Le Cinq / L'Ambroisie / Alain Ducasse",a:"6e / 8e / 4e",d:"3h30",p:"€€€€",w:"Paris tem mais restaurantes com estrela do que qualquer outra cidade. A três estrelas, a lista inclui Guy Savoy (no Monnaie de Paris, com vista do Sena), Le Cinq (no Four Seasons George V) e a histórica L'Ambroisie na Place des Vosges. Se você quiser fazer uma refeição-acontecimento, é aqui — reserve com meses.",t:["comida","luxo","reservar","imperdível"]},
{c:"paris",k:"comida",n:"Wine bars e a cultura do vinho natural",o:"Le Verre Volé / Septime La Cave / Aux Deux Amis",a:"10e / 11e",d:"2h",p:"€€",w:"Paris é a capital mundial do vinho natural: bares pequenos com prateleiras de garrafas, tábua de queijos e petiscos, onde você trava conversa com o dono. O Le Verre Volé, às margens do Canal, foi pioneiro; a Septime La Cave é a versão enxuta do restaurante. Vá sem pressa e deixe o sommelier escolher.",t:["vinho","bar","noite","local","imperdível"]},
{c:"paris",k:"comida",n:"Coquetelaria de Paris",o:"Le Syndicat / Little Red Door / Candelaria / ECC",a:"2e / 3e / 11e",d:"2h",p:"€€€",w:"Paris tem uma cena de coquetelaria reconhecida mundialmente. O Le Syndicat trabalha só com destilados franceses; a porta vermelha do Little Red Door esconde um dos bares mais premiados do mundo; e a Candelaria fica atrás de uma taqueria, com coquetéis excelentes e sala mínima. Chegue cedo — são lugares pequenos.",t:["coquetel","noite","escondido","imperdível"]},
{c:"paris",k:"comida",n:"Cerveja artesanal francesa",o:"Paname Brewing Company / La Fine Mousse / Le Supercoin",a:"19e / 11e / 18e",d:"2h",p:"€€",w:"A França virou país de craft beer: a Paname Brewing Company fica num galpão à beira do bassin de la Villette, com deck sobre a água; a La Fine Mousse tem 20 torneiras com foco em cervejarias francesas; e o Le Supercoin é o bar de bairro artesanal no 18e. Bom para variar do vinho sem cair na cerveja industrial.",t:["cerveja","bar","noite","local"]},
{c:"paris",k:"comida",n:"Cafés de especialidade",o:"Ten Belles / Coutume / Fragments / KB Caféshop",a:"10e / 7e / 3e / 9e",d:"1h",p:"€€",w:"A onda de café de especialidade chegou forte em Paris: a Ten Belles e a Fragments torram e fazem filtrados excelentes; a Coutume, na rue de Babylone, foi pioneira; e a KB Caféshop, em Montmartre, é onde a cena começou. Para trabalhar de manhã ou recuperar de uma noite longa.",t:["café","manhã","chuva","trabalhar"]},
{c:"paris",k:"comida",n:"Quartier asiático do 13e e comida vietnamita",o:"Quartier asiatique / Tang Frères / Olympiades",a:"13e",d:"2h",p:"€",w:"O bairro asiático de Paris, concentrado nas avenidas de Choisy e d'Ivry, com o supermercado Tang Frères, restaurantes vietnamitas, chineses e tailandeses, padarias asiáticas e preços baixos. O pho e o bánh mì aqui são melhores e mais baratos que nos bares do centro. Coma num lugar sem decoração, com plástico na mesa.",t:["comida","asiático","barato","local"]},
{c:"paris",k:"comida",n:"Cozinha do Magreb e do Oriente Médio",o:"Chez le Libanais / L'As du Fallafel / Goutte d'Or",a:"5e / 4e / 18e",d:"1h30",p:"€–€€",w:"Cuscuz, tajine, meze, kebab de verdade e pastelaria com mel e pistache: a comunidade magrebina faz a melhor comida barata de Paris. O bairro da Goutte d'Or, no 18e, é o epicentro, e o cuscuz de sexta-feira é tradição. Peça o prato do dia e o chá de menta.",t:["comida","barato","local","noite"]},
{c:"paris",k:"comida",n:"Chocolate quente, sorvete e doces clássicos",o:"Angelina / Berthillon / Glaces Bachir",a:"1er / 4e / 4e",d:"45min",p:"€€",w:"O chocolate quente do Angelina, na rue de Rivoli, é espesso a ponto de precisar de colher; o sorvete da Berthillon, na Île Saint-Louis, é o mais famoso de Paris desde 1954; e o Glaces Bachir, no Marais, faz sorvete libanês com pistache e flor de laranjeira. Três paradas curtas e certeiras entre um passeio e outro.",t:["comida","doce","pausa","ícone"]},
{c:"paris",k:"comida",n:"Queijos e vinhos — a compra para levar",o:"Fromagerie Laurent Dubois / Barthélémy",a:"5e / 7e",d:"45min",p:"€€",w:"A Laurent Dubois é uma das melhores queijarias do mundo, com cave de maturação própria e cerca de 200 queijos; a Barthélémy é a preferida dos chefes. Se você quiser levar (ou comer no quarto com uma baguete e uma garrafa), este é o melhor souvenir gastronômico possível. Peça sugestão de maturação.",t:["comida","compras","souvenir","luxo"]},

/* ---------- PARIS · COMPRAS & MERCADOS ---------- */
{c:"paris",k:"compras",n:"Marché aux Puces de Saint-Ouen",o:"Puces de Saint-Ouen",a:"Saint-Ouen (linha 4 / 13)",d:"3–4h",p:"Grátis",w:"O maior mercado de antiguidades do mundo: mais de 2.000 comerciantes em 15 mercados distintos, de móveis e lustres a discos, cartazes, bijuterias, roupas e objetos de design. Abre sábado, domingo e segunda (segunda com menos bancas). Vá com tempo, dinheiro em espécie e disposição para negociar.",t:["compras","antiguidades","sábado","domingo","imperdível"]},
{c:"paris",k:"compras",n:"Marché aux Puces de Vanves",o:"Puces de Vanves",a:"14e (Porte de Vanves)",d:"2h",p:"Grátis",w:"Menor, mais curado e mais amigável que Saint-Ouen, com cerca de 380 bancas de antiguidades, quadros, louça, relógios, livros e pequenos objetos. Sábado e domingo de manhã. Ótimo para garimpar sem a muvuca do mercado maior — e dá para combinar com um almoço em Montparnasse.",t:["compras","antiguidades","sábado","domingo","manhã"]},
{c:"paris",k:"compras",n:"Marché d'Aligre e Marché Beauvau",o:"Marché d'Aligre",a:"12e (Ledru-Rollin)",d:"1h30",p:"€",w:"Mercado de bairro no seu estado mais vivo: comida de rua, produtores, queijos, flores, e do lado o Marché Beauvau, coberto, com peixaria, carnes e queijos. Em volta há lojas de vinhos e cafés. É onde os parisienses do bairro compram — barato, barulhento e real.",t:["compras","comida","mercado","barato","local"]},
{c:"paris",k:"compras",n:"Grandes lojas: Galeries Lafayette, Printemps, Le Bon Marché, Samaritaine",o:"Grands magasins",a:"9e / 7e / 1er",d:"3h",p:"€€–€€€€",w:"As quatro grandes lojas de departamento de Paris, cada uma com personalidade: as Galeries Lafayette e o Printemps (com as cúpulas e os terraços com vista), o Le Bon Marché (o mais chique, com a Grande Épicerie ao lado) e a Samaritaine, reaberta com arquitetura Art Nouveau e vista do Sena. Bom para as vitrines de Natal a partir de meados de novembro.",t:["compras","luxo","arquitetura","chuva"]},
{c:"paris",k:"compras",n:"Marais vintage e lojas conceito",o:"Merci / Free'P'Star / Kilo Shop / Thanx God I'm a V.I.P.",a:"3e / 4e",d:"2h",p:"€–€€€",w:"O Marais concentra o melhor garimpo de Paris: a Merci (loja conceito com carro vermelho na entrada e parte da renda para caridade), a Free'P'Star e a Kilo Shop (vintage barato vendido por quilo) e a Thanx God I'm a V.I.P., onde gente da moda procura peça única. Vá num dia de semana à tarde.",t:["compras","vintage","moda","barato"]},
{c:"paris",k:"compras",n:"Rue des Martyrs e o comércio de bairro",o:"Rue des Martyrs",a:"9e / 18e",d:"1h30",p:"€€",w:"A rua mais gostosa de Paris para comprar comida: padarias premiadas, queijaria, peixaria, chocolate, sorvete, vinho, florista e cafés, numa ladeira que sobe de Notre-Dame-de-Lorette até Montmartre. É o padrão parisiense de qualidade de bairro. Termine com um croissant quente e suba até Pigalle.",t:["compras","comida","caminhada","local","imperdível"]},
{c:"paris",k:"compras",n:"Livrarias e a Shakespeare and Company",o:"Shakespeare and Company / Galignani / Gibert Joseph",a:"5e / 1er",d:"1h30",p:"€€",w:"A Shakespeare and Company, em frente a Notre-Dame, é a livraria em inglês mais famosa do mundo, com escritores morando de graça em troca de trabalho e leituras à noite. A Galignani, na rue de Rivoli, é a mais antiga livraria em inglês do continente. E a Gibert, no Quartier Latin, tem sebo gigante e barato.",t:["compras","livros","chuva","história"]},
{c:"paris",k:"compras",n:"Perfumarias de nicho",o:"Nose / Serge Lutens / Fragonard / Ex Nihilo",a:"3e / 1er / 8e",d:"1h30",p:"€€–€€€€",w:"Paris é o centro mundial da perfumaria e tem muito além das grifes: a Nose, na rue Bachaumont, faz diagnóstico olfativo e vende marcas de nicho; a Serge Lutens, no Palais Royal, cria perfumes que não existem em outro lugar; e a Fragonard tem museu e ateliê. Ótimo para um souvenir que dura anos.",t:["compras","perfume","luxo","souvenir"]},
{c:"paris",k:"compras",n:"Lojas de vinil e selos independentes",o:"Crocodisc / Gibert Musique / Balades Sonores / Born Bad",a:"5e / 11e / 18e",d:"1h30",p:"€€",w:"Paris tem uma cena forte de selos independentes e lojas de disco de segunda mão — a Crocodisc, no Quartier Latin, é a mais tradicional; a Balades Sonores e a Born Bad Records apostam em rock, garage e francês; o andar de música da Gibert é gigantesco e barato. Se você curte vinil, é meia tarde garantida.",t:["compras","vinil","música","barato"]},
{c:"paris",k:"compras",n:"Papelaria de arte e materiais de desenho",o:"Sennelier / Charvin / Rougier & Plé / Lavrut",a:"6e / 1er / 11e",d:"1h",p:"€€",w:"A Sennelier, na margem do Sena, fez tintas para Cézanne, Picasso e Monet e continua funcionando no mesmo lugar desde 1887; a Charvin é de 1830; e a Rougier & Plé é a maior loja de belas artes de Paris. Se você desenha ou se interessa por pigmento, é quase um museu.",t:["compras","arte","escondido","história","souvenir"]},

/* ---------- PARIS · BATE-VOLTA ---------- */
{c:"paris",k:"batevolta",n:"Versailles",o:"Château de Versailles",a:"Yvelines (40min de RER C)",d:"Dia inteiro",p:"€€€",w:"O palácio de Luís XIV, o Salão dos Espelhos, os aposentos da rainha e os jardins de Le Nôtre com os bosques, fontes e canais, mais o Grand Trianon, o Petit Trianon e o Hameau de la Reine (a aldeia campestre de Maria Antonieta). Em novembro há muito menos fila que no verão. Vá cedo e calcule meio dia só para os jardins.",t:["batevolta","história","jardim","arte","dia inteiro","imperdível"]},
{c:"paris",k:"batevolta",n:"Fontainebleau e Barbizon",o:"Château de Fontainebleau / Barbizon",a:"Seine-et-Marne (45min)",d:"Dia inteiro",p:"€€",w:"O castelo onde nasceram e morreram vários reis franceses, com 1.500 cômodos, a galeria de Francisco I e o salão do trono, mais os jardins e o pátio. Ao lado, a vila de Barbizon, onde os pintores pré-impressionistas ficavam, no limite da floresta. Combine com a trilha dos 25 Bosses se tiver pernas.",t:["batevolta","história","arte","jardim","trilha"]},
{c:"paris",k:"batevolta",n:"Chantilly — castelo, floresta e creme",o:"Château de Chantilly",a:"Oise (30min de trem)",d:"Dia inteiro",p:"€€€",w:"O Château de Chantilly tem o segundo maior acervo de pintura antiga da França depois do Louvre (condes de Aumale), as Grandes Écuries — as cavalariças mais aristocráticas da Europa, com museu do cavalo e demonstrações — e um parque de Le Nôtre. A cidade dá nome ao creme Chantilly. Combine com trilha na floresta.",t:["batevolta","arte","jardim","trilha","família"]},
{c:"paris",k:"batevolta",n:"Reims e a Champagne",o:"Reims / Champagne",a:"Marne (45min de TGV)",d:"Dia inteiro",p:"€€€",w:"A catedral onde os reis da França eram coroados e onde foram descobertas as caves de champagne: dá para visitar casas como Taittinger, Mumm, Veuve Clicquot e Ruinart, muitas em galerias romanas subterrâneas. 45 minutos de TGV da Gare de l'Est. Combine a catedral, uma visita a cave e um almoço — é um dia perfeito.",t:["batevolta","vinho","história","arte","dia inteiro","imperdível"]},
{c:"paris",k:"batevolta",n:"Épernay — a Avenida de Champagne",o:"Épernay",a:"Marne (1h20)",d:"Dia inteiro",p:"€€",w:"A capital do champagne, com a Avenue de Champagne — uma avenida inteira sob a qual estão mais de 100 km de galerias com milhões de garrafas. Menos monumental que Reims e mais dedicada à bebida, com a casa Moët & Chandon e a Perrier-Jouët. Fácil de combinar com Reims no mesmo dia.",t:["batevolta","vinho","dia inteiro"]},
{c:"paris",k:"batevolta",n:"Rouen",o:"Rouen",a:"Normandia (1h15)",d:"Dia inteiro",p:"€€",w:"A cidade da catedral que Monet pintou 30 vezes, com o Gros-Horloge, a praça do mercado velho onde Joana d'Arc foi queimada e as ruas de casas enxaimel. 1h15 de trem da Gare Saint-Lazare. Boa combinação com o Museu de Belas Artes, que tem impressionistas de primeira linha.",t:["batevolta","história","arte","arquitetura"]},
{c:"paris",k:"batevolta",n:"Chartres",o:"Chartres",a:"Eure-et-Loir (1h)",d:"Meio dia",p:"€€",w:"A catedral gótica mais bem preservada da França, com 176 vitrais originais do século XIII cobrindo 2.600 m² — e o famoso labirinto no chão da nave. 1h de trem da Gare Montparnasse. Bom para meio dia, e a cidade antiga em volta vale uma volta a pé.",t:["batevolta","história","arte","meio-dia"]},
{c:"paris",k:"batevolta",n:"Auvers-sur-Oise — a trilha de Van Gogh",o:"Auvers-sur-Oise",a:"Val-d'Oise (1h)",d:"Dia inteiro",p:"€",w:"A vila onde Van Gogh passou seus últimos 70 dias e pintou 80 quadros, incluindo a igreja e o campo de trigo com corvos. Há um circuito de caminhada sinalizado entre os lugares pintados, o cemitério onde ele e Theo estão enterrados e a pousada Ravoux, onde morreu. Trilha de verdade com contexto artístico — combinação difícil de bater.",t:["batevolta","trilha","arte","caminhada","imperdível"]},
{c:"paris",k:"batevolta",n:"Vaux-le-Vicomte",o:"Château de Vaux-le-Vicomte",a:"Seine-et-Marne (1h)",d:"Meio dia",p:"€€",w:"O castelo de Fouquet, o ministro das finanças que foi preso depois de dar uma festa tão espetacular que Luís XIV ficou com ciúmes — e contratou os mesmos três artistas (Le Vau, Le Nôtre, Le Brun) para fazer Versailles. Dizem que é Versailles em tamanho humano. Costuma ter visita à noite com velas na temporada — confirme.",t:["batevolta","história","jardim","arquitetura"]},
{c:"paris",k:"batevolta",n:"Provins — cidade medieval",o:"Provins",a:"Seine-et-Marne (1h30)",d:"Dia inteiro",p:"€€",w:"Cidade medieval murada e Patrimônio Mundial, com a Tour César, a gruta dos cordeiros, as muralhas e as ruas de feira onde se realizava uma das maiores feiras da Europa medieval. Há espetáculos de falcoaria e de cavaleiros. 1h30 de trem da Gare de l'Est, e quase nenhum turista estrangeiro.",t:["batevolta","história","arquitetura","família"]},
{c:"paris",k:"batevolta",n:"Lille",o:"Lille",a:"Norte (1h de TGV)",d:"Dia inteiro",p:"€€",w:"Cidade flamenga com praça central colorida, casas de tijolos, cerveja local, o museu de belas artes (que é excelente) e a cultura do estaminet — bistrô flamengo com prato de carbonnade e cerveja. 1h de TGV. Boa opção de dia frio e chuvoso, porque tudo é perto e há muito indoor.",t:["batevolta","arquitetura","cerveja","comida","chuva"]},
{c:"paris",k:"batevolta",n:"Bruxelas ou Londres no mesmo dia (Eurostar)",o:"Bruxelles / London",a:"Eurostar",d:"Dia inteiro",p:"€€€",w:"Da Gare du Nord saem Eurostar para Bruxelas em ~1h20 e para Londres em ~2h15 — as duas cidades cabem num dia. Bruxelas é mais barata e rápida (Grand-Place, museus, cerveja e chocolate); Londres exige passaporte/ETA e é mais caro, mas rende um dia completo. Compre com antecedência, senão o preço dobra.",t:["batevolta","dia inteiro","internacional","trem"]},
/* ---------- COLÔNIA · SÓ NESTA DATA ---------- */
{c:"colonia",k:"data",n:"11/11 — Abertura da sessão de Carnaval (11h11)",o:"Karnevalsbeginn",a:"Alter Markt / Heumarkt",d:"Dia todo",p:"Grátis",w:"Às 11h11 do dia 11 de novembro começa a sessão de Carnaval de Colônia, e a cidade inteira para. No Alter Markt, ao lado do Dom, acontece a cerimônia que abre oficialmente o Fastelovend, com os Jecken fantasiados, banda e o grito ritual “Kölle Alaaf!”. É uma das festas populares mais antigas da Europa e acontece exatamente no dia em que você estará na cidade.",t:["evento","festa","ao ar livre","imperdível","gratuito"]},
{c:"colonia",k:"data",n:"Festas de Carnaval da noite de 11/11",o:"Karnevalspartys",a:"Zülpicher Str. / Heumarkt / Ehrenfeld",d:"Noite toda",p:"€–€€€",w:"Depois da festa de rua, a noite tem festas de Carnaval em toda a cidade: as clássicas nos ginásios e salões (com banda ao vivo e música kölsch), as festas de rua entre Heumarkt e Zülpicher Straße e as versões alternativas em Ehrenfeld e nos clubes. Escolha por perfil de público e compre antes — quase tudo esgota.",t:["evento","festa","balada","noite","imperdível"]},
{c:"colonia",k:"data",n:"Regras de segurança do 11/11",o:"Sicherheitsregeln",a:"Centro e Zülpicher Straße",d:"—",p:"—",w:"Todo ano a prefeitura aplica regras no centro e na Zülpicher Straße: proibição de garrafas de vidro e latas em determinadas áreas, restrição de mochilas grandes, controle de acesso com revista em zonas específicas e mais policiamento. Leve o celular carregado, documento, dinheiro em espécie, copo não-vidro e nada de mochila grande. Confira as regras do ano no site da cidade e da polícia na véspera.",t:["evento","aviso","segurança","verificar"]},

/* ---------- COLÔNIA · ARTE & MUSEUS ---------- */
{c:"colonia",k:"arte",n:"Catedral de Colônia e o tesouro",o:"Kölner Dom",a:"Altstadt (Innenstadt)",d:"2h",p:"Grátis (torre e tesouro pagos)",w:"A maior catedral gótica da Alemanha, 157 m, iniciada em 1248 e concluída só em 1880 — Patrimônio Mundial e o monumento mais visitado do país. Entre de graça, desça à cripta, suba os 533 degraus da torre sul para a vista mais completa da cidade e visite o tesouro da catedral. Em novembro há bem menos fila.",t:["arte","história","vista","grátis","imperdível"]},
{c:"colonia",k:"arte",n:"Museum Ludwig",o:"Museum Ludwig",a:"Innenstadt (perto do Dom)",d:"2–3h",p:"€€",w:"Um dos melhores museus de arte moderna da Alemanha: a maior coleção de pop art fora dos Estados Unidos (Warhol, Lichtenstein), Expressionismo alemão, Picasso e a coleção de fotografia. Fica literalmente ao lado da catedral, então é parada obrigatória no dia do centro.",t:["arte","chuva","moderno","imperdível"]},
{c:"colonia",k:"arte",n:"Museu Romano-Germânico",o:"Römisch-Germanisches Museum",a:"Innenstadt",d:"1h30",p:"€€",w:"Colônia foi uma das maiores cidades do Império Romano (Colonia Claudia Ara Agrippinensium). O museu guarda o impressionante mosaico de Dionísio descoberto no lugar e o túmulo de Poblicius, mais vidro, moeda e utensílio romano. ATENÇÃO: está fechado para reforma há anos, com reabertura prevista só depois de 2030 — parte do acervo aparece em exposições temporárias; confirme onde antes de ir.",t:["arte","história","chuva","fechado"]},
{c:"colonia",k:"arte",n:"Kolumba",o:"Kolumba (Museum des Erzbistums)",a:"Innenstadt",d:"1h30",p:"€€",w:"O museu da arquidiocese projetado por Peter Zumthor em cima das ruínas de uma igreja gótica destruída na guerra — a arquitetura é luminosa e silenciosa, com paredes de tijolo perfurado. O acervo mistura arte contemporânea com obras sacras de 2.000 anos. Um dos espaços mais bonitos de Colônia e pouco conhecido.",t:["arte","arquitetura","chuva","calmo","imperdível"]},
{c:"colonia",k:"arte",n:"EL-DE-Haus — centro de documentação do nazismo",o:"NS-Dokumentationszentrum",a:"Innenstadt",d:"2h",p:"€ (grátis em algumas condições)",w:"A sede da Gestapo em Colônia, com as celas dos presos no subsolo, com inscrições originais feitas nas paredes, e uma exposição sobre o nazismo e a perseguição em Colônia. É o memorial mais forte da cidade — a inscrição de um prisioneiro nas paredes é de partir o coração.",t:["história","memória","forte","chuva","solo"]},
{c:"colonia",k:"arte",n:"Schokoladenmuseum",o:"Schokoladenmuseum",a:"Rheinauhafen",d:"1h30",p:"€€",w:"Museu do chocolate dentro do Rheinauhafen, com a história do cacau desde os astecas, uma fábrica de vidro em funcionamento (com fonte de chocolate), degustação e vista do Reno pela janela. Turístico, mas bem feito e ótimo com frio — termina com compras na loja.",t:["chuva","família","comida","turístico"]},
{c:"colonia",k:"arte",n:"Wallraf-Richartz-Museum",o:"Wallraf-Richartz-Museum",a:"Innenstadt",d:"2h",p:"€€",w:"Pintura do medieval ao impressionismo: mestres de Colônia (Stefan Lochner), Rubens, Rembrandt e uma coleção francesa do século XIX que surpreende para uma cidade alemã. Praticamente sem turista estrangeiro e do lado do Rathaus.",t:["arte","chuva"]},
{c:"colonia",k:"arte",n:"Museum Schnütgen",o:"Museum Schnütgen",a:"Innenstadt (St. Cäcilien)",d:"1h",p:"€€",w:"Arte sacra medieval instalada dentro de uma igreja românica do século XII, com esculturas, vitrais, marfins e têxteis expostos de forma muito moderna, com iluminação cuidadosa. Um museu pequeno e elegante que quase ninguém visita.",t:["arte","chuva","escondido","religioso"]},
{c:"colonia",k:"arte",n:"KölnTriangle — mirante",o:"KölnTriangle",a:"Deutz (outra margem)",d:"45min",p:"€",w:"Torre do outro lado do rio com mirante panorâmico: é de lá que sai a foto clássica de Colônia, com a catedral, a ponte de ferro e o rio no mesmo quadro. Barato, rápido e melhor no fim do dia, quando a cidade acende e a catedral fica iluminada.",t:["vista","pôr do sol","noite","barato","fotografia"]},
{c:"colonia",k:"arte",n:"Rautenstrauch-Joest-Museum",o:"Rautenstrauch-Joest-Museum",a:"Innenstadt",d:"2h",p:"€€",w:"Museu etnológico com acervo das Américas, Ásia, África e Oceania, reformulado recentemente para encarar de frente a questão colonial e a proveniência das peças. Boa visita para pensar cultura material e colecionismo — bem diferente de museu de arte tradicional.",t:["arte","cultura","chuva","reflexivo"]},

/* ---------- COLÔNIA · HISTÓRIA & MONUMENTOS ---------- */
{c:"colonia",k:"historia",n:"Hohenzollernbrücke — a ponte dos cadeados",o:"Hohenzollernbrücke",a:"Entre o Dom e Deutz",d:"30min",p:"Grátis",w:"A ponte de ferro com centenas de milhares de cadeados de amor presos nas grades, atravessada por trens, pedestres e ciclistas, com a catedral atrás. Caminhe até a outra margem, olhe para trás e volte — é o passeio obrigatório de Colônia e é gratuito.",t:["ao ar livre","grátis","caminhada","fotografia","ícone"]},
{c:"colonia",k:"historia",n:"Altstadt e Alter Markt",o:"Altstadt / Alter Markt",a:"Innenstadt",d:"2h",p:"Grátis",w:"O centro histórico reconstruído, com o Alter Markt (onde o Carnaval começa), o Rathaus com a torre medieval, a praça Roncalliplatz e as cervejarias históricas. Muito turístico e muito vivo — bom para uma caminhada de fim de tarde terminando numa Brauhaus.",t:["caminhada","ao ar livre","grátis","história"]},
{c:"colonia",k:"historia",n:"Rheinauhafen — docas e gruas históricas",o:"Rheinauhafen",a:"Südstadt",d:"1h30",p:"Grátis",w:"O porto histórico reformado em bairro de arquitetura contemporânea: os três edifícios em forma de guindaste (Kranhäuser), os antigos galpões de carga, a roda-gigante e a passarela sobre o Reno. Caminhada plana e bonita, com o museu do chocolate na ponta. Bom para o fim do dia.",t:["caminhada","ao ar livre","arquitetura","grátis","rio"]},
{c:"colonia",k:"historia",n:"Melaten-Friedhof",o:"Melaten-Friedhof",a:"Lindenthal",d:"1h30",p:"Grátis",w:"O cemitério principal de Colônia, com quase 200 anos, árvores antigas e túmulos monumentais de famílias industriais e artistas. Funciona como parque e como museu histórico a céu aberto — solene, silencioso e sem turista nenhum.",t:["ao ar livre","grátis","história","solo","calmo"]},
{c:"colonia",k:"historia",n:"Denkmal für die Opfer des Nationalsozialismus e memoriais do centro",o:"Gedenkstätten",a:"Innenstadt",d:"1h",p:"Grátis",w:"Memoriais no centro e na Catedral para as vítimas do nazismo, incluindo as placas dos judeus de Colônia deportados e as pedras de tropeço (Stolpersteine) espalhadas pelas calçadas, à frente das casas de quem foi deportado. Andar pelo centro prestando atenção no chão é uma experiência por si só.",t:["história","grátis","caminhada","memória","solo"]},
{c:"colonia",k:"historia",n:"Haus 4711 e a história da água de colônia",o:"4711-Haus",a:"Glockengasse",d:"30min",p:"Grátis",w:"A casa onde nasceu a Água de Colônia, com o número 4711 que virou nome da marca, e o museu da fragrância. Existe também a Fragrance Museum Farina, onde o perfumista italiano Giovanni Maria Farina inventou a receita em 1709. Duas casas, a mesma história, e um souvenir muito mais interessante que o habitual.",t:["história","grátis","compras","souvenir"]},
{c:"colonia",k:"historia",n:"Trude-Herr-Denkmal e a memória cultural de Colônia",o:"Denkmäler im Altstadt",a:"Innenstadt",d:"30min",p:"Grátis",w:"Colônia tem estátuas e memoriais espalhados por toda parte — de Trude Herr, compositora e atriz da cidade, ao monumento do Carnaval. Passeio curto para entender o orgulho local e a cultura popular da cidade, que se define como “Kölle” antes de “Alemanha”.",t:["história","grátis","caminhada","cultura"]},
{c:"colonia",k:"historia",n:"Museu da Cidade (Zeughaus / Kölnisches Stadtmuseum)",o:"Kölnisches Stadtmuseum",a:"Innenstadt",d:"1h30",p:"€€",w:"A história de Colônia do Império Romano ao século XX, no antigo arsenal da cidade, com objetos do Carnaval, da ocupação e do cotidiano. Confirme a situação atual — o museu passou por fechamento e reforma, com acervo em exibição provisória.",t:["história","chuva","verificar"]},
/* ---------- COLÔNIA · BAIRROS & CAMINHADA ---------- */
{c:"colonia",k:"bairro",n:"Belgian Quarter (Brüsseler Platz)",o:"Belgisches Viertel",a:"Innenstadt (oeste)",d:"2h",p:"Grátis",w:"O bairro mais gostoso de Colônia para andar: ruas com prédios do início do século XX, cafés, bares de esquina, restaurantes e a Brüsseler Platz, que vira ponto de encontro ao ar livre no fim do dia (e onde o Carnaval também acontece). É onde os moradores levam a vida — não os turistas.",t:["caminhada","ao ar livre","bar","comida","local","imperdível"]},
{c:"colonia",k:"bairro",n:"Ehrenfeld",o:"Ehrenfeld",a:"Ehrenfeld",d:"2h30",p:"Grátis",w:"O bairro que virou o epicentro alternativo e criativo de Colônia, com antigas fábricas ocupadas por ateliês, clubes, galerias, bares e o Bürgerhaus. Muita coisa acontece ali. É o lado mais cru e mais interessante da cidade, especialmente à noite.",t:["caminhada","alternativo","arte","noite"]},
{c:"colonia",k:"bairro",n:"Agnesviertel",o:"Agnesviertel",a:"Innenstadt (norte)",d:"1h30",p:"Grátis",w:"Bairro elegante e tranquilo ao redor da igreja de Santa Agnes, com ruas largas, cafés, galerias pequenas e restaurantes. Menos badalado que o Belgian Quarter, com moradores de perfil mais velho e uma sensação de calma em plena cidade.",t:["caminhada","calmo","café","comida"]},
{c:"colonia",k:"bairro",n:"Kwartier Latäng (Zülpicher Straße)",o:"Kwartier Latäng",a:"Sülz / Innenstadt",d:"1h30",p:"Grátis",w:"O bairro universitário de Colônia, com bares baratos, döner, pubs irlandeses, clubes pequenos e vida noturna intensa na Zülpicher Straße. É aqui que acontece boa parte da festa de rua do Carnaval de 11/11. Ambiente jovem e barato, com muita gente na rua até tarde.",t:["caminhada","noite","barato","bar","festa"]},
{c:"colonia",k:"bairro",n:"Severinsviertel",o:"Severinsviertel",a:"Südstadt",d:"1h30",p:"Grátis",w:"Bairro histórico ao sul do centro, com a Severinstraße cheia de lojas, cervejarias antigas e a Severinstorburg, uma das portas medievais da cidade. Menos turístico, mais cotidiano, com clima de bairro tradicional e prédios bonitos.",t:["caminhada","história","comida","local"]},
{c:"colonia",k:"bairro",n:"Eigelstein e a volta dos anéis (Ringe)",o:"Eigelstein / Ringe",a:"Innenstadt (norte)",d:"1h30",p:"Grátis",w:"Região de imigrantes turcos e curdos, com mercado, restaurantes, lojas de comida do Oriente Médio e a Eigelsteintorburg, outra porta medieval. Dali saem os bulevares em anel (Ringe) que substituíram as muralhas, hoje o circuito de caminhada e corrida da cidade.",t:["caminhada","comida","mercado","local"]},

/* ---------- COLÔNIA · TRILHAS & NATUREZA ---------- */
{c:"colonia",k:"natureza",n:"Siebengebirge e o Drachenfels",o:"Siebengebirge / Drachenfels",a:"Königswinter (~1h)",d:"Dia inteiro",p:"€€ (trem)",w:"As sete montanhas ao sul de Colônia, com a subida ao Drachenfels (Rocha do Dragão), 321 m, e vista ampla do vale do Reno — há um trem de cremalheira histórico que sobe se você não quiser caminhar. Passa por castelos, ruínas e vinhedos. A melhor trilha a um dia de Colônia, com retorno de trem de Königswinter.",t:["trilha","natureza","vista","batevolta","dia inteiro","imperdível"]},
{c:"colonia",k:"natureza",n:"Rheinsteig — trechos do vale do Reno",o:"Rheinsteig",a:"Vale do Reno (~1h)",d:"Dia inteiro",p:"€ (trem)",w:"Trilha de longa distância de 320 km pela margem direita do Reno, com trechos de um dia entre Königswinter, Bad Honnef, Unkel e Linz, passando por castelos, vinhedos em encosta e vilarejos. Sinalizada e acessível por trem regional em pontas diferentes. Em novembro, com neblina sobre o rio, fica bonito de verdade.",t:["trilha","natureza","dia inteiro","batevolta","rio"]},
{c:"colonia",k:"natureza",n:"Nationalpark Eifel",o:"Nationalpark Eifel",a:"Eifel (~1h30)",d:"Dia inteiro",p:"€€ (trem)",w:"Parque nacional de floresta, represas e vilarejos a 1h30 de Colônia, com trilhas sinalizadas e possibilidade de ver cervo e javali ao amanhecer. A paisagem é de colina arredondada e floresta densa. Vá cedo e leve comida — a estrutura de restaurante é esparsa em novembro.",t:["trilha","natureza","dia inteiro","batevolta","solo"]},
{c:"colonia",k:"natureza",n:"Kottenforst e Ville — trilhas na porta de Colônia",o:"Kottenforst / Ville",a:"Bonn / Köln (S-Bahn)",d:"3–4h",p:"€ (transporte)",w:"Grande floresta entre Colônia e Bonn, com trilhas planas e largas, incluindo o antigo caminho de caça dos príncipes eleitores, mais a serra baixa da Ville, onde havia mineração de lignito. Acesso fácil por S-Bahn. Ideal para uma caminhada longa sem pegar trem para longe.",t:["trilha","natureza","fácil","solo","batevolta"]},
{c:"colonia",k:"natureza",n:"Wahner Heide",o:"Wahner Heide",a:"Perto do aeroporto",d:"3h",p:"Grátis",w:"Reserva natural de heath e areia na periferia de Colônia, um dos últimos trechos de paisagem de charneca do oeste da Alemanha, com trilhas marcadas, pinheiros anões e áreas de areia branca. Muito perto da cidade e quase sem turista.",t:["trilha","natureza","grátis","fácil"]},
{c:"colonia",k:"natureza",n:"Königsforst",o:"Königsforst",a:"Leste de Colônia",d:"2–3h",p:"Grátis",w:"Floresta de bosque misto a leste da cidade, com trilhas amplas, lagos e caminhos usados por corredores e ciclistas. Chega-se de S-Bahn ou bike. Boa caminhada de meio dia, sem sair da região metropolitana.",t:["trilha","natureza","grátis","bicicleta","fácil"]},
{c:"colonia",k:"natureza",n:"Margem do Reno até Bonn, a pé ou de bicicleta",o:"Rheinuferweg",a:"Köln → Bonn",d:"Dia inteiro",p:"Grátis",w:"O caminho de pedestres que acompanha o Reno pela margem esquerda, entre Colônia e Bonn, passa por bairros, praias fluviais, o Rheinauhafen, o porto e a antiga capital. São cerca de 30 km de percurso plano — dá para fazer um trecho e voltar de trem ou S-Bahn, que seguem o mesmo rio.",t:["caminhada","bicicleta","rio","ao ar livre","grátis","batevolta"]},
{c:"colonia",k:"natureza",n:"Bergisches Land e a represa de Rur",o:"Bergisches Land / Rurtalsperre",a:"Leste (~1h15)",d:"Dia inteiro",p:"€€ (trem)",w:"Região de colinas, vales, represas e florestas a leste de Colônia, com circuitos de trilha ao redor da água e vilarejos de casas em xadrez cinza. Muito menos visitada que o vale do Reno e igualmente bonita. Boa para trilha de dia inteiro em terreno variado.",t:["trilha","natureza","dia inteiro","batevolta","água"]},

/* ---------- COLÔNIA · COMIDA & BEBIDA ---------- */
{c:"colonia",k:"comida",n:"Brauhaus e o rito do Kölsch",o:"Früh / Sion / Päffgen / Peters",a:"Innenstadt / Südstadt",d:"2h",p:"€€",w:"Em Colônia não se pede cerveja: o garçom (Köbes) traz Kölsch em copos de 0,2 litro e continua trazendo enquanto você não cobrir o copo com o porta-copo — só então ele para e conta. As cervejarias Früh am Dom, Sion, Päffgen e Peters Brauhaus fazem isso desde o século XIX, com cozinha local. É o programa mais autenticamente coloniense que existe.",t:["comida","cerveja","tradição","ícone","imperdível"]},
{c:"colonia",k:"comida",n:"Pratos colonienses: Halver Hahn, Himmel un Ääd, Sauerbraten",o:"Kölner Küche",a:"Innenstadt",d:"1h30",p:"€€",w:"A cozinha de Colônia tem personalidade própria: o Halver Hahn (pão de centeio com queijo Gouda e mostarda, apesar do nome, não tem frango), o Himmel un Ääd (purê de maçã com batata e morcela, “céu e terra”), o Sauerbraten com molho de passas e a Rievkooche (bolinho de batata) com compota de maçã. Peça tudo numa Brauhaus.",t:["comida","tradição","local","imperdível"]},
{c:"colonia",k:"comida",n:"Kölsch-Wanderung — rota de cervejarias a pé",o:"Kölsch-Tour",a:"Innenstadt / Südstadt",d:"3h",p:"€€",w:"Circuito a pé entre quatro ou cinco cervejarias históricas no centro e no Severinsviertel, tomando um Kölsch em cada uma — a tradição local é exatamente essa. Existem tours guiados (em inglês) e dá para fazer sozinho usando um mapa. Cada parada tem sua própria marca de Kölsch.",t:["comida","cerveja","caminhada","grupo","local"]},
{c:"colonia",k:"comida",n:"Mercados e Wochenmarkt",o:"Wochenmärkte",a:"Rathenauplatz / Neumarkt / Ehrenfeld",d:"1h",p:"€",w:"As feiras semanais de bairro são onde Colônia compra: queijos, pão, azeitonas, flores, linguiça, frutas da estação e barracas de comida quente. A do Rathenauplatz e a de Ehrenfeld são as mais agradáveis. Manhã, barato e sem turista.",t:["comida","mercado","barato","manhã","local"]},
{c:"colonia",k:"comida",n:"Waffeln, Reibekuchen e doces de feira",o:"Kölner Süßes",a:"Innenstadt / feiras",d:"30min",p:"€",w:"Em novembro começa a temporada de barracas de Reibekuchen (bolinho de batata frito) com compota de maçã, waffeln com cereja quente e chocolates de Natal. Coma na rua, em pé, com o frio — é o jeito certo. Barato e boa pausa no meio da caminhada.",t:["comida","barato","ao ar livre","frio","pausa"]},
{c:"colonia",k:"comida",n:"Cafés e Konditorei do Belgian Quarter",o:"Belgisches Viertel Cafés",a:"Belgisches Viertel / Agnesviertel",d:"1h",p:"€€",w:"Café da manhã alemão longo, com pão, queijo, presunto, ovo e café de filtro em quantidade, é uma instituição — e no Belgian Quarter e no Agnesviertel há várias casas de bairro boas para isso, com jornal na mesa e ninguém apressando você. Bom para o dia seguinte ao Carnaval.",t:["café","manhã","comida","local"]},

/* ---------- COLÔNIA · BALADA & MÚSICA AO VIVO ---------- */
{c:"colonia",k:"balada",n:"Bootshaus",o:"Bootshaus",a:"Deutz (margem do Reno)",d:"Noite toda",p:"€€",w:"Um dos melhores clubes de música eletrônica da Alemanha segundo a imprensa especializada, com três pistas, som pesado e vista do Reno. Programa techno, bass, drum'n'bass e dubstep com nomes internacionais. Vale reservar ingresso online — as festas grandes esgotam.",t:["techno","noite","madrugada","imperdível"]},
{c:"colonia",k:"balada",n:"Odonien",o:"Odonien",a:"Ehrenfeld",d:"Noite toda",p:"€€",w:"Espaço cultural alternativo em Ehrenfeld, com esculturas mecânicas, sucata transformada em arte, pátio externo e festas que vão do techno ao funk. É o lugar mais “underground” de Colônia e uma das melhores surpresas da cidade — a decoração sozinha já vale.",t:["techno","noite","alternativo","arte"]},
{c:"colonia",k:"balada",n:"Gebäude 9",o:"Gebäude 9",a:"Deutz",d:"Noite",p:"€€",w:"Antigo prédio industrial em Deutz que virou casa de shows e clube, com programação de indie, rock, eletrônica e festas temáticas. Tamanho médio, boa acústica, público que vai pela música. Um dos espaços mais consistentes da cidade.",t:["shows","noite","indie","rock"]},
{c:"colonia",k:"balada",n:"Stadtgarten",o:"Stadtgarten",a:"Innenstadt (norte)",d:"Noite",p:"€€",w:"Café, restaurante, casa de shows e clube num parque no centro, tocando jazz, soul, world e eletrônica em salas diferentes. Tem jardim de cerveja no verão e programação o ano inteiro. Bom para uma noite em que você quer música ao vivo sem ambiente de balada.",t:["jazz","shows","noite","parque"]},
{c:"colonia",k:"balada",n:"Blue Shell, King Georg e os clubes de Ehrenfeld",o:"Blue Shell / King Georg / Artheater",a:"Ehrenfeld / Innenstadt",d:"Noite",p:"€–€€",w:"O circuito alternativo de Colônia: a Blue Shell é rock, garage e blues num porão histórico; o King Georg é pequeno e mistura música ao vivo, DJ e cabaré; o Artheater tem programação eclética e pista. Baratos, com gente de bairro e sem turista.",t:["rock","noite","alternativo","barato","shows"]},
{c:"colonia",k:"balada",n:"A noite LGBTQIA+ da Schaafenstraße",o:"Schaafenstraße",a:"Innenstadt (Kwartier Latäng)",d:"Noite toda",p:"€–€€",w:"Colônia tem uma das cenas LGBTQIA+ mais antigas e ativas da Alemanha, concentrada nas ruas Schaafenstraße e Pipinstraße, com bares, clubes e festas — incluindo o Charlys, o Lux e outros, além de festas maiores. Apesar de Colônia ter tradição progressista, a cena é mais de bares que de clubes enormes.",t:["queer","noite","bar","gay-friendly"]},

/* ---------- COLÔNIA · PALCO, ÓPERA & CONCERTOS ---------- */
{c:"colonia",k:"palco",n:"Kölner Philharmonie",o:"Kölner Philharmonie",a:"Innenstadt (perto do Dom)",d:"2h",p:"€€–€€€",w:"Sala de concerto moderna embaixo da praça Heinrich-Böll-Platz, entre o Dom e o museu Ludwig, com acústica reconhecida e programação de orquestra filarmônica, recitais e concertos contemporâneos. Preços acessíveis e lugar bom na plateia em praticamente qualquer assento.",t:["concerto","erudito","noite","imperdível"]},
{c:"colonia",k:"palco",n:"Oper Köln",o:"Oper Köln",a:"Innenstadt (Offenbachplatz)",d:"3h",p:"€€–€€€€",w:"A ópera da cidade, com repertório clássico e encenações contemporâneas, Depois de 15 anos de reforma, a casa voltou ao Offenbachplatz na temporada 2026/27 — confirme no site qual sala está em uso na sua data e garanta ingresso, porque novembro enche. Ingressos de última hora costumam sair baratos.",t:["ópera","erudito","noite"]},
{c:"colonia",k:"palco",n:"Schauspiel Köln, Comedia e Senftöpfchen",o:"Theater in Köln",a:"Innenstadt / Südstadt",d:"2h30",p:"€€",w:"O Schauspiel Köln é o teatro dramático da cidade, com encenações em alemão e produções fortes; a Comedia e o Senftöpfchen são casas de comédia, cabaré político e pequenos musicais, com programação em alemão e ambiente intimista. Para a segunda opção, algum alemão ajuda — mas o formato é divertido mesmo sem entender tudo.",t:["teatro","comédia","noite"]},
/* ---------- COLÔNIA · EXPERIÊNCIA ÚNICA ---------- */
{c:"colonia",k:"unica",n:"Claudius Therme — spa à beira do Reno",o:"Claudius Therme",a:"Riehl",d:"3–4h",p:"€€€",w:"Complexo termal com piscinas internas e externas aquecidas, saunas (temperatura variada, incluindo finlandesa e bio), jacuzzis e área de descanso com vista do Reno. A piscina externa com a neblina saindo da água no frio de novembro é a melhor coisa depois de um dia de andança. Padrão alemão: saunas sem roupa.",t:["spa","relaxar","frio","imperdível"]},
{c:"colonia",k:"unica",n:"Passeio de barco no Reno (KD)",o:"Rheinschifffahrt / KD",a:"Partidas do centro",d:"1h–4h",p:"€€",w:"A Köln-Düsseldorfer opera passeios pelo Reno saindo de Colônia: opções curtas de uma hora pelo porto e pela cidade, e trechos mais longos subindo o rio até Königswinter e Bonn, passando por castelos, vinhedos e pelo Drachenfels. Em novembro os barcos são fechados e aquecidos. Programão de frio com vista.",t:["rio","vista","chuva","relaxar"]},
{c:"colonia",k:"unica",n:"Estádio do FC Köln e a cultura de futebol",o:"RheinEnergieStadion",a:"Müngersdorf",d:"3h",p:"€€",w:"Colônia é cidade de futebol e o FC Köln tem a maior torcida de arquibancada da Alemanha em proporção. Ver um jogo no RheinEnergieStadion — mesmo em partida modesta — significa cantar, tomar Kölsch e ouvir o estádio inteiro gritar “Kölle”. Confira o calendário da Bundesliga e compre pelo site oficial de revenda. Se não houver jogo, há tour pelo estádio.",t:["evento","esporte","grupo","local"]},
{c:"colonia",k:"unica",n:"Tour de cervejaria artesanal e Kölsch-Wanderung guiada",o:"Brauereiführung",a:"Ehrenfeld / Innenstadt",d:"3h",p:"€€",w:"Tours guiados (alguns em inglês) que visitam cervejarias artesanais e históricas, explicam a diferença entre Kölsch e Altbier, e terminam com degustação. Há também as visitas às grandes casas do centro. Bom jeito de entender a cidade por dentro, com gente local.",t:["comida","cerveja","aula","grupo","noite"]},

/* ---------- COLÔNIA · COMPRAS & MERCADOS ---------- */
{c:"colonia",k:"compras",n:"Compras de bairro no Belgian Quarter e Ehrenfeld",o:"Belgisches Viertel / Ehrenfeld",a:"Innenstadt / Ehrenfeld",d:"2h",p:"€–€€",w:"Lojas independentes, brechós, lojas de disco, design de autor e marcas alemãs pequenas espalhadas pelo Belgian Quarter e por Ehrenfeld. Muito mais interessante que a rua comercial do centro. Procure a Aachener Straße, a Venloer Straße e as ruas paralelas.",t:["compras","vintage","design","vinil","local"]},
{c:"colonia",k:"compras",n:"Souvenirs que valem a pena",o:"Kölner Mitbringsel",a:"Innenstadt",d:"1h",p:"€–€€",w:"Colônia tem souvenirs melhores que o padrão alemão: água de colônia 4711 e as criações da Farina, Kölsch em garrafa, mostarda de Colônia (Kölner Senf), chocolate do Schokoladenmuseum, bretzel e a porcelana/cerâmica com o brasão da cidade. A Glockengasse e as ruas perto do Dom concentram as lojas.",t:["compras","souvenir","comida","barato"]},

/* ---------- COLÔNIA · NOTURNO & VISTAS ---------- */
{c:"colonia",k:"noturno",n:"Passeio noturno no Reno com o centro iluminado",o:"Rhein bei Nacht",a:"Margem do Reno",d:"1h30",p:"Grátis",w:"A caminhada pela margem do Reno, de Deutz até o Rheinauhafen, com o skyline do centro iluminado refletido na água, a catedral acesa, os trens atravessando a Hohenzollernbrücke e os Kranhäuser no fim. Gratuito, plano e bonito em qualquer temperatura — só leve um casaco de verdade.",t:["noite","ao ar livre","grátis","caminhada","fotografia","imperdível"]},
{c:"colonia",k:"noturno",n:"Roda-gigante do Rheinauhafen",o:"Riesenrad",a:"Rheinauhafen",d:"45min",p:"€€",w:"Roda-gigante instalada no porto histórico, com vista noturna do centro, do rio e da catedral. ATENÇÃO: é sazonal, e a temporada de 2026 vai de 14/05 a 06/09 — em novembro ela não está em operação. Se as datas da viagem mudarem, vale conferir.",t:["noite","vista","fotografia","fechado","família"]},

/* ---------- COLÔNIA · BATE-VOLTA ---------- */
{c:"colonia",k:"batevolta",n:"Düsseldorf",o:"Düsseldorf",a:"30–40min de trem",d:"Dia inteiro",p:"€€",w:"A vizinha elegante: Altstadt (a “barra mais longa do mundo”, com mais de 260 bares), Königsallee com o canal e as lojas de luxo, o Medienhafen com os edifícios inclinados de Frank Gehry e os museus Kunstpalast e K21 (este com uma obra no teto em que dá para andar). 30 minutos de trem — é o bate-volta mais fácil de Colônia.",t:["batevolta","arte","arquitetura","bar","comida","imperdível"]},
{c:"colonia",k:"batevolta",n:"Bonn",o:"Bonn",a:"25min de trem",d:"Dia inteiro",p:"€€",w:"A antiga capital da Alemanha Ocidental: a Museumsmeile (Haus der Geschichte, Bundeskunsthalle, Museum Koenig), a casa de Beethoven onde ele nasceu (com piano e partituras originais), a universidade no antigo palácio e a Rheinaue, parque enorme à beira do rio. Cidade de escala humana e sem multidão, 25 minutos de trem.",t:["batevolta","museu","história","música","jardim"]},
{c:"colonia",k:"batevolta",n:"Aachen",o:"Aachen",a:"1h de trem",d:"Dia inteiro",p:"€€",w:"A cidade de Carlos Magno, com a catedral onde 30 imperadores do Sacro Império foram coroados, o tesouro com o trono e as relíquias, a prefeitura gótica e as termas de água quente romanizadas (Carolus Thermen). Fronteira com a Bélgica e a Holanda — dá para cruzar três países a pé numa tarde.",t:["batevolta","história","arte","spa"]},
{c:"colonia",k:"batevolta",n:"Brühl — Augustusburg e Phantasialand",o:"Brühl",a:"20min de trem",d:"Meio dia",p:"€€–€€€€",w:"Duas opções completamente diferentes na mesma cidade: o Schloss Augustusburg, palácio rococó Patrimônio Mundial com escadaria monumental de Balthasar Neumann, e o Phantasialand, um dos maiores parques temáticos da Alemanha, com montanhas-russas premiadas. Escolha por perfil — ou faça o palácio de manhã e o parque se o clima estiver ruim para trilha.",t:["batevolta","história","parque","família"]},
{c:"colonia",k:"batevolta",n:"Wuppertal — o trem suspenso",o:"Wuppertal Schwebebahn",a:"45min de trem",d:"Meio dia",p:"€",w:"A cidade do trem suspenso mais antigo do mundo (1901), que corre pendurado sobre o rio Wupper por 13 km, balançando, a 12 metros do chão — é uma obra de engenharia e uma experiência em si. Aproveite para o Von der Heydt-Museum e o bairro histórico de Elberfeld.",t:["batevolta","arquitetura","curioso","meio-dia","chuva"]},
{c:"colonia",k:"batevolta",n:"Essen — Zeche Zollverein (UNESCO)",o:"Zeche Zollverein",a:"1h de trem",d:"Dia inteiro",p:"€€",w:"A mina de carvão mais bonita do mundo, fechada em 1986 e transformada em centro cultural Patrimônio Mundial: a estrutura de aço do poço XII, o museu da mineração (Ruhrmuseum), o centro de design (Red Dot) e a piscina de água quente no antigo prédio. Aula de arquitetura industrial e de como a Alemanha reinventou o Ruhr.",t:["batevolta","arquitetura","arte","história","chuva","imperdível"]},
{c:"colonia",k:"batevolta",n:"Duisburg — Landschaftspark Nord",o:"Landschaftspark Duisburg-Nord",a:"1h15 de trem",d:"Meio dia",p:"Grátis",w:"Uma antiga usina siderúrgica transformada em parque público: você caminha pelas passarelas dos altos-fornos, desce às galerias de coque, sobe na torre e vê a estrutura iluminada por luzes coloridas à noite. Entrada gratuita, surreal e impressionante — difícil acreditar que existe de graça.",t:["batevolta","arquitetura","grátis","fotografia","imperdível"]},
{c:"colonia",k:"batevolta",n:"Maastricht",o:"Maastricht",a:"1h30 de trem",d:"Dia inteiro",p:"€€",w:"Cidade holandesa a 1h30: praças com cafés, a basílica, as cavernas calcárias (grotten) e as fortificações, o rio Maas e uma cultura que não é alemã nem belga. O mercado de sexta e as ruas de compras são bons. Ótimo para um dia diferente, e você chega de trem sem baldeação difícil.",t:["batevolta","história","compras","internacional","comida"]},
{c:"colonia",k:"batevolta",n:"Vale do Mosel — Cochem",o:"Cochem / Mosel",a:"2h de trem",d:"Dia inteiro",p:"€€€",w:"O vale do Mosel é uma das paisagens de vinhedo mais bonitas da Alemanha: encostas em terraço, o rio fazendo curva, o castelo de Cochem no alto e cidades de enxaimel. Visite uma cave, prove o Riesling da região e caminhe entre vinhedos — em novembro é a época da colheita tardia e o vale está dourado.",t:["batevolta","vinho","trilha","paisagem","dia inteiro","imperdível"]},
{c:"colonia",k:"batevolta",n:"Koblenz e o Loreley",o:"Koblenz / Sankt Goar",a:"1h30–2h de trem",d:"Dia inteiro",p:"€€",w:"Koblenz fica na confluência do Reno com o Mosel (o Deutsches Eck), com fortaleza no alto e teleférico. Subindo o rio, o trecho mais famoso do vale do Reno passa pela rocha do Loreley, Patrimônio Mundial, com castelos em cada curva. Dá para combinar trem e barco num dia longo e muito recompensador.",t:["batevolta","rio","história","paisagem","dia inteiro"]},
{c:"colonia",k:"batevolta",n:"Bruxelas",o:"Bruxelles",a:"2h de trem",d:"Dia inteiro",p:"€€€",w:"A Grand-Place, os museus reais de belas artes (com Bruegel e Magritte), o Atomium, o bairro real e a comida — moules, waffle, chocolate, cerveja trapista. Duas horas de trem. Também pode ser feito como extensão da volta de Paris para Colônia, em vez de bate-volta de ida e volta.",t:["batevolta","arte","comida","cerveja","internacional","dia inteiro"]}
];
